INSERT INTO "public"."chapters" ("id", "story_id", "chapter_number", "title", "content", "created_at") VALUES (2, 2, 2, 'Chương 1: Dâng hàng', 'Tây Lương và Đại Lương có vị trí địa lý liền kề nhau. Suốt mấy chục năm qua, biên cảnh hai nước không ngừng xảy ra va chạm, đôi bên luôn dò xét thực hư, thăm dò thực lực của nhau.

Đầu năm nay, Tây Lương vương Thác Bạt Hoằng đích thân điều động gần mười vạn tướng sĩ, ý đồ một hơi nuốt trọn trọng thành nơi biên vực Đại Lương — Xích Phong. Vốn dĩ đó là một trận chiến tưởng như nắm chắc phần thắng, nào ngờ vì Trấn Tây đại tướng quân Hoắc Yếm của Đại Lương nghìn dặm gấp rút chi viện, cục diện chiến sự trong nháy mắt đảo ngược.

Hoắc Yếm, kẻ được người đời gọi là Diêm La mặt lạnh. Có hắn uy chấn phương Bắc, hoàng đế Đại Lương mới có thể ở thượng kinh an tâm kê cao gối, nghe nhạc thưởng múa.

Còn Tây Lương vương Thác Bạt Hoằng, trước thì khinh địch, sau lại nóng vội công thành, cuối cùng tổn binh hao tướng thảm trọng, thậm chí còn trúng tên vào ngực, suýt nữa mất mạng.

Đồng thời, trận chiến ấy cũng gần như vét cạn hơn phân nửa căn cơ của Tây Lương. Từ đó về sau, Tây Lương không còn cơ hội phản công Đại Lương nữa.

…

Ba tháng sau.

Trong nội viện hoàng cung Tây Lương, các vị phi tần mặt mày ủ rũ vây quanh trước giường bệnh của Thác Bạt Hoằng, lòng đầy lo lắng cho bệnh tình của vương thượng.

Thái y chẩn đoán, chứng bệnh này là do uất hỏa công tâm mà thành, cần tĩnh tâm điều dưỡng. Nếu không, vết thương trúng tên trước đó của vương thượng trên chiến trường e rằng sẽ có nguy cơ tái phát.

Bên cạnh giường, chẳng biết là vị nương nương nào vừa nghẹn ngào vừa khóc lóc oán trách một câu:

“Cái tên quỷ Diêm La đáng chém nghìn đao đến từ Đại Lương kia! Quả thật khinh người quá đáng! Làm bị thương đại vương của chúng ta còn chưa đủ, vậy mà còn thừa lúc chúng ta suy yếu, liên tiếp đoạt mất ba trọng thành nơi biên vực. Có phải hắn phải đánh đến tận Duy Viên mới chịu dừng tay không!”

Duy Viên, chính là đô thành của Tây Lương.

Lời này vừa thốt ra, sắc mặt mọi người đều khác nhau. Các nữ quyến đều lộ vẻ lo âu, còn mấy vị vương tử đang ngồi đó thì ai nấy đều phẫn uất không cam lòng.

Thác Bạt Hoằng vốn đang suy yếu nằm trên giường, hai mắt khép hờ, nghe vậy lại ho dữ dội hai tiếng, kéo theo lồng ngực chấn động mạnh.

“Phụ vương! Tên Hoắc Yếm kia thật sự khinh người quá đáng. Hắn thật sự tưởng nam nhi Tây Lương chúng ta đều chết hết rồi hay sao! Nhi thần nguyện dẫn năm vạn tinh binh, tiến đến giết bớt nhuệ khí của hắn!”

Đại vương tử Thác Bạt Xuyên một tay đặt trước ngực, quỳ một gối phía trước, thề rằng nhất định sẽ xách đầu Hoắc Yếm đến trước điện, rửa sạch mối nhục này.

Nhưng nếu lời này được nói ra vào ba tháng trước, tất nhiên sẽ khiến lòng người phấn chấn, cổ vũ sĩ khí. Còn hiện giờ, mười vạn tinh nhuệ Tây Lương đã gần như tổn thất một nửa nơi biên quan, cờ xí phủ bụi, sĩ khí sa sút, lấy đâu ra ý chí để tiếp tục đánh một trận được ăn cả ngã về không?

Huống chi, Hoắc Yếm ở biên quan đã đánh tan đội quân tinh nhuệ, chiếm trọng thành, lại một mình đánh bại hai danh tướng hổ thần của Tây Lương. Uy danh lẫy lừng của hắn đã đến mức khiến người ta chỉ nghe thôi cũng phải kinh hồn bạt vía.

Nếu còn tái chiến, e rằng cũng chỉ là phí công vô ích.

Nghe vậy, Thác Bạt Hoằng yếu ớt chống người ngồi dậy, ngón tay run rẩy chỉ xuống dưới.

“Hồ đồ! Hoắc Yếm dũng mãnh vô song, khắp sáu nước hiếm gặp đối thủ. Con muốn đi đánh hắn, dựa vào đâu? Đừng nói là con, ngay cả cô… Nếu sớm biết hắn có thể từ phương Bắc chi viện nhanh đến thế, cô cũng sẽ không khinh địch mạo muội chinh phạt Xích Phong, uổng công làm tổn thất bao nhiêu nam nhi anh dũng của Tây Lương ta!”

Hốc mắt Thác Bạt Xuyên đỏ lên vì phẫn uất, không cam lòng hỏi:

“Vậy chúng ta cứ ngồi chờ chết, mặc cho Hoắc Yếm hắn đánh đến trước điện Duy Viên sao?”

Dứt lời, tam vương tử Thác Bạt Tắc vẫn luôn im lặng bấy lâu chậm rãi tiến lên, đỡ Thác Bạt Xuyên đứng dậy. Sau đó hắn thở dài nói:

“Vương huynh, sau trận Xích Phong, binh tướng của chúng ta nguyên khí đại thương, đã không còn sức tái chiến. Hiện giờ, cầu hòa mới là lối thoát duy nhất…”

“Cầu hòa? Bảo chúng ta cắt đất bồi bạc, năm nào cũng tiến cống lễ vật cho kẻ thù không đội trời chung là Đại Lương? Mối nhục này, chúng ta làm sao chịu nổi?!”

Tính tình Thác Bạt Xuyên cương liệt. Trước mắt bị Hoắc Yếm ép đến đường cùng, hắn thậm chí đã chuẩn bị sẵn tâm thế thà chết vinh còn hơn sống nhục.

“Không chịu, thì còn có thể làm gì!”

Thác Bạt Hoằng được vương hậu đỡ nửa ngồi dậy. Khi nói, cổ họng ông khô khốc khó nhọc, giọng nói càng thêm khàn đặc căng chặt.

“Nhịn nỗi nhục hôm nay, vẫn còn một hơi thở để chờ ngày rửa hận. Xuyên nhi, đạo lý giữ được núi xanh thì không lo thiếu củi đốt, con vậy mà còn không nghĩ thấu được như tam đệ của con!”

Nghe vậy, ánh mắt Thác Bạt Xuyên dần trầm xuống. Sau đó hắn nhìn chằm chằm Thác Bạt Tắc, ánh mắt ẩn chứa ý vị khó đoán.

“Tam đệ hiểu quốc sự, biết vận nước, xem ra là vi huynh nông cạn, trong mắt chỉ có cái dũng của kẻ thất phu.”

Thác Bạt Tắc đang định mở miệng, lại nghe Thác Bạt Xuyên ngay sau đó đổi giọng nói tiếp:

“Nếu phụ vương và tam đệ đều có ý này, ta cũng không cố chấp thêm nữa. Chỉ là cầu hòa cần thể hiện thành ý. Lần này trên thư cầu hòa, ngoài thành trì và bạc tiền cần có, ta lại cảm thấy còn nên thêm một món lễ nữa, mới có thể xem như điểm mắt cho rồng, khiến thành ý thêm trọn vẹn.”

Mọi người đều kinh ngạc trước sự thay đổi thái độ nhanh chóng của Thác Bạt Xuyên. Thác Bạt Tắc càng khó hiểu hỏi:

“Vương huynh nói đến thứ gì?”

“Mỹ nhân.”

Thác Bạt Xuyên nhìn về phía Thác Bạt Tắc, trên mặt lộ ra một nụ cười khiêu khích.

“Mỹ nhân được gửi nuôi trong cung của Vân nương nương kia, ta từng gặp qua một lần, đã kinh diễm khó quên. Dung mạo khuynh thành như thế, trên đời có thể nói là vô song. Nếu được dạy dỗ một phen rồi đưa sang Đại Lương làm lễ vật, ắt hẳn sẽ thể hiện rõ thành ý. Chỉ là không biết tam đệ một lòng vì dân vì nước của ta, có nỡ cắt bỏ thứ mình yêu thích hay không.”

“Nàng không được!”

Thác Bạt Tắc trước giờ luôn ôn hòa nhã nhặn, lúc này trên khuôn mặt đoan chính hiếm khi hiện ra mấy phần tức giận.

Lời vừa dứt, tỳ nữ A Giáng đứng ngoài cùng đám người hốt hoảng đến suýt làm đổ chén trà trong tay.

Nhân lúc sự chú ý của mọi người đều dồn về phía trước giường, A Giáng nhẹ tay nhẹ chân đặt chén xuống, cẩn thận lẻn ra ngoài, sau đó chạy thẳng đến Ôn Cư Tạ để lén báo tin.

Nàng chạy một mạch rất gấp, gần như hoảng đến mức không chọn đường. Trong lòng càng thêm lo lắng. Đại vương tử thật đáng ghét, cô nương nhà nàng rõ ràng và tam vương tử lưỡng tình tương duyệt, sao có thể lại bị xem như lễ vật đưa đến Đại Lương?

Hơn nữa, nghe nói người Trung Nguyên ai nấy đều âm hiểm xảo trá, trong đó càng không thiếu những ác quỷ Diêm La giết người như ngóe như Hoắc Yếm. Nếu cô nương thật sự đi, làm sao có thể bình an?

…

Ôn Cư Tạ.

Cánh cửa sổ chống trên tường lan can hé mở một nửa, ánh nắng trải xuống, nghiêng nghiêng phủ trên mặt bàn gỗ hoàng hoa lê. Thi Nghê một tay chống lên bàn, hờ hững đỡ cằm, tay còn lại đang đưa ngón tay lật những trang phổ cầm đã ố vàng.

Thỉnh thoảng có gió nhẹ thổi qua, vạt váy lụa màu hồng nhạt của nàng khẽ lay động trước sau, tựa như một đóa phù dung non mềm, e ấp nở rộ.

Lại lật qua một trang, lúc này một lọn tóc rủ bên vai mỹ nhân bị gió thổi rối, bay phất lên trước vầng trán đầy đặn.

Thi Nghê dường như bị làm ngứa, khẽ nhíu mày. Nhưng dù là vẻ mặt lộ chút thiếu kiên nhẫn, khi phản chiếu trong đôi mắt đào hoa rực rỡ của nàng, ý vị lại giống như hờn dỗi nhiều hơn, oán trách chỉ phảng phất đôi phần.

Nàng đặt phổ cầm xuống, đang chuẩn bị hồi tưởng lại những thế tay vừa ghi nhớ, thì lúc này, ngoài cửa bỗng vang lên một loạt tiếng bước chân vội vã.

Thi Nghê nghe tiếng ngẩng mắt lên, liền thấy tỳ nữ thân cận của mình là A Giáng lại không gõ cửa mà hấp tấp chạy vào.

“A Giáng, ta đã nói với muội rất nhiều lần rồi, ở vương phủ không thể vô lễ như vậy. Nếu chỉ có ta ở đây thì còn có thể dung túng cho muội làm càn, nhưng lỡ như không khéo gặp phải Vân nương nương và Tắc ca ca, trận phạt này muội nhất định không tránh được đâu.”

Nhưng A Giáng một chữ cũng không nghe lọt tai. Vừa vào phòng, nàng đã trực tiếp quỳ xuống trước mặt Thi Nghê, vẻ mặt đau khổ bi tráng.

“Nếu có thể giúp cô nương tránh được tai họa, A Giáng dù có bị phạt cũng cam lòng!”

“Tai họa…”

Nghe vậy, Thi Nghê lẩm bẩm lặp lại hai chữ ấy, nhưng trong lòng lại không có bao nhiêu sợ hãi.

Từ khi nàng có ký ức, tai họa bên cạnh dường như chưa từng ngừng lại. Cha mẹ mất sớm, gia tộc suy tàn, bị nuôi dưỡng trong cung… Ngoài một lớp da thịt xinh đẹp rực rỡ ra, nàng vốn chẳng có gì cả.

Mà sau khi đến tuổi cập kê, ngay cả nhan sắc duy nhất nàng có thể tựa vào, cũng dần trở thành ngọn nguồn dẫn họa sinh chuyện.

Sống nhờ trong cung, nàng trước giờ chưa từng được tự quyết. Vì vậy nàng học cách được chăng hay chớ, đặt mọi kỳ vọng đối với thế gian xuống mức thấp nhất.

Đã như vậy, còn có tai họa nào đáng để nàng phải đau lòng oán thán nữa? Chẳng qua cũng chỉ là sống lay lắt mà thôi.

“Muội đứng lên trước đi. Quỳ lâu đầu gối sẽ đau đấy, A Giáng.”

Thi Nghê khẽ thở dài, cúi người muốn đỡ tỳ nữ đứng dậy. Tính nàng ôn hòa hiền lành, đối với người dưới cũng luôn thương xót quan tâm.

Nhưng A Giáng lại bướng bỉnh không chịu đứng lên. Thấy Thi Nghê bày ra dáng vẻ chẳng để tâm, nhất thời nàng càng thêm lo lắng.

“Cô nương lúc nào cũng không để tâm đến chuyện của mình. Nhưng nguy nan lần này không phải những cuộc tranh đấu trong cung uyển ngày thường, có thể xoay xở hóa giải được đâu. Chuyện này liên quan đến quốc nạn. Nếu cô nương còn không nghĩ cách, e rằng sẽ bị xem như cống phẩm cầu hòa của Tây Lương, dâng sang Đại Lương!”

Dưới ánh mắt sững sờ của Thi Nghê, A Giáng lời ít ý nhiều kể lại trọn vẹn đầu đuôi sự việc. Cuối cùng, nàng lại nhấn mạnh lần nữa rằng chuyện này là do đại vương tử Thác Bạt Xuyên đề xuất, còn tam vương tử Thác Bạt Tắc thì hết sức phản đối.

Nghe vậy, trong lòng Thi Nghê dâng lên chút cảm xúc phức tạp. Sợ hãi tất nhiên là có, nhưng nhiều hơn vẫn là tê dại.

Nàng là hậu nhân của tội thần, trên đời sớm đã không còn người thân để nương tựa. May nhờ được Vân nương nương nhận nuôi trong cung, nàng mới không đến mức chết đói đầu đường. Ban đầu, nàng còn ngây thơ ảo tưởng, thật sự xem Vân nương nương là ân nhân, là quý nhân của mình.

Nhưng mãi đến sau này, nàng vô tình nghe được Vân nương nương và ma ma nói chuyện riêng, mới biết các nàng chịu bố thí lòng tốt, vậy mà tất cả đều là để tận tâm dạy dỗ nàng thành quân cờ tranh sủng với vương hậu. Nơi thuộc về nàng không phải Ôn Cư Tạ này, mà là giường của đại vương.

Cũng chính khi ấy, Thi Nghê mới bừng tỉnh. Chẳng trách bao năm qua, ăn mặc sinh hoạt của nàng đều được hưởng thứ tốt nhất, mức độ được nuông chiều thậm chí chẳng khác gì công chúa lá ngọc cành vàng. Còn có những yêu cầu kỳ lạ mà ma ma đưa ra với nàng… Hóa ra tất cả đều xuất phát từ một âm mưu kéo dài nhiều năm.

Những năm qua, bất kể đông hè, đêm nào nàng cũng bắt buộc phải ngâm mình trong sữa nửa canh giờ. Hơn mười năm được dưỡng nuôi như thế, khiến làn da nàng bây giờ non mềm như trẻ nhỏ, chạm nhẹ một cái cũng như có thể véo ra nước. Còn thứ thuốc đắng đến tận cùng mà nàng quanh năm suốt tháng ngày nào cũng phải uống, cũng khiến cơ thể nàng so với thiếu nữ cùng tuổi càng phát triển đầy đặn hơn, nhất là trước ngực, thường xuyên có cảm giác căng tức.

Nàng chỉ là một thiếu nữ chưa từng trải chuyện nam nữ, làm sao hiểu được những thủ đoạn dơ bẩn chốn hậu cung ấy. Mãi đến muộn màng về sau, nàng mới nhận ra cái gọi là thiên vị chăm sóc của Vân nương nương dành cho nàng bao năm qua, căn bản không xuất phát từ thương yêu, mà là đang trang hoàng cho một món lễ vật!

Vì địa vị của bản thân trong hậu cung, Thi Nghê vô tội trở thành vật thử nghiệm của bà ta. Nàng bị bà ta dốc lòng nuôi dưỡng thành một thiếu nữ quyến rũ đến mức bất kỳ nam nhân nào cũng khó lòng cự tuyệt. Hoặc cũng có thể nói, thành một thứ đồ chơi trên giường…

Nàng đương nhiên từng muốn trốn. Nhưng thực lực hai bên quá cách biệt, ngoài nhận mệnh ra, nàng chỉ còn con đường chết.

Mà tạo hóa trêu ngươi, đúng vào lúc ấy, tam vương tử Thác Bạt Tắc lại bày tỏ lòng yêu thích với nàng. Vân nương nương tính kế trăm bề, lại không ngờ đứa con trai đoan chính nhã nhặn của mình cũng không thoát khỏi căn tính thấp kém của nam nhân, đối với sắc đẹp cũng tham luyến thèm muốn như vậy.

Cũng vì thế, kế hoạch của Vân nương nương bị xáo trộn. Còn Thi Nghê tạm thời dựa vào sự che chở của Thác Bạt Tắc, bình an vượt qua mấy năm nay.

Nhưng hiện giờ, nàng không biết rốt cuộc Thác Bạt Tắc còn có thể bảo vệ nàng được bao lâu.

Thi Nghê thở dài cho số mệnh không thể tránh thoát của mình, rồi không khỏi tự oán tự thương mà thở ra một hơi.

“Dù là Tây Lương hay Đại Lương, đối với ta cũng chẳng qua là từ hang sói sang hang hổ. Dù sao cũng thân bất do kỷ, lại có gì khác biệt đâu.”

A Giáng không biết mưu tính của Vân nương nương, lúc này vẫn còn ngây thơ nói:

“Sao cô nương lại nói vậy? Với sự yêu chiều của Vân nương nương dành cho cô nương, sao người nỡ đưa cô nương đến Đại Lương xa nghìn dặm? Huống chi Tắc vương tử đối với cô nương tình sâu nghĩa nặng như vậy, chuyện này chàng tuyệt đối sẽ không đồng ý đâu. Bây giờ cô nương chỉ cần đi tìm họ tỏ ra yếu mềm, đáng thương rơi vài giọt nước mắt, tai họa này tất nhiên có thể tránh được.”

Thi Nghê bất lực ngồi trở lại trên giường mềm, ánh mắt tản ra ngoài cửa sổ, rơi lên khóm hoa mộc cận đang nở rộ. Một lúc lâu sau nàng mới nói:

“A Giáng, nơi này là vương cung quý uyển. Thứ không đáng tin nhất chính là hai chữ thâm tình.”

Khi ấy A Giáng không tin, nào ngờ lời này của Thi Nghê thật sự một câu thành sấm.

Nửa tháng sau, vương chiếu được đưa đến. Thác Bạt Hoằng đặc biệt lập Thi Nghê làm nghĩa nữ của vương hậu, ban phong hiệu Thuấn Hoa, được hưởng nghi trượng kiệu hoa của công chúa.

Nàng nhận được ân thưởng thể diện. Đồng thời, đạo chiếu thư thứ hai ban xuống ngay sau đó: công chúa vì phù hộ quốc vận, phải lên đường xa đến Đại Lương.

Thuấn Hoa, Thuấn Hoa.

Chẳng qua là hồng nhan mệnh bạc, vẻ đẹp chỉ rực rỡ trong thoáng chốc.

Thi Nghê quỳ xuống cúi người tiếp chỉ, trong lòng bỗng sinh ra vô vàn lạnh lẽo. Phong hiệu buồn cười này, vậy mà lại có vài phần hợp với số mệnh nổi trôi như bèo nước của nàng.

Sau này vào Đại Lương, e rằng tuổi xuân chẳng còn, quãng đời còn lại chỉ còn ảm đạm.

Dù là bị nạp vào nơi thâm cung sâu kín, hay bị ban vào hầu môn tướng phủ, thì nàng cũng chẳng tránh khỏi số mệnh lấy sắc hầu người, trở thành món đồ chơi trong lòng bàn tay của vương quyền quý nhân.

Còn về việc bị hiến tặng cho ai, đối với nàng mà nói, vốn chẳng có gì khác biệt.', '2026-06-01 06:52:24.859994+00'), (3, 2, 1, 'Văn án', '【Vũ cơ tuyệt sắc vs Chiến thần tướng quân】

Tây Lương chiến bại, Thi Nghê trở thành mỹ nhân cống phẩm được Tây Lương vương đích thân tuyển chọn kỹ càng để dâng lên hoàng tộc Đại Lương.

Nàng đẹp đến tuyệt sắc, yêu mị đến cực hạn. Vừa mới đặt chân tới thượng kinh, nàng đã khiến các vị hoàng tử tranh nhau theo đuổi. Thế nhưng trớ trêu thay, hoàng đế lại ban nàng cho Trấn quốc đại tướng quân Hoắc Yếm — người đang ở tận biên cảnh phương Bắc, trấn thủ cương vực.

Ai nấy đều biết Hoắc Yếm si mê võ nghệ đến thành cuồng, chẳng gần nữ sắc. Trong lúc nhất thời, người đời đều không khỏi thổn thức, tiếc than cho mỹ nhân vận số không may, vậy mà lại bị đưa cho một kẻ thô lỗ chẳng hiểu phong tình.

Ban đầu, quả thật Hoắc Yếm xem nàng như không thấy.

Hắn luyện chữ trong thư phòng, Thi Nghê ân cần hầu hạ bên cạnh. Hắn liếc nhìn bộ dị phục mỏng manh, rực rỡ trên người nàng, giọng nói trầm lạnh:

“Ăn mặc cho đàng hoàng. Hở hang như vậy còn ra thể thống gì.”

Trong mắt Thi Nghê đầy vẻ tủi thân. Đó vốn là y phục thường ngày của nàng mà.

Về sau, vẫn là gian thư phòng ấy, Hoắc Yếm không còn luyện chữ nữa, mà đổi sang vẽ tranh. Hắn đặt Thi Nghê nằm trên mặt án bằng gỗ đàn hương, rồi trên làn da trắng như tuyết, mềm mịn như băng ngọc của nàng, hắn chấm nghiên hạ mực.

Hóa ra, hắn muốn lấy thân nàng làm giấy vẽ cho mình.

* Ngọt sủng, song khiết.
* Ít quyền mưu, bản chất là câu chuyện yêu đương.
* Nữ chính thuộc kiểu mềm yếu, không mạnh mẽ, nhưng mê hoặc nam chính đến chết đi sống lại.

Thể loại: Trời sinh một đôi, truyện ngọt.
Từ khóa tìm kiếm: Nhân vật chính: Thi Nghê, Hoắc Yếm
Tóm tắt một câu: Vũ cơ tuyệt sắc vs Chiến thần tướng quân.
Chủ đề: Mệnh ta do ta quyết, phá bỏ xiềng xích.', '2026-06-01 06:55:01.075245+00'), (4, 2, 3, 'Chương 2: Tướng quân Diêm La ', 'Cỗ kiệu hoa lệ rời khỏi vương cung Tây Lương đã xa đến nghìn mét, tiếng nức nở khe khẽ của A Giáng vẫn chưa từng dứt.
Nghe tiếng khóc thê lương không ngừng ấy, có thể thấy trong lòng nàng đầy oán trách, nỗi uất ức dường như còn nhiều hơn Thi Nghê mấy phần.
Vốn dĩ nha đầu này không cần phải đi theo, nhưng nàng lại cố chấp cầu xin vương thượng ban ân cho đồng hành, chỉ vì sợ Thi Nghê một mình đến dị quốc, cô khổ không nơi nương tựa. Có nàng đi cùng, trên đường ít nhiều cũng có người bầu bạn, không đến mức quá quạnh quẽ.
Vì vậy, Thi Nghê quả thật không thấy đường đi buồn tẻ. A Giáng khóc rất lâu vẫn không ngừng, từ lúc xuất phát đến giờ, trong khoang xe chưa có lấy một khắc yên tĩnh.
Lại qua thêm một lúc, Thi Nghê bất đắc dĩ xoa xoa thái dương, có chút muốn nói lại thôi. Vốn nàng nghĩ đường đi xa xôi, vừa lên kiệu sẽ dưỡng sức chợp mắt một lát, nào ngờ giọng A Giáng lại tốt đến vậy, khóc gần nửa canh giờ rồi vẫn chưa chịu thôi.
Hơn nữa, nếu nàng còn mặc kệ như thế, e rằng lát nữa đi vào con đường nhỏ trong rừng phía trước, tiếng khóc gào của A Giáng cũng đủ dẫn sói núi kéo tới.
Thi Nghê thở dài một hơi, lấy chiếc khăn tay bằng tơ tằm trong tay áo ra, nghiêng người qua muốn lau gương mặt nhỏ đã khóc lem luốc của A Giáng. Kết quả nhìn nàng nước mắt không ngừng, nước mũi cũng chảy, nhất thời lại không tìm được chỗ nào để xuống tay.
Một lát sau, Thi Nghê thật sự không nhịn được, bị gương mặt lem luốc như mèo con của A Giáng chọc cho bật cười.
“A Giáng, mau lau đi. Lát nữa đến Hội Kê, chúng ta còn phải giữ chút thể diện trước mặt quân tướng Đại Lương.”
Xe ngựa của các nàng do binh tướng Tây Lương hộ tống đến thành Hội Kê, sau đó sẽ được người Đại Lương tiếp nhận. Bất kể là tiền tài bạc lụa, hay là nàng, tất cả đều phải đi về phía đông, từ nay không thể quay đầu nữa.
“Cô nương sao còn có tâm trạng cười được chứ? Ta là thấy uất ức thay cho cô nương. Sau này tiền đồ hiểm nguy, cô nương thân cô thế cô, không còn ai che chở nữa, về sau phải làm sao mới có thể bình an sống tiếp đây?”
A Giáng nhận lấy khăn tay, càng nói càng không kìm được đau lòng.
“Không có ai sẽ mãi mãi che chở cho ai.”
Thi Nghê nghiêm túc nhìn vào mắt tỳ nữ A Giáng, như đang nói với nàng, lại càng giống như đang nói với chính mình.
“Nếu đã đến rồi thì cứ yên ổn mà chấp nhận. Ở lại cung viện Tây Lương đã là đường cùng, nay rời khỏi đó, có lẽ còn có thể gặp được một tia sinh cơ.”
A Giáng chớp chớp mắt, lau khô nước mắt, nhưng vẫn còn ôm ảo tưởng ngây ngốc.
“Sao lại là đường cùng được? Nếu không phải Tắc vương tử bị Vân nương nương lừa uống hai bát lớn thuốc mê, lại bị nhốt trong Ôn Cư Tạ không ra được, cô nương sao có thể đáng thương rơi vào cảnh này? Cô nương cứ chờ thêm đi, chờ dược hiệu qua rồi, Tắc vương tử tỉnh lại, chàng nhất định sẽ đuổi theo cứu cô nương về!”
Những chuyện ở Tây Lương, vốn dĩ nàng chẳng muốn nhớ một chuyện nào. Nhưng lúc này A Giáng lại đột nhiên nhắc đến, khiến lòng nàng khó tránh khỏi hơi chua xót.
Sau khi vương chiếu ban xuống, Tắc ca ca quả thật đã hết sức tranh thủ vì nàng. Chàng không chỉ đến cầu xin Vân nương nương, mà còn quỳ suốt một ngày một đêm ngoài điện của vương thượng. Nhưng trong mắt kẻ nắm giữ vương quyền, những chuyện tình cảm nam nữ hư vô mờ mịt ấy thì tính là gì? Cuối cùng, tất cả chẳng qua cũng chỉ là vô ích.
Thi Nghê chậm rãi thu hồi suy nghĩ, không còn cố chấp mà khẽ lắc đầu thở dài.
“Ta lại không mong huynh ấy đến.”
Giãy giụa vô ích thì có tác dụng gì?
A Giáng lại không hiểu.
“Vì sao chứ? Chẳng phải cô nương và Tắc vương tử đã lưỡng tình tương duyệt, âm thầm định chung thân rồi sao? Nay cô nương gặp nạn, sao lại không mong chàng đến cứu?”
Im lặng một lúc lâu, ánh mắt Thi Nghê bỗng ảm đạm đi rất nhiều. Những lời riêng tư này là lần đầu tiên nàng thổ lộ với người khác.
“Mấy năm nay, ta vẫn luôn xem Tắc ca ca như huynh trưởng. Trong lòng ta dành cho huynh ấy cũng không phải tâm tư của nữ nhi. Nhưng để có thể sống tiếp, ta chỉ có thể… Thôi bỏ đi.”
Nàng thở dài rồi ngừng lời. Nếu còn nói tiếp, e rằng nàng cũng sẽ giống A Giáng vừa rồi, không kìm được mà rơi lệ.
Những năm này, nàng chịu quá nhiều uất ức. Nhiều đến mức hiện giờ bị hiến sang Đại Lương, nàng lại cảm thấy đây cũng là một cách giải thoát khác.
Nếu may mắn, sau khi vào Đại Lương, nàng có thể được ban cho một người ôn hòa lương thiện, quãng đời còn lại xem như cũng được bình an. Dù phải làm thiếp, cũng vẫn tốt hơn ở Tây Lương ngày ngày đề phòng Vân nương nương, sống trong nơm nớp lo sợ.
A Giáng nhìn dáng vẻ thương tâm ảm đạm của Thi Nghê lúc này, không đành lòng tiếp tục truy hỏi. Vì vậy nàng nghiêng người qua, chậm rãi ôm lấy Thi Nghê, lại nhẹ nhàng vỗ lưng an ủi hồi lâu.
…
Vào đến Hội Kê, tùy tùng và tướng quan Tây Lương không thể tiếp tục theo vào thành.
Vốn dĩ, thành Hội Kê là trọng thành nơi biên tuyến của Tây Lương. Vậy mà nay lại trở thành địa bàn của Đại Lương, nơi người Tây Lương không thể đặt chân. Bảo người ta làm sao không nhụt chí cho được? Vì vậy suốt dọc đường, vẻ sầu não trên gương mặt binh lính chẳng kém A Giáng là bao.
Cỗ kiệu hoa của Thi Nghê và A Giáng được viên quan binh dẫn đầu đích thân đưa đến trước mặt tướng quan Đại Lương. Vì là bên bại trận, người Tây Lương tự nhiên thấp hơn một bậc. Ngay cả Thi Nghê cũng phải xuống kiệu để nữ quan lục soát người.
Tướng lĩnh Đại Lương được phái đến là một võ nhân da mặt ngăm đen, cử chỉ thô lỗ. Người bên cạnh gọi hắn là Mông hiệu úy.
Mông hiệu úy thấy Thi Nghê che khăn lụa trên mặt, được tỳ nữ đỡ xuống với dáng vẻ yếu mềm yêu kiều, liền nhìn không thuận mắt, nhíu mày nói:
“Từ nay về sau cô nương đi theo đoàn xe của Đại Lương chúng ta, e rằng không thể tiếp tục được hầu hạ như công chúa nữa. Cô nương tốt nhất nên sửa lại cái dáng vẻ kiều quý ấy đi, nếu không trên đường tự nhiên sẽ phải chịu chút khổ.”
A Giáng nóng lòng bảo vệ chủ, vội chắn lên phía trước, cất giọng phản bác:
“Sao ngươi có thể nói chuyện với cô nương nhà ta như vậy? Cho dù chúng ta là người Tây Lương, nhưng cô nương đã được vương hậu nhận làm nghĩa nữ. Vì giao hảo lâu dài giữa hai nước, sau khi cô nương vào Đại Lương của các ngươi, cũng sẽ trở thành nương nương hoặc tiểu chủ tử.”
Chưa đợi Mông phó hiệu úy nói gì, từ phía sau hắn đã có một nữ quan mặc quan phục màu đỏ sẫm, áo trên váy dưới, bước tới. Nàng ta không chút nể mặt mà lạnh lùng châm chọc:
“Chủ tử? Ta lại không biết người Đại Lương chúng ta phải làm thế nào để nhận một vị công chúa tiện nghi của nước bại trận làm chủ tử đây?”
Sự khinh miệt trong lời nữ quan gần như không hề che giấu. Thi Nghê quả thật cũng không ngờ, người Đại Lương không thích các nàng đến mức ngay cả chút công phu bề ngoài cơ bản nhất cũng lười duy trì.
A Giáng còn muốn tiếp tục tranh chấp với nữ quan kia, nhưng bị Thi Nghê ngăn lại. Chặng đường này các nàng còn phải ở chung với bọn họ rất lâu. Nếu lúc này đắc tội triệt để với người ta, e rằng đường sau này sẽ càng thêm gian nan.
Vì vậy nàng vội kéo A Giáng lại, giọng nói ôn hòa yếu nhẹ:
“Lời của Mông hiệu úy, chúng ta đã ghi nhớ. Xin các vị đại nhân yên tâm, trên đường ăn mặc sinh hoạt của chúng ta giống mọi người là được, không cần chăm sóc đặc biệt.”
Có lẽ thấy thái độ của Thi Nghê như thế, nữ quan kia liền nhận định nàng là quả hồng mềm dễ bắt nạt, vì vậy càng vênh váo, càng lấn tới.
“Nếu đã vậy, về sau bữa ăn của cô nương cứ tự dựng bếp riêng đi. Chỗ chúng ta trước giờ không nuôi người rảnh rỗi. Thực phẩm ở chỗ quân nhu đều có, cô nương cần gì thì tự mình đến lấy là được.”
Nàng ta nói xong, Mông hiệu úy dường như cảm thấy việc này không ổn, liền do dự dùng ánh mắt ra hiệu cho nữ quan kia.
Nhưng đối phương không nhận ý tốt ấy, vẫn làm ra dáng vẻ muốn giữ trọn bộ dạng chỉ tay sai khiến của mình.
Thi Nghê chỉ cười cười, mặc cho nữ quan kia tự ý quyết định.
“Biết rồi.”
…
Theo Thi Nghê từ Duy Viên đến đây, ngoài A Giáng còn có hai phụ nhân trung niên và ba nha đầu tuổi không lớn. Thi Nghê không cần nhiều người ở bên hầu hạ như vậy, hơn nữa tình cảnh hiện tại tốt nhất vẫn nên hành sự kín đáo. Vì thế nàng chỉ giữ A Giáng ở lại bên cạnh, những người còn lại giao cho Mông hiệu úy sắp xếp.
Quân đội Đại Lương đều đóng trong doanh trại trong thành, các nàng cũng phải ở cùng quân doanh. Vì vậy chiếc lều quân đơn sơ nằm nơi góc khuất nhất đã trở thành chỗ ở tạm thời của Thi Nghê và A Giáng.
Vào trong lều, đợi xung quanh không còn ai, A Giáng thật sự nhịn không nổi, uất ức nhăn gương mặt nhỏ lại, tiếp đó thở dài buồn bực nói:
“Tính tình cô nương vốn mềm yếu, nay lại bị người ta bắt nạt đến mức này. Nghĩ đến bộ mặt của nữ quan kia, thật sự đáng ghét! Cũng không biết nàng ta có lai lịch gì. Chỉ là một cung nữ cao cấp ở Lục Thượng Cục nho nhỏ, vậy mà lại có thể khiến Mông hiệu úy đối với nàng ta khách khí như thế.”
A Giáng vừa nói vừa bước lên đánh giá đồ đạc bày biện trong lều. Rất nhanh nàng đã bất mãn nói:
“Cái giường rách đơn sơ này cứng đến mức cấn tay, cô nương thân thể mềm yếu sao ngủ được? Còn chăn đệm này nữa, ngửi đã thấy mùi ẩm mốc rồi, chắc chắn là để lâu ở nơi âm u ẩm thấp nên sinh mốc. Cô nương rơi vào tình cảnh thế này, nếu để Tắc vương tử biết được, chàng không đau lòng chết mới lạ.”
Nghe nàng càng nói càng quá, càng lúc càng không biết giữ miệng, Thi Nghê khẽ nhíu mày, lập tức nhắc nhở:
“A Giáng, họa từ miệng mà ra. Sau này tuyệt đối không được tùy tiện nhắc đến Tắc ca ca nữa. Thân phận của ta đặc biệt. Nay nếu đã đến dưới trướng quân đội Đại Lương, chuyện cũ trước kia nên cắt đứt sạch sẽ. Nếu không, có lẽ sẽ rước lấy họa sát thân. Muội nhớ chưa?”
Nghe vậy, A Giáng cũng ý thức được mức độ nghiêm trọng của sự việc, vội nhận lỗi rồi gật đầu. Sau đó nàng lại hạ thấp giọng, không cam lòng hỏi:
“Nhưng cô nương bị nữ quan kia khinh thường đối đãi như vậy… Chúng ta cứ thế nhịn cơn giận này sao?”
“Tuy chúng ta thân phận nhỏ bé, lời nói không có trọng lượng, nhưng rốt cuộc vẫn xem như mang theo thể diện của vương thượng. Để thể hiện phong phạm đại quốc, xét cả tình lẫn lễ, người Đại Lương đều nên đối đãi lễ độ với chúng ta. Ít nhất là lễ độ trên mặt ngoài.”
Giọng điệu Thi Nghê nhàn nhạt, vẻ mặt lại bỗng lộ ra vài phần giảo hoạt.
“Nay người ta cố ý làm khó, vậy chi bằng chúng ta cứ thuận theo ý nàng ta, sống thật thê thảm một chút. Đến khi chủ tướng dẫn đội thật sự truy cứu, người bị hỏi tội cũng không phải chúng ta.”
Lúc này A Giáng mới bừng tỉnh.
“Hóa ra cô nương đã sớm nghĩ cách đáp trả rồi.”
“Không phải đáp trả.”
Thi Nghê dịu dàng cười. Trên gương mặt tuyệt sắc quá mức diễm lệ của nàng, lúc này hiện ra chút sinh khí mà mấy ngày gần đây chưa từng có.
“Chúng ta không tranh, chỉ cầu tự bảo vệ mình.”
“Đúng đúng, chỉ cầu tự bảo vệ mình.”
A Giáng biết trong lòng Thi Nghê đã sớm có chủ ý, luồng uất nghẹn trong lòng rốt cuộc cũng thuận hơn. Nàng không hiểu nhiều đạo lý lớn lao, nhưng chỉ nhận một lý lẽ, đó là bất kể là ai, dù tôn quý thế nào, cũng không được bắt nạt cô nương nhà nàng.
Nếu không, dù có liều mạng, nàng cũng phải bảo vệ cô nương chu toàn.
“Đúng rồi, cô nương có biết lần này người đưa chúng ta đến đô thành Thượng Kinh của Đại Lương là vị tướng quân nào không?”
A Giáng như nhớ ra gì đó, lại mở miệng hỏi.
Thi Nghê thành thật lắc đầu:
“Không biết.”
“Ai cũng được, chỉ cần không phải vị Hoắc tướng quân được gọi là quỷ Diêm La kia là được.”
A Giáng lẩm bẩm, rồi lại nhỏ giọng bàn tán:
“Cô nương biết không? Dân chúng biên quan chúng ta đều đang truyền nhau đấy, nói Hoắc Yếm người này ăn thịt uống máu, trên đầu mọc sừng, mặt mũi xấu xí đáng sợ, còn bị biên thành đồng dao chuyên dùng để dọa những đứa trẻ bảy tám tuổi không nghe lời. Cô nương nói xem, người thật sự có thể mọc sừng sao? Nếu mọc thật thì phải thành dáng vẻ đáng sợ thế nào chứ?”
Trước kia Thi Nghê thật ra chưa từng nghe lời đồn như vậy. Nay nghe A Giáng miêu tả cụ thể đến thế, nàng bất giác cũng tưởng tượng theo hình tượng của Hoắc tướng quân trong đầu. Thân người mặt trâu sao? Vậy thì thật sự đáng sợ quá…
“Muội biết rõ ta trước giờ sợ mấy chuyện quỷ thần, còn cố ý nói những lời quái dị này để dọa ta. A Giáng, muội đúng là học hư rồi.”
Thi Nghê hờn trách trừng mắt nhìn A Giáng một cái. Sau đó nàng vội vàng xua tan hình ảnh đang dần hình thành trong đầu, chỉ sợ đêm nay quỷ quái nhập mộng, khiến nàng không thể ngủ yên.
A Giáng thì vội xin tha, lại khuyên nàng rằng cho dù Hoắc tướng quân thật sự mọc sừng trên đầu cũng chẳng sao, dù sao các nàng cũng sẽ không vô duyên vô cớ gặp phải vị Diêm La tướng quân ấy.
Nhưng khi ấy Thi Nghê không biết rằng, lời này của A Giáng, rốt cuộc đã nói ra quá sớm.', '2026-06-01 09:56:02.339793+00'), (5, 2, 4, 'Chương 3: Khó nguôi', 'Mấy ngày ở trong quân doanh, Thi Nghê luôn bị người Đại Lương đề phòng rất chặt. Ngày thường nếu có chạm mặt ai, đối phương cũng chẳng dám tùy tiện nói với nàng lấy một câu.
Ngoài ra, ăn mặc sinh hoạt của nàng cũng bị cắt xén đủ đường. May mà trước khi xuất phát A Giáng đã tự chuẩn bị khá đầy đủ, nếu không ở nơi thành ngoại hoang vắng, đất khách quê người này, hai chủ tớ các nàng e rằng thật sự khó mà sống nổi.
Ban đầu, Thi Nghê còn tưởng người Đại Lương chỉ muốn ra oai phủ đầu với nàng. Dù sao hai nước vừa mới ở thế kiếm tuốt cung giương, nàng lại là người mới đến, còn là nữ tử Tây Lương dâng lên để tỏ lòng quy thuận, chịu chút lạnh nhạt vốn cũng nằm trong dự liệu.
Nhưng sau mấy ngày tiếp theo, Thi Nghê dần dần nhận ra, mức độ bài xích của đám tỳ nữ và nữ quan Đại Lương đối với nàng còn nghiêm trọng hơn nàng tưởng tượng rất nhiều.
Cảm giác ấy giống như đã có người dặn dò các nàng từ trước vậy, thật sự kỳ quặc vô cùng.
Thi Nghê nghĩ mãi không hiểu, bèn dặn A Giáng ngày thường có thể giao thiệp nhiều hơn với những phụ nhân giúp việc dưới bếp. Địa vị của họ trong doanh trại khá thấp, những lời căn dặn từ bên trên phần nhiều cũng không truyền đến tai họ.
Để A Giáng có thể nhanh chóng tạo quan hệ với họ, Thi Nghê liền lấy hết những trang sức châu ngọc mình thường đeo, vòng ngọc trâm cài, đưa cho nàng dùng làm quà lấy lòng. Thi Nghê thì không quá để tâm tiếc hay không tiếc, nhưng lại khiến A Giáng đau lòng hỏng mất.
“Những món trang sức này của cô nương, món nào cũng tinh xảo vô song. Còn có mấy món là Vân nương nương đặc biệt tìm thợ làm riêng cho cô nương. Bây giờ nói tặng người là tặng người, về sau e rằng không dễ đòi lại nữa đâu.”
“Đã là đồ tặng ra ngoài, tự nhiên không có đạo lý đòi lại. Huống hồ những thứ này đều là vật ngoài thân, có thể giải quyết cái khó trước mắt thì đã phát huy được tác dụng lớn nhất của chúng rồi. Muội cứ cầm đi làm việc là được.”
Thi Nghê căn dặn như vậy.
Trâm vòng đưa đi chưa hẳn đã là chuyện xấu. Những thứ Vân nương nương ban thưởng, nàng vốn không nhận nổi, giữ bên người cũng chẳng có lợi ích gì. Huống chi thứ nàng ngày thường không thiếu nhất chính là châu báu trang sức, đưa đi vài món cũng chưa đến mức sa sút.
Quả nhiên, bất kể ở đâu, tiền tài bạc lụa đều là tấm giấy thông hành tốt nhất để đi lại quan hệ.
Danh tiếng ra tay hào phóng của A Giáng vừa truyền ra, không chỉ những phụ nhân dưới bếp bắt đầu âm thầm chiếu cố các nàng, mà ngay cả vài tỳ nữ có chút phẩm cấp cũng bắt đầu lén lút muốn kết giao với A Giáng.
A Giáng tất nhiên ai đến cũng không từ chối. “Bạn bè” trong quân doanh quen biết càng nhiều, tiền tài tự nhiên cũng tiêu tán không ít. Đương nhiên, quan trọng nhất là tin tức Thi Nghê dặn nàng đi hỏi thăm, cuối cùng nàng cũng hỏi rõ được cả ngoài sáng lẫn trong tối, vào lúc túi tiền suýt nữa thấy đáy.
“Cô nương đoán không sai, nữ quan kia quả thật có quý nhân chống lưng phía sau. Nàng ta tên thật là Phùng Chiêu, rất được trưởng công chúa Đại Lương tin tưởng. Nghe nói hai người quen biết nhau trong dân gian, vì nàng ta có một đôi tay khéo léo, giỏi may chế hoa phục, nên được công chúa phá lệ đưa vào cung, còn được ban chức Thượng y. Hơn nữa…”
Trải qua mấy ngày gian nan này, A Giáng không còn nóng nảy hấp tấp như lúc mới đến nữa, cũng hiểu đạo lý tai vách mạch rừng. Vì vậy nói đến chỗ riêng tư, nàng vội xoay người đi đến cửa lều, đợi xác nhận xung quanh không có ai, mới hạ thấp giọng nói tiếp.
“Hơn nữa nghe nói, trưởng công chúa có ý tác hợp Phùng đại nhân với thái tử Đại Lương. Thái tử lại là em trai ruột cùng mẹ với trưởng công chúa. Vốn tưởng có công chúa làm chủ, chuyện này hơn phân nửa có thể thành. Nào ngờ thái tử Đại Lương lại từ chối triệt để, khiến Phùng đại nhân mất mặt ghê gớm.”
Thi Nghê nghe A Giáng kể sinh động như thật những chuyện bí mật trong hoàng cung Đại Lương, càng nghe càng cảm thấy mù mờ.
Những chuyện này đều chẳng liên quan gì đến nàng. Phùng đại nhân đối xử hà khắc với nàng, chẳng lẽ chỉ vì muốn trút giận trong lòng? Chuyện này thật sự quá gượng ép.
Như nhìn ra sự khó hiểu của Thi Nghê, A Giáng liền nói tiếp:
“Nhưng đúng vào lúc ấy, bức họa của cô nương được sứ thần Tây Lương chúng ta đưa vào hoàng cung Đại Lương. Nghe nói mọi người ngắm tranh trong yến tiệc, thái tử đúng lúc khen một câu: ‘Mỹ nhân, thật tuyệt diệu thay.’ Đối với dung mạo dáng vẻ của cô nương càng hết lời tán thưởng. Phùng đại nhân đúng lúc đang thương tâm lại nghe thấy rõ ràng, vì vậy trong lòng sinh ra oán hận và địch ý với cô nương. Cho nên, đại khái là vì thế, mới có sự bạc đãi hôm nay đối với chúng ta…”
Hiểu rõ đầu đuôi sự việc, trong lòng Thi Nghê dâng lên vài phần bất đắc dĩ.
Nàng ở hoàng cung Tây Lương cũng xem như đã lâu, tự nhiên biết một khi lòng ghen ghét của nữ nhân phát tác thì có thể đáng sợ đến mức nào. Nhất là hiện giờ, nàng và A Giáng không nơi nương tựa, cho dù địch ý của đối phương đến một cách vô lý, các nàng cũng chỉ có thể tạm thời nhẫn nhịn.
…
Dựa vào những “bạn bè” trong doanh mà A Giáng đã kết giao trước đó, mấy ngày này các nàng sống cũng xem như khá thoải mái.
Nhưng ngày vui ngắn chẳng tày gang. Phùng Chiêu nhạy bén, rất nhanh đã phát hiện những động tác nhỏ của các nàng. Vì vậy nàng ta càng trông coi các nàng nghiêm ngặt khắt khe hơn, thậm chí không cho người khác đến để ý. Về sau gần như vứt các nàng ở trong chiếc lều hẻo lánh, không hỏi không quản.
Thấy thái độ Phùng Chiêu tệ hại đến vậy, những tỳ nữ phụ nhân kia tất nhiên không dám tự ý làm chủ nữa. Vì vậy thái độ của họ cũng từ nhiệt tình chiếu cố ban đầu, dần dần biến thành thấy gió đổi chiều, né tránh không gặp các nàng.
Đối với chuyện này, Thi Nghê quả thật không còn cách ứng phó. Nói cho cùng, nơi đây là địa bàn của Đại Lương, những kẻ tha hương như các nàng nào có tư cách kêu oan.
Mắt thấy vật tư cung cấp càng lúc càng tệ, A Giáng tức giận mắng một câu:
“Chẳng trách thái tử không cần nàng ta. Biết giận cá chém thớt như vậy, ta thấy nàng ta căn bản là một mụ điên đầu óc không bình thường!”
Nói xong, như nghĩ đến điều gì, nàng vội thở dài ngừng lại, tiếp đó cúi đầu ủ rũ nhìn Thi Nghê.
“Cô nương đừng trách, ta lại ăn nói không biết giữ miệng rồi.”
Thi Nghê đang ôm giỏ tre, cẩn thận lựa lá mộc cận bên trong. Nghe vậy, hiếm khi nàng dung túng nói:
“Không sao, muội nói như vậy, ta nghe cũng thấy hả giận không ít.”
A Giáng bất ngờ trong thoáng chốc. Cô nương ngày thường dịu dàng mềm mại, lúc nào cũng giống như không có tính khí. Thật ra bên trong lại hơi có chút tinh ranh, chỉ là người ngoài rất khó nhìn ra ngoài mặt mà thôi.
A Giáng cười cười, ghé sát lại gần, thấy Thi Nghê tiếp tục lựa trong giỏ, liền nói:
“Những lá này vừa rồi ta đã chọn qua một lượt rồi. Cô nương muốn dùng để dưỡng tóc thì cứ dùng trực tiếp là được, bảo đảm thơm thơm.”
Thi Nghê lại nhặt ra một chiếc đưa đến trước mặt nàng, để lộ dấu răng bị sâu bọ cắn trên đó, mang theo vài phần oán trách:
“Cả giỏ đều là thứ kém chất lượng, có chọn nữa cũng chọn không sạch. Lần này Phùng đại nhân có lẽ thật sự nổi giận rồi, ngay cả những thứ này cũng không cho đồ tốt nữa.”
Ăn uống kém một chút thì chẳng sao, nhưng điều khiến Thi Nghê khó chịu nhất chính là hiện giờ dùng nước khó khăn, không thể dưỡng tóc đàng hoàng, càng không thể mỗi ngày ngâm mình trong sữa để dưỡng da.
Hơn mười năm qua, nàng được nuôi dưỡng thật sự quá mảnh mai quý giá. Thói quen chăm dưỡng giữ gìn quanh năm, đâu phải nói đổi là có thể đổi ngay được. Nhưng nơi quân doanh đóng quân vốn cách xa sông nước, trước đây các nàng dùng nước đều là nhờ binh sĩ giúp đỡ. Nay không còn ai giúp nữa, vì vậy trước mắt ngay cả nước ăn cũng thành vấn đề, càng đừng nói đến chuyện xa xỉ như ngâm mình trong sữa.
Thi Nghê nhịn hai ngày, thân thể thật sự khó chịu vô cùng. Đúng lúc này, A Giáng bỗng mang đến tin tốt.
“Cô nương, tình hình nơi này cuối cùng cũng bị ta dò rõ rồi. Mấy ngày nay ta lén lút quan sát, thấy có tỳ nữ xách thùng thường xuyên chui vào con đường nhỏ trong rừng. Ban đầu ta tưởng các nàng đi giặt y phục, kết quả ta cẩn thận đi theo, liền thấy trong sâu trong rừng có một dòng nước lặng chảy. Hóa ra ngày thường các nàng đều trực tiếp vào khe nước đó để tắm gội. Nếu đã vậy, cô nương chẳng phải có thể nhân lúc chiều tối phát cơm mà lén đi sao? Như thế sẽ không bị quấy nhiễu, thời gian tắm gội cũng đủ rộng rãi.”
Nghe vậy, vẻ buồn rầu của Thi Nghê cuối cùng cũng dần giãn ra. Nàng giơ tay chạm nhẹ lên chóp mũi A Giáng, lập tức vui vẻ nói:
“A Giáng, ta biết ngay muội là người lanh lợi nhất mà.”
…
Doanh phòng thủ Ung Thành.
Trên võ trường, hai tướng quan để trần nửa thân trên đang dùng sức vật lộn với nhau. Thực lực đôi bên ngang ngửa, từng quyền từng thế đều khiến binh sĩ xung quanh lớn tiếng reo hò cổ vũ.
Đứng ở nơi cao nhất trên đài chủ tướng là một nam tử trẻ tuổi. Thân cao hơn tám thước, dáng người thẳng tắp vĩ ngạn, mặc áo giáp nghi vệ uy nghiêm lạnh lẽo. Bên hông đeo một thanh bảo kiếm ánh đen vàng sắc lạnh, khí thế quanh thân sắc bén bức người.
Đúng lúc tiếng hô trên sân lại vang lên, hắn tập trung cúi mắt nhìn xuống, ánh mắt dừng trên người đang dần rơi vào thế yếu trên võ trường.
Lúc này, phó tướng bên cạnh hắn vô cùng chắc chắn mở miệng:
“Tướng quân, nhìn mấy lượt giao thủ vừa rồi, trận này chắc lại là huynh đệ doanh hai thắng rồi.”
“Chưa chắc.”
Hoắc Yếm bình thản mở miệng. Sau đó hắn cảm thấy chẳng còn thú vị gì, liền thu hồi tầm mắt.
Hôm nay là tiệc mừng công của Ung Thành, hắn là chủ soái nên nhất định phải có mặt. Yến tiệc đã ăn, võ cũng đã so, mắt thấy trời không còn sớm, hắn bước xuống khỏi đài tướng, chuẩn bị nhân lúc trời còn sáng quay về Hội Kê.
Phó tướng Kinh Thiện vội vàng đuổi theo. Chỉ là vừa đi được mấy bước, đã nghe phía sau truyền đến một trận huyên náo. Kinh Thiện tò mò quay đầu, liền thấy huynh đệ doanh một vừa rồi còn ở thế yếu, giờ đã được mọi người vây quanh tung lên cao, hiển nhiên đã giành được vị trí đầu trong cuộc tỷ võ.
Hắn lại một lần nữa cảm thán nhãn lực của mình vẫn chưa đủ. Nhưng thiên tư và trình độ của tướng quân cũng không phải ai cũng có thể dễ dàng theo kịp.
Rời khỏi võ trường, hai người không kinh động thành chủ rầm rộ đến tiễn đưa, chỉ để lại lời nhắn, rồi cưỡi ngựa trở về.
Dọc đường thuận lợi không trở ngại. Nhưng khi đến ngoài thành Hội Kê, Hoắc Yếm bỗng cảm thấy choáng váng căng tức, liền vội kéo dây cương dừng ngựa khẩn cấp.
Luồng tà khí này đến rất mạnh. Trong lòng hắn cũng theo đó nóng lên, ngũ tạng lục phủ như đều sắp bốc cháy. Nhất thời toàn thân nóng rực khó chịu, cổ họng khô khát vô cùng.
Phó tướng Kinh Thiện kinh hãi, vội xuống ngựa hỏi:
“Tướng quân, có phải âm độc kia lại phát tác rồi không?”
Ngoài phó quan thân cận của Hoắc Yếm, những người còn lại đều không biết rằng trong trận đại chiến Ung Thành tháng trước, thật ra Hoắc Yếm đã bị trúng tên. Hơn nữa, trên mũi tên ấy có tẩm kỳ độc. Tuy nhất thời không lấy mạng người, nhưng lại liên tục giày vò vô cùng.
Từ lúc trúng tên đến nay, âm độc này tổng cộng đã phát tác hai lần. Mỗi lần phát tác đều là hỏa khí trống rỗng khô nóng khó tiêu, chỉ có thể tạm thời dựa vào nước đá để làm tê liệt.
Trong thời gian ấy, Kinh Thiện cũng từng thành khẩn đề nghị, nếu tướng quân thật sự khó nhịn được nhiệt ý trong lòng, có thể nạp một mỹ thiếp trong thành. Nhưng lại bị Hoắc Yếm khinh thường từ chối.
Sau đó, âm độc này tạm thời được thuốc khống chế. Bọn họ đều tưởng sẽ không tái phát nữa, huống hồ vết thương cũng đã gần khỏi hẳn. Nào ngờ hôm nay lại…
“Kinh Thiện, đưa ta về Hàn Trì. Dọn sạch toàn bộ người quanh vùng nước ấy!”
Hoắc Yếm căng chặt sắc mặt, mồ hôi dần túa ra trên trán, nghiến răng nghiến lợi căn dặn.
Kinh Thiện vội nhận lệnh:
“Vâng, tướng quân. Hàn Trì là hồ tắm riêng của tướng quân, kẻ khác sao dám tùy tiện vào đó.”
Nói xong, hắn do dự một phen, muốn nói lại thôi. Nhưng vì thân thể của tướng quân, hắn vẫn liều chết khuyên can:
“Tướng quân, độc tính hôm nay đến quá dữ. Thật sự… không cần nữ nhân sao?”
Sắc mặt Hoắc Yếm mang theo sắc đỏ nóng rực vì bị thiêu đốt, nhưng ánh mắt lại lạnh đến tận cùng. Hắn ngậm giận cảnh cáo:
“…Cút!”', '2026-06-01 09:57:03.87816+00'), (6, 2, 5, 'Chương 4: Nàng ở lại', 'Cuối cùng cũng đợi được đến khoảng chiều tối phát cơm. A Giáng rón rén trốn sau đống củi, khom lưng thò đầu quan sát. Xác nhận mọi người đã lần lượt rời lều đi nhận thức ăn, nàng vội lẻn vào doanh trại của cung nữ, trộm giúp Thi Nghê một bộ y phục cung nữ có kích cỡ đại khái vừa người.
Trang phục và phụ kiện của người Đại Lương phần lớn đều mộc mạc thanh nhã, màu sắc cũng nhạt và sạch. Còn váy áo lụa mỏng của Tây Lương lại theo phong cách cực kỳ rực rỡ, lộng lẫy và nồng diễm. Thi Nghê lo nếu mặc y phục của mình lén đi tắm, e rằng sẽ vì áo váy quá bắt mắt mà khiến người khác chú ý, cho nên mới bảo A Giáng đi trộm một bộ đồ cung nữ.
Nhanh chóng thay xong áo ngoài, để cẩn thận hơn, Thi Nghê lại búi tóc mô phỏng theo kiểu búi của người Đại Lương.
Nàng không có bản lĩnh gì khác. Ngoài giỏi múa nhạc, cũng chỉ có một đôi tay khéo biết vấn đủ loại búi tóc là còn có thể lọt vào mắt người sành sỏi.
Mọi thứ thu xếp xong xuôi, A Giáng vừa cẩn thận chỉ cho Thi Nghê vị trí con đường mòn dẫn đến khe nước trong rừng, vừa không nhịn được thành tâm khen ngợi bên cạnh.
“Ngũ quan của cô nương vốn diễm lệ đậm nét, ban đầu ta còn tưởng mặc váy áo thanh nhã của Đại Lương sẽ không hợp. Không ngờ đậm nhạt phối vào nhau lại hài hòa đến vậy. Theo A Giáng thấy, cô nương đúng là giá áo mỹ nhân trời sinh, mặc y phục tỳ nữ cũng sáng rỡ thế này. Càng đừng nói sau này đến Thượng Kinh, mặc những bộ hoa phục cầu kỳ của Đại Lương bọn họ thì sẽ đẹp đến mức nào.”
Thi Nghê nhìn dáng vẻ hai mắt phát sáng của nàng, hiểu ý mà nói:
“Vậy đợi đến Thượng Kinh, ta cũng sắm cho A Giáng một bộ đồ mới. Chọn kiểu y phục mới nhất đang thịnh hành ở Đại Lương, được không?”
Tiểu cô nương đương nhiên không ai là không thích làm đẹp. Nghe vậy, A Giáng vội gật đầu lia lịa như giã tỏi, sau đó lại cười híp mắt sáp đến gần Thi Nghê làm nũng.
“Cô nương thật tốt. Sau này A Giáng muốn mãi mãi đi theo cô nương, cô nương đi đâu ta cũng không rời.”
Nhìn dáng vẻ ngây thơ của A Giáng, trong lòng Thi Nghê khẽ thở dài một tiếng.
Bản thân nàng còn thân bất do kỷ, tiền đồ chưa định. A Giáng trung thành đi theo nàng, chưa chắc đã là lựa chọn tốt nhất.
…
Có A Giáng dò rõ tuyến đường từ trước, Thi Nghê đi suốt dọc đường cũng xem như thuận lợi. Chỉ là lúc sắp ra khỏi doanh, không khéo lại bị một binh lính tuần tra bắt gặp.
Thi Nghê vội xoay người giấu mặt đi, lập tức chỉ cảm thấy sau lưng lạnh toát, căng thẳng đến mức tim cũng sắp nhảy ra ngoài.
Nhưng may mà, thấy nàng mặc y phục cung nữ Đại Lương, tên lính tuần tra kia rất nhanh đã buông lỏng cảnh giác, chỉ liếc nhìn hai cái rồi xem như chuyện thường mà tiếp tục đi về phía trước.
Còn Thi Nghê thì vẫn chưa hoàn hồn, cứng đờ tại chỗ, bị dọa đến toát mồ hôi lạnh.
Sau đó, Thi Nghê men theo tuyến đường A Giáng đã miêu tả, cứ đi thẳng về phía trước theo con đường nhỏ trong rừng. Nhưng sau cú kinh hãi vừa rồi, nàng bỗng không nhớ rõ lời A Giáng nói, ở ngã rẽ cuối cùng rốt cuộc phải rẽ trái hay rẽ phải.
Nàng nhíu mày do dự một lúc lâu, liền nghe trên con đường nhỏ bên phải vang lên mấy tiếng quạ kêu quái dị. Thi Nghê hơi sợ, theo bản năng cảm thấy A Giáng hẳn là nói bên trái. Vì vậy nàng xách vạt váy, không do dự nữa mà chạy thẳng về phía bên trái.
…
Nguồn nước trong veo, lối mòn hoang vắng thanh tĩnh.
Khi đến nơi, Thi Nghê hơi kinh ngạc, hoàn toàn không ngờ hoàn cảnh ở đây lại tốt đến vậy.
Ban đầu nghe A Giáng nói, tỳ nữ trong quân doanh thường đến đây tắm gội, nàng còn nghĩ khe nước này nếu đã bị người dùng đến, cảnh vật hẳn sẽ không còn nguyên sơ tự nhiên.
Nhưng cảnh tượng trước mắt, xanh biếc ngập tràn, dòng nước lặng lẽ chảy, cách bờ không xa còn có vài cây hoa dại đang độ vươn thẳng, tỏa ra hương thơm phảng phất.
Tóm lại, mọi thứ lọt vào mắt đều vượt xa dự đoán ban đầu của Thi Nghê.
Vì vậy nàng tràn đầy vui mừng, rất nhanh cởi áo ngoài ra, gấp gọn đặt bên bờ. Sau đó nàng để chân trần lội nước, cẩn thận bước xuống khe suối.
Thân thể dần thấm ướt, nhiệt độ nước cũng hơi lạnh. Thi Nghê thích ứng một lát liền cảm thấy khoan khoái, lại giơ tay vốc nước từ trên cao tưới xuống hõm vai.
Ở trong quân doanh ngột ngạt đã lâu, giờ phút này thật sự là khoảng thời gian thư thái hiếm có.
Mắt thấy ban đêm yên tĩnh, nơi này lại ít dấu chân người, Thi Nghê nghĩ ngợi một lát, bèn định cởi dây buộc áo trong trên người, để có thể tắm rửa sát da sạch sẽ hơn một chút.
Huống hồ dòng suối này trong veo mát lành như vậy, nếu cách một lớp y phục thì chỉ cảm nhận được năm phần, thật sự đáng tiếc.
Nàng dùng một tay đi cởi. Chiếc cổ trắng nõn trong suốt dưới ánh trăng theo đó khẽ ngửa lên, cổ tay mềm mại như sương tuyết.
Chỉ là dây buộc thấm nước hơi khó cởi. Thi Nghê bất đắc dĩ chỉ đành cúi đầu nghiêm túc tháo. Sau đó phí rất lâu sức lực, cuối cùng mới cởi được hai nút dây, bờ vai thơm và xương quai xanh cũng theo đó lộ ra ngoài, trắng trong như tuyết.
Trong đêm tối, nàng không nghi ngờ gì chính là sắc trắng bắt mắt nhất, thậm chí còn mê hoặc rối mắt hơn cả ánh trăng sáng.
Mắt thấy sắp hoàn toàn gỡ bỏ lớp y phục ngăn cách, Thi Nghê giãn mày thở phào một hơi. Nhưng hơi thở ấy còn chưa kịp buông hết, sau lưng nàng bỗng vang lên tiếng nước bắn tung tóe dữ dội, tựa như có người từ dưới mặt nước chui lên.
Nơi này vậy mà còn có người khác sao?
Thi Nghê kinh hãi trong thoáng chốc, chưa kịp phản ứng, cổ đã bị người ta từ phía sau dùng một con dao găm sắc bén mạnh mẽ kề vào.
“Ai?”
Một giọng nói xa lạ lại đặc biệt trầm nặng bỗng truyền vào tai Thi Nghê. Giọng điệu cảnh giác rõ ràng khiến nàng trong nháy mắt nhận ra nguy hiểm.
Đối phương là nam tử. Nhưng trước mắt, Thi Nghê đã không còn tâm trí để bận tâm đến tình trạng y phục xộc xệch, gần như nửa hở của mình lúc này, cũng không dám trách hắn vì sao vô lễ như vậy, lại trực tiếp vươn tay siết chặt lấy eo nàng, áp sát không chút khe hở.
Nàng căn bản không dám động đậy. Lúc này con dao găm đặt ngang cổ nàng đã khẽ cứa qua bề mặt da thịt.
Rất rõ ràng, chỉ cần đối phương muốn, hắn có thể dễ dàng kết thúc tính mạng của nàng.
“Đừng… đừng giết ta.”
Giọng Thi Nghê không khống chế được mà run lên. Nàng trước giờ luôn là người tiếc mạng. Nếu không, vì sao nàng phải nhẫn nhịn nỗi chua xót sống nhờ nơi vương cung Tây Lương, và cả sự nhục nhã khi bị xem như lễ vật dâng đến Đại Lương?
Từ đầu đến cuối, nàng chỉ muốn sống cho thật tốt mà thôi.
Thấy người phía sau không đưa dao găm tiến thêm một tấc, Thi Nghê như nhìn thấy sinh cơ. Thần kinh căng chặt hơi thả lỏng, đầu óc cũng bắt đầu nhanh chóng xoay chuyển.
Chẳng lẽ gặp phải sơn tặc…
Thi Nghê ép mình bình tĩnh lại. Nhìn nơi này quả thật hai bên đều có núi bao quanh, nàng liền cảm thấy suy đoán của mình đại khái có bảy phần chắc chắn.
Nàng đang định thử thăm dò thương lượng với hắn, rằng mình bằng lòng để lại toàn bộ trang sức mang trên người cho hắn, chỉ cầu đối phương tha cho nàng một mạng.
Nhưng lời còn chưa kịp nói ra, nàng đã bị đối phương ôm vai trực tiếp xoay người lại. Vị trí dao găm không đổi, da thịt thoáng cảm thấy đau nhói.
Thi Nghê chợt linh quang lóe lên, đột nhiên nhớ đến những thoại bản giang hồ nàng từng xem trước kia. Nàng biết những kẻ cướp của thường không muốn bị người khác nhìn rõ dung mạo thật, nếu không sẽ giết người diệt khẩu. Vì vậy trong lúc xoay người, nàng rất thức thời nhắm mắt lại.
Kim loại lạnh cứng dời lên, dần dần nâng cằm nàng. Vì vậy Thi Nghê chỉ đành bị ép ngửa người lên, phối hợp để hắn quan sát.
Đúng lúc một trận gió mát lướt qua, Thi Nghê theo bản năng run nhẹ. Ngay sau đó nàng muộn màng nhận ra, bị hắn nhìn thẳng mặt như vậy, e rằng bản thân sẽ bị nhìn sạch…
“Là Kinh Thiện bảo nàng đến?”
Người kia cuối cùng cũng mở miệng lần nữa, nhưng lời nói lại khiến Thi Nghê không hiểu rõ.
Kinh Thiện… là ai?
Người này nàng căn bản không quen biết. Nhưng dục vọng cầu sinh trong lòng Thi Nghê lại nói với nàng rằng, có lẽ thừa nhận mới có thể sống.
Không nhận được câu trả lời, đối phương dường như hơi mất kiên nhẫn.
“Mở mắt, trả lời.”
Nàng không dám không nghe. Hàng mi khẽ run, Thi Nghê đành cắn răng chậm rãi mở mắt ra.
Đập vào mắt đầu tiên là một đôi đồng tử đen nhánh sâu thẳm như mắt chim ưng. Thi Nghê không ngờ, người có giọng nói thấm đầy lệ khí ấy, dung mạo lại tuấn nghị sáng sủa đến vậy.
Hắn dùng ngọc quan buộc tóc, chiếc quan hình bán nguyệt được chạm khắc tinh xảo khiến toàn bộ tóc được chải gọn ra sau không chút rối loạn. Cộng thêm thần sắc của hắn quá mức lạnh nhạt xa cách, cả người càng lộ vẻ uy nghiêm, lạnh lùng.
“Công tử có thể cho ta… mặc y phục trước được không?”
Thi Nghê khẽ giọng cầu xin. Lúc này bị khí thế bức người của hắn bao phủ, nàng thậm chí không dám ngẩng mắt đối diện với hắn.
Nghe tiếng, Hoắc Yếm hơi hạ tầm mắt xuống. Ánh mắt khựng lại một thoáng rồi rất nhanh dời đi, vẻ mặt lộ ra chút giễu cợt khó đoán.
Hắn xem sự lảng tránh không đáp của Thi Nghê là ngầm thừa nhận.
“Nàng là nữ tử nhà lành ở thôn trang gần đây?”
Có thể trong thời gian ngắn như vậy tìm được một nữ tử có dung mạo thế này đến Hàn Trì hầu hạ, cũng chỉ có khả năng này.
Hoắc Yếm thu lại ánh mắt, chăm chú đánh giá gương mặt Thi Nghê. Hắn chưa từng để ý đến dung mạo tư sắc của nữ tử, nhưng người trước mắt này quả thật là đẹp đến mức khiến người ta vui mắt. Có thể thấy Kinh Thiện thật sự đã tốn một phen tâm tư, chỉ sợ hắn sẽ lại từ chối.
“Ta… ta chỉ muốn đến tắm rửa, không biết sẽ quấy nhiễu công tử. Ta lập tức đi ngay.”
“Đi?”
Hoắc Yếm cười nhạo trò vờ muốn rời đi để khơi gợi của nàng quá vụng về. Tiếp đó, hắn mạnh mẽ vươn tay ôm người vào trước ngực, ánh mắt u ám, trầm giọng hỏi:
“Cứ đi như vậy, nàng giao việc được sao?”
Không biết là đôi mắt khiếp sợ của nàng quá mê hoặc lòng người, hay là xúc cảm mềm mịn dưới lòng bàn tay khi đặt trên eo nàng quá bỏng rát. Tóm lại, ngọn lửa trong lòng Hoắc Yếm vừa rồi phải dựa vào việc lặn xuống đáy Hàn Trì mới miễn cưỡng đè xuống được, lúc này lại như cỏ xuân gặp gió, cháy lan khắp đồng.
Hắn thừa nhận, phương thức giải độc mà trước kia hắn khinh thường nhất, giờ phút này hắn vậy mà thật sự sinh ra vài phần ý nghĩ muốn thử.
Hoắc Yếm khinh bỉ bản thân trong lòng một thoáng, thầm nghĩ nhất định là do lần này âm độc phát tác quá bá đạo, cộng thêm nữ nhân này còn cố ý ăn mặc không chỉnh tề để câu dẫn mới khiến hắn như vậy…
Ánh mắt Hoắc Yếm tối xuống. Lồng ngực và bụng càng lúc càng nóng đến khó chịu, trong lòng càng nghiến răng nghiến lợi thề rằng, đợi về quân doanh, hắn nhất định phải xử trí Kinh Thiện tự tiện làm chủ theo quân pháp!
Mà Thi Nghê bên kia vì tiếc mạng nên không dám tự tiện động đậy, càng không dám tùy ý trả lời, chỉ sợ thân phận nữ tử Tây Lương của mình bị phát giác. Nàng là lén trốn đến đây, nếu bị phát hiện rồi bị gán thêm tội bỏ trốn, e rằng cũng khó thoát khỏi cái chết.
Nàng đang như ngồi trên đống lửa, liền thấy sắc mặt hắn bỗng trở nên khó coi. Cả mặt lẫn cổ hắn dần dần nổi lên một mảng đỏ khác thường, trong ánh mắt càng giống như có từng đốm lửa nóng cháy.
“Công tử, ngươi… ngươi không sao chứ?”
Nàng thử dò hỏi, nhưng đối phương lại không trả lời. Hắn chỉ quay mắt đi, hung dữ bảo nàng mau mặc y phục vào. Thi Nghê cầu còn không được, vội vàng xoay người buộc chặt dây áo trước ngực.
Thái độ người này thật sự khó đoán. Sau khi chỉnh lại y phục, Thi Nghê theo bản năng lùi về sau một bước, rồi sắc mặt hơi đỏ lên vì xấu hổ. Vừa rồi áp sát một nam tử xa lạ ở khoảng cách gần như vậy, đối với nàng mà nói, thật sự là lần đầu tiên trong đời.
Hai người im lặng giằng co. Thi Nghê chờ đợi đến mức giày vò. Nàng chậm rãi ngẩng mắt, liền thấy đáy mắt đối phương thoáng hiện lên vẻ giằng co do dự, sau đó thần sắc căng chặt lại như đã thỏa hiệp mà hơi thả lỏng.
Nàng đang định thu hồi tầm mắt, nào ngờ lại bị bắt gặp ngay tại trận. Trong khoảnh khắc bị ép đối diện, nàng rõ ràng cảm nhận được đôi mắt nóng rực trước mặt thật sự như ngọn lửa thiêu đốt.
Ngay sau đó, đối phương áp sát, dao găm lại lần nữa kề trước mắt nàng.
“Nàng đến đây, Kinh Thiện đã dạy nàng phải làm thế nào chưa?”
Thi Nghê nhìn chằm chằm lưỡi dao găm kia, trái tim treo cao thật chặt, thầm nghĩ quả nhiên hắn vẫn có sát ý với mình.
Vì để giữ mạng, Thi Nghê vội dùng ánh mắt tỏ ra yếu thế. Trước mắt nàng cũng không còn cách nào khác, chỉ đành thuận theo lời hắn mơ hồ nói tiếp. Còn cái gọi là Kinh Thiện rốt cuộc là ai, nàng lại được yêu cầu phải làm gì, Thi Nghê căn bản hoàn toàn mờ mịt. Những lời nói ra cũng chỉ là bịa bừa để thử vận may.
“Đều… đều có thể làm, tùy công tử phân phó là được.”
Nói xong, nàng vội vàng yếu ớt bổ sung thêm một câu:
“Công tử tâm thiện, chỉ cầu công tử đừng làm hại tính mạng ta.”
Nghe nàng nói xong, trong đáy mắt Hoắc Yếm lóe lên một tia phức tạp mất tự nhiên, giọng nói cũng theo đó căng lại.
“Loại chuyện này, đại khái còn chưa đến mức hại mạng người.”
Không hại mạng người?
Thi Nghê bắt được trọng điểm trong lời hắn, trái tim treo lơ lửng hồi lâu cuối cùng cũng có thể rơi xuống. Vì vậy nàng vội mỉm cười đáp lời:
“Vậy thì tốt. Công tử cần ta làm gì, ta nhất định sẽ tận tâm tận lực.”
Khóe miệng Hoắc Yếm giật nhẹ. Hắn lặng lẽ nhìn nàng chớp đôi mắt đẹp sáng long lanh, dáng vẻ thật sự đáng thương yêu kiều.
Giờ phút này, hắn muốn cưỡng ép phân tâm nhưng căn bản không có tác dụng gì. Hắn nhìn Thi Nghê, đáy mắt quả thật đã nhuốm dục ý. Hắn không phủ nhận, mình đối với nữ tử có dung nhan quá mức yêu diễm trước mắt này cũng không đến nỗi quá phản cảm.
Nhất định là âm độc tà tính kia đang quấy phá.
Hoắc Yếm lại một lần nữa nhấn mạnh với chính mình trong lòng.
Hắn phất tay ném dao găm xuống khe nước bên cạnh. Mặt nước bị kích lên từng vòng gợn sóng, lưỡi dao chớp mắt chìm xuống.
Quay đầu lại, ánh mắt hắn lần nữa khóa chặt vào đôi mắt đẹp đang khiếp sợ trước mặt, trong lòng vậy mà nảy sinh ý niệm tà ác muốn phá hủy vẻ đẹp ấy.
Hoắc Yếm nhắm mắt lại. Khi mở ra lần nữa, hắn đã đưa ra quyết định.
Hắn giơ tay nắm lấy cằm Thi Nghê, ép sát lại gần, mở miệng nói:
“Nàng ở lại, giúp ta giải độc.”', '2026-06-01 09:57:43.424354+00'), (7, 2, 6, 'Chương 5: Nàng là người của ta', 'A Giáng bị bỏ lại một mình trong quân doanh, mắt thấy sắc trời càng lúc càng tối, trong lòng càng chờ càng nóng ruột.

Nàng khó tránh khỏi lo lắng, không biết lúc này Thi Nghê đã trên đường trở về hay chưa. Trong quân doanh, mỗi tối đều có người lần lượt đến từng lều kiểm kê nhân số. Nếu bị người Đại Lương phát hiện cô nương không có mặt, vậy sẽ bị chụp lên đầu trọng tội phản quốc.

Tội danh này, không ai trong các nàng gánh nổi.

Mắt thấy sắp đến giờ đánh chuông tắt nến, A Giáng hoảng hốt vội vàng trải chăn đệm của Thi Nghê cho ngay ngắn, sau đó lại lấy hai ba cái gối nhét vào trong chăn, giả vờ như bên trong có người.

Nàng không biết cách này có thể lừa được người khác hay không, vì vậy vừa luống cuống tay chân, vừa đổ mồ hôi lạnh ướt đẫm lưng áo.

Sau đó, bên ngoài truyền đến động tĩnh. Tiếng đội tuần tra càng lúc càng gần. A Giáng căng thẳng đi qua đi lại, tiếp đó lại nghe thấy giọng nữ quan dẫn đầu đang căn dặn mọi việc. A Giáng lập tức nhíu mày, thầm kêu một tiếng không ổn.

Người đến vậy mà là Phùng Chiêu, nữ quan không vừa mắt các nàng nhất.

Lần này hỏng rồi…

Rất nhanh đã đến lượt các nàng. A Giáng vội đi ra ngoài lều đứng ngay ngắn, nhưng nhóm tuần tra dường như chẳng hề để ý đến nàng, chỉ duỗi cổ nhìn vào trong lều. A Giáng vội lặng lẽ dịch sang bên một bước, chậm rãi chắn tầm mắt của người kia.

“Cô nương nhà ngươi đâu? Lề mề ở trong đó làm gì? Vào doanh mấy ngày rồi, nàng ta vẫn chưa chịu bỏ cái dáng vẻ chủ tử xuống, còn muốn tiếp tục bày giá ở đây sao?”

Lúc này, người mở miệng với giọng điệu không tốt chính là thủ hạ của nữ quan Phùng Chiêu. Trong lời nói đầy ý châm chọc, có thể nói là hùng hổ dọa người. Lại thấy Phùng Chiêu đứng một bên không hề có ý định lên tiếng, liền biết đây là chó cậy thế chủ.

A Giáng không kiêu không sợ, ép bản thân bình tĩnh.

“Đêm qua tóc cô nương chưa khô đã ngủ, hôm nay tỉnh dậy liền ho mãi, e là nhiễm phong hàn. Từ sau khi ăn tối đến giờ, cô nương vẫn luôn trùm chăn nghỉ ngơi. Mong đại nhân đừng trách cô nương lúc này bệnh yếu không dậy nổi.”

Nhưng đối phương lại không định dễ dàng bỏ qua. Nàng ta mở miệng không chút kiêng dè, lời nói cũng càng lúc càng khó nghe.

“Ho hai tiếng mà đã bệnh đến mức nằm liệt rồi? Người Tây Lương các ngươi chẳng phải ai nấy đều khỏe mạnh cường tráng sao? Sao đến nàng ta lại yếu liễu đón gió thế? Quả nhiên hồ ly tinh vẫn là hồ ly tinh, biết chủ soái sắp vào doanh, liền bắt đầu giả vờ mềm yếu để giành lòng thương hại.”

“Ngươi nói ai là hồ ly tinh!”

A Giáng nhíu mày hỏi lại, giọng điệu cũng gấp lên. Bản thân nàng chịu nhục không sao, nhưng nàng chính là không nghe nổi bất kỳ ai bôi nhọ Thi Nghê dù chỉ một chữ.

“Nói ai thì trong lòng tự biết, cũng không cần vội vàng tự nhận vào mình như thế. Suốt ngày chỉ biết bôi bôi trát trát lên người, thơm đến mức ong bướm cũng bị dụ tới. Định bò lên giường vị tướng quân nào đây?”

Nghe vậy, A Giáng tức đến toàn thân phát run, hận không thể lập tức nhào lên xé nát cái miệng thối của cung nữ kia. Lúc này nàng lại thấy may mắn vì cô nương không ở trong lều phía sau, nếu không những lời ác độc bẩn thỉu ấy e rằng sẽ làm bẩn tai cô nương.

“Mong các vị đại nhân cẩn lời! Cô nương nhà chúng ta dù có thế nào, cũng có phong hiệu công chúa ‘Thuấn Hoa’. Vào Thượng Kinh rồi, không phải vào hậu cung làm tiểu chủ thì cũng sẽ vào vương phủ hoàng tộc làm phu nhân. Một võ tướng cỏn con, đừng trách cô nương nhà chúng ta nhìn không thuận mắt!”

A Giáng nhịn không nổi nữa. Lần này rốt cuộc không nghe lời khuyên trước đó của Thi Nghê, tức quá liền đáp trả.

“Ngươi vậy mà dám xem thường võ tướng, thật buồn cười! Bao nhiêu thành trì biên quan của Tây Lương các ngươi đều bị Hoắc tướng quân dễ dàng công phá. Những thủ tướng Tây Lương kia vì giữ mạng, ai nấy đều phải quỳ xuống xin hàng Hoắc tướng quân. Xương sống cong xuống thuần thục lắm đấy. Bọn họ à, thậm chí ngay cả tư cách ngước nhìn Hoắc tướng quân cũng không có!”

A Giáng bị chọc mạnh vào nỗi đau, nghiến răng đỏ hoe mắt. Cho dù miệng lưỡi có sắc bén đến đâu, lời này nàng cũng không thể phản kích. Mẫu quốc chiến bại, đó là nỗi nhục khắc sâu trên sống lưng của mỗi một người Tây Lương.

Thấy khí thế của A Giáng trong nháy mắt biến mất, đáy mắt nữ quan Phùng Chiêu lóe lên một tia khoái ý vì đắc thắng.

Những lời vừa rồi nào phải chỉ nói cho một tỳ nữ nghe, mà là muốn để chủ tử phía sau nàng ta biết, cái gì mà công chúa Thuấn Hoa Tây Lương, cái gì mà mỹ cơ tuyệt sắc khuynh thành. Đặt chân vào địa bàn Đại Lương rồi, nàng Thi Nghê chẳng qua cũng chỉ là món đồ để mua vui cho nam nhân mà thôi.

Chỉ bằng nàng ta, cũng xứng được thái tử khen ngợi?

Khóe miệng Phùng Chiêu cong lên một nụ cười khô khốc đầy châm biếm.

Nhưng cũng may, Phùng Chiêu và đám người của nàng ta chiếm đủ tiện nghi ngoài miệng rồi, sau đó liền không tiếp tục kiên trì vào lều kiểm tra.

Đợi đoàn người đi khỏi, A Giáng lập tức mềm nhũn người, ngã ngồi bên bậc cửa, trong lòng đầy tủi thân và bất bình.

Vừa lo lắng vì sao cô nương còn chưa trở về, vừa nghĩ đến tiền đồ sau này lắm gian truân, nàng khó tránh khỏi thở dài.

…

Màn sao lay động, đêm tĩnh mịch dài lâu, nước lặng, gió cũng ngừng.

Hai cây hoa bên bờ khe nước nhân lúc ánh trăng bị một đám mây đen che khuất, bắt đầu lặng lẽ rũ những chùm hoa trên cành. Một cánh, hai cánh, phiêu nhiên rơi xuống.

Rơi bên bờ, rơi trên mặt nước, rơi lên hàng mi khẽ run của Thi Nghê.

Nàng bị nam nhân đột nhiên ôm vào lòng. Trong khoảnh khắc ấy, nàng kinh ngạc vô cùng. Bên tai đồng thời vang lên từng nhịp tim mạnh mẽ, khiến Thi Nghê không phân rõ đó là của mình, hay là của đối phương.

Hắn không làm gì khác, chỉ ôm nàng. Nhưng Thi Nghê vẫn sợ hãi. Bởi vì vừa rồi nàng phát hiện, trên người hắn thật ra không chỉ có một con dao găm. Lúc này, bên eo nàng đang bị một lưỡi dao cứng lạnh khác uy hiếp.

Thi Nghê rất mờ mịt. Nàng nhớ rõ ràng vừa rồi hắn mới nói sẽ không hại tính mạng nàng, sao chớp mắt đã thay đổi thái độ rồi?

Nơi này đêm tối gió cao, lại là ngoài hoang dã. Cho dù nàng lớn tiếng kêu cứu cũng chỉ phí công, thậm chí còn có khả năng chọc giận hắn. Vì vậy Thi Nghê khuyên bản thân nhất định không được hành động thiếu suy nghĩ.

Hoắc Yếm nhắm mắt, ghé sát bên tai nàng, tiếng thở càng lúc càng nặng.

“Nàng run cái gì?”

“Sợ… sợ chết.”

Thi Nghê lẩm bẩm thành thật trả lời. Toàn thân bị hơi nóng của hắn bao phủ, hun đến gò má nàng cũng nóng lên theo.

Hoắc Yếm không biết nàng đang giả vờ hay thật sự sợ hãi. Nếu đã là người đến dùng thân thể hầu hạ, vậy trong lòng hẳn nên có chuẩn bị. Cho nên lúc này hắn không hề thu liễm, còn ôm người nhẹ nhàng nhấc lên, khiến nàng hoàn toàn dựa vào người mình.

Thi Nghê kinh hô một tiếng, lập tức bỗng cảm nhận được có gì đó khác thường. Con dao găm vừa rồi hắn giấu bên eo, lúc này vậy mà đã đổi vị trí, chuyển sang uy hiếp bên chân nàng.

Mà Hoắc Yếm không bận tâm đến sự nhút nhát của nàng, chỉ lạnh giọng hỏi ngược lại:

“Nếu nhát gan như vậy, còn dám đến Hàn Trì hầu hạ? Ta thấy chỉ cần bị dọa một chút là nàng đã sắp rơi nước mắt rồi.”

Thi Nghê lúc này chỉ muốn giữ mạng là quan trọng nhất, vì vậy nhịn nỗi sợ, thương lượng với hắn:

“Ta, ta không rơi nước mắt. Ngươi có thể… vứt dao găm đi trước không?”

“Dao găm?”

“… Ừm.”

Ánh mắt khiếp nhược của Thi Nghê nhìn về phía hắn, dùng sức gật đầu một cái.

Hoắc Yếm không hiểu ý nàng. Con dao hắn cầm trong tay vừa rồi đã ném đi rồi, hơn nữa hắn xác nhận hôm nay ra ngoài tuần tra, trên người chỉ mang theo một thanh.

Hắn vừa định nói không có, lại đột nhiên cảm thấy bên dưới bị nàng cọ qua. Yết hầu hắn không nhịn được mà lăn nhẹ, lập tức hiểu ra.

Dao găm… nàng thật biết hình dung.

Vốn dĩ nhờ mượn hơi lạnh trên người nàng mới tạm thời xua đi được cơn nóng trong cơ thể, giờ lại trong nháy mắt cuồn cuộn ập đến, phủ kín toàn thân. Trong lồng ngực càng không thể đè nén luồng tà hỏa chạy loạn. Hoắc Yếm nghiến răng, thái dương bị khơi lên cũng theo đó giật nhẹ.

Hắn cho rằng dáng vẻ giả vờ thuần khiết này của Thi Nghê là đang cố ý câu dẫn. Vì vậy hắn siết chặt cằm nàng, dữ tợn mở miệng:

“Rốt cuộc nàng đến giúp ta giải độc, hay là muốn đốt cháy ta?”

Thi Nghê run rẩy đôi mắt trong sạch, căn bản nghe không hiểu lời hắn nói.

“Ta… ta không biết ngươi đang nói gì.”

Dáng vẻ nàng mờ mịt lại tủi thân, khiến Hoắc Yếm dù thật sự có tức giận cũng không biết trút vào đâu. Hơn nữa điều khó hiểu hơn là, cho dù biết nàng đang giả vờ, nhưng nhìn ánh mắt khiếp sợ của nàng, hắn vẫn không nhịn được mà nhường một bước.

“Thanh dao găm này không thể vứt.”

Quỷ mới biết vì sao hắn lại thuận theo lời nàng mà nói như thế.

“Vì sao?”

Không biết sống chết! Nàng vậy mà còn dám hỏi tiếp…

Hoắc Yếm đương nhiên xem đây cũng là chiêu trò cố ý trêu chọc của Thi Nghê, vì vậy như trả thù mà dùng sức bóp lấy vòng eo mảnh mai của nàng.

Lực tay hắn không nhẹ. Thi Nghê đau đến mức không nhịn được mà khẽ rên thành tiếng. Âm thanh mềm run ấy truyền vào tai hắn, Hoắc Yếm lập tức có một thoáng thần sắc kỳ lạ. Một cảm giác sảng khoái vô cùng kỳ dị khuấy động khiến da đầu hắn cũng theo đó tê rần.

Hắn thậm chí còn muốn nghe nữa.

“Cố ý trêu chọc ta?”

Hắn ghé sát lại, hơi thở nóng rực, suýt nữa đã cắn lên vành tai nàng.

Ánh mắt Thi Nghê hơi ẩm, né tránh lưỡi dao của hắn, liên tục cầu xin:

“Không dám…”

Hoắc Yếm căn bản không cho nàng né. Ánh mắt bức ép nhìn qua.

“Không dám? Ta thấy lá gan của nàng hẳn là lớn lắm. Nếu thật như lời nàng nói, e rằng ta không còn mặt mũi nào gặp liệt tổ liệt tông nữa.”

Thi Nghê lập tức bị dọa sững. Nghe vậy, nàng bày ra dáng vẻ rất dễ thương lượng:

“Ta không biết nó quan trọng như vậy. Vậy… vậy thì không vứt nữa.”

“…”

Hoắc Yếm nhìn dáng vẻ khiếp nhược của nàng, chỉ cảm thấy như đấm vào bông, có lực mà không chỗ dùng.

Trong tay lại cảm nhận vòng eo mềm mại mảnh mai không đầy một nắm của nàng, tâm trạng hắn vô cùng phức tạp. Trước kia hắn chưa từng biết nữ tử còn có thể như thế này.

Từ nhỏ đến lớn, hắn từng thấy sự đoan trang tao nhã của mẫu thân, sự ung dung hiền thục của các vị nương nương trong cung. Nghĩ thêm nữa, còn có các nữ tướng trong quân dứt khoát hiên ngang. Nhưng người trước mắt này lại hoàn toàn là một sắc xuân khác biệt.

Hoắc Yếm không hình dung được cảm giác cụ thể. Tóm lại, hắn sẽ muốn che chở nàng.

Nhưng đồng thời, hắn lại muốn hung hăng bắt nạt nàng. Tốt nhất là bắt nạt đến mức nàng rơi nước mắt.

Sự mâu thuẫn này khiến Hoắc Yếm vô cớ sinh ra ý muốn chiếm hữu. Nhất là hắn cảm thấy, nếu có thể nghe tiếng nàng khe khẽ nức nở, nhìn dáng vẻ vỡ vụn khi nàng luống cuống, đối với hắn mà nói, đại khái cũng có thể xem là một chiến lợi phẩm khá có cảm giác thành tựu.

Ý thức được suy nghĩ này hoang đường, Hoắc Yếm vội tĩnh tâm gạt bỏ tạp niệm. Hắn lại nhắc nhở chính mình, trước mắt việc quan trọng nhất là mượn thân thể nàng mau chóng trừ bỏ độc hỏa trong người, sau đó hắn nên cách xa nữ nhân giỏi mê hoặc lòng người này mới đúng.

Nhưng hắn vừa mới khó khăn tĩnh tâm lại, nữ nhân trong lòng lại bắt đầu không yên phận mà động tới động lui. Nàng nhẹ nhàng giãy ra, nhưng đáng tiếc sức lực quá nhỏ, động tác giãy giụa càng giống như đang cọ sát trêu chọc bên người hắn.

Nàng quyến rũ như vậy, sao còn có thể trách hắn không thu lưỡi dao lại.

Hắn căn bản không thu được.

“Còn động lung tung nữa.”

Giọng Hoắc Yếm khàn khàn, mang theo lời cảnh cáo không lành.

Nghe vậy, quả nhiên Thi Nghê không dám động nữa. Lúc này trong lòng nàng có chút cảm xúc, không nhịn được mà oán trách hắn hễ không vừa ý liền dùng lưỡi dao uy hiếp, thật sự quá đáng.

“Nếu ngươi không làm hại ta, vậy… vậy có thể thả ta ra trước không?”

Hoắc Yếm nhíu mày không động, dường như bất mãn vì nàng không làm tròn trách nhiệm.

“Kinh Thiện dặn dò nàng như vậy sao? Ta còn chưa khỏi, nàng chạy cái gì?”

“Cái gì… chưa khỏi?”

Thấy nàng lại đang diễn, Hoắc Yếm giật nhẹ khóe miệng, miễn cưỡng phối hợp giải thích một câu:

“Lại giả vờ. Kinh Thiện chưa nói rõ với nàng sao? Ta trúng một loại âm độc kỳ lạ, thân nhiệt quá cao không hạ xuống được. Người nàng rất lạnh, có thể giúp ta vận công giải độc.”

Nghe vậy, Thi Nghê cuối cùng mới bừng tỉnh. Nàng thầm nghĩ, chẳng trách nhiệt độ trên người hắn và hơi thở phả ra đều nóng rực. Ban đầu nàng còn tưởng hắn đang độ trẻ tuổi, hỏa khí cường thịnh, nên mới có chênh lệch thân nhiệt nam nữ bình thường. Không ngờ lại là do trúng độc.

Biết hành động trước mắt là có nguyên nhân, hắn cũng không phải kẻ xem mạng người như cỏ rác, nỗi sợ trong lòng Thi Nghê hơi giảm đi vài phần.

Nhưng cứ giằng co như vậy không phải cách. Mắt thấy trời đã tối, nếu không trở về e rằng sẽ liên lụy A Giáng. Vì vậy Thi Nghê do dự cúi mắt nhìn lớp áo lụa mỏng trên người mình, tiếp đó nhịn xấu hổ và sợ hãi, chủ động mở miệng:

“Người ta vẫn chưa đủ lạnh. Ngươi thả ta ra một chút trước đi, lát nữa… lát nữa lại ôm.”

Nàng không có thời gian tiếp tục dây dưa ở đây nữa. Để nâng cao hiệu quả, nàng chỉ đành tạm thời để bản thân chịu thiệt một chút.

Hoắc Yếm vốn không muốn mãi nhượng bộ nàng, nhưng nhìn ánh mắt nàng chân thành, giọng nói lại mềm mại dễ nghe, hơi do dự một chút, vậy mà thật sự nghe lời nàng, tạm thời buông người ra.

Không còn bị trói buộc, Thi Nghê lùi về sau một bước, sau đó gập gối, rụt toàn bộ thân thể vào trong nước. Nàng cố hết sức nín thở để bản thân có thể hoàn toàn thấm ướt, bởi vì như vậy mới có thể khiến thân nhiệt đủ lạnh.

Thật ra nàng còn có thể kiên trì thêm, nhưng không ngờ vừa mới chìm vào nước chưa được bao lâu, vai đã bị người ta siết chặt. Nàng còn chưa kịp phản ứng, cả người đã bị dễ dàng kéo lên khỏi mặt nước.

“Nàng điên rồi! Vừa rồi không phải còn sợ chết sao, bây giờ lại đang làm gì?”

Cơn giận âm ỉ của Hoắc Yếm bốc lên trong đáy mắt.

Thi Nghê thậm chí không giải thích. Vì muốn tranh thủ thời gian, nàng trực tiếp chủ động ôm lấy hắn, để hắn tự cảm nhận.

Nàng thử vòng tay ôm eo hắn, dựa theo cách giải độc vừa rồi của hắn mà cố gắng áp sát thêm một chút, lại nhẹ giọng nói:

“Bây giờ lạnh hơn một chút rồi. Ngươi mau vận công giải độc đi.”

Hoắc Yếm cúi mắt nhìn nàng với ánh mắt phức tạp, không động.

Không thấy hắn đáp lại, Thi Nghê vội ngẩng đầu nhìn hắn, chớp chớp mắt, không chắc chắn hỏi:

“Trên người vẫn chưa đủ lạnh sao? Vừa rồi nếu ngươi không kéo ta lên nhanh như vậy, để ta ngâm trong nước lâu hơn một chút, hiệu quả sẽ tốt hơn.”

Hoắc Yếm nhíu mày:

“Là vì ta?”

Thi Nghê chậm rãi gật đầu. Là vì hắn, nhưng chủ yếu hơn là vì chính nàng có thể nhanh chóng rời khỏi đây an toàn.

Đối phương dường như rất để tâm đến hành động vừa rồi của nàng, bày ra dáng vẻ muốn nói lại thôi. Nhưng cuối cùng hắn lại chẳng nói gì.

Rất lâu sau, hắn nặng nề thở ra một hơi, tiếp đó cánh tay thu lại, mạnh mẽ ôm người trở về. Một tay hắn đặt trên eo Thi Nghê, tay còn lại thì dùng tư thế khá cường thế bóp giữ sau gáy nàng.

“Nàng có thể giao việc với Kinh Thiện rồi.”

Trong lòng Hoắc Yếm đã có quyết định.

“Giao việc?”

Thi Nghê mở to đôi mắt ướt át, khó hiểu nhìn hắn.

Lần này, giọng hắn hung dữ. Hắn quay mặt đi, giống như đang cố ý giữ vẻ cứng rắn vì mất tự nhiên.

“Chẳng phải đã ôm nàng rồi sao, còn biết rõ mà cố hỏi cái gì?”

Hắn nói, đầu ngón tay đồng thời vuốt ve trên da thịt sau gáy nàng, từng chút từng chút, vừa tê vừa ngứa.

Thi Nghê hơi bị sắc mặt âm trầm của hắn dọa sợ, vì vậy giọng càng thấp:

“Không có cố ý…”

Hoắc Yếm nhìn dáng vẻ tủi thân như bị bắt nạt của nàng, ánh mắt hơi mờ đi. Tiếp đó, hắn vậy mà vô thức giơ tay như an ủi mà xoa xoa tóc nàng, sau đó dịu giọng lại:

“Khóc cái gì.”

Nói xong hơi khựng lại, hắn dùng đầu ngón tay lau đi giọt nước đang treo trên hàng mi Thi Nghê, giọng điệu nghiêm túc hơn mấy phần.

“Sau này, nàng là người của ta.”

Lời tác giả:

Hai bộ mặt của Hoắc tướng quân.

Trước đó khinh thường: Người Tây Lương xảo trá, nữ tử này vào kinh e rằng sẽ dùng sắc đẹp mê hoặc bệ hạ.

Sau khi nhận nhầm người: Nàng là người của ta, đưa người đến trướng của ta.', '2026-06-01 10:12:06.822388+00'), (8, 2, 7, 'Chương 6: Hoạ thuỷ', 'Là người của hắn…

Trước kia chưa từng có nam tử nào đứng trước mặt nàng nói ra những lời bá đạo mạnh mẽ như vậy. Nghe thấy, trong lòng Thi Nghê quả thật thoáng hiện lên một tia phức tạp.

Nhưng rồi nghĩ đến tình cảnh thân bất do kỷ của mình lúc này, lòng nàng lại càng thêm khổ sở. Nếu hắn biết nàng là lễ vật Tây Lương dâng lên hoàng tộc Đại Lương để tỏ lòng quy thuận, không biết có hối hận vì đã nói ra những lời vừa rồi hay không.

Có điều Thi Nghê cũng rất nhanh đã nghĩ thông. Trong lòng nàng thầm nghĩ, dù sao hắn cũng nhận nhầm người. Những lời này xem như vốn không phải nói với nàng.

Vì vậy nàng không đáp lời, chỉ nhỏ giọng nhắc nhở:

“Nhân lúc người ta vẫn còn lạnh, công tử mau lên.”

Hoắc Yếm tưởng nàng xấu hổ, trong lòng nhất thời sinh ra thương tiếc, lại ôm chặt nàng, ghé tai khẽ nói:

“Ừm, đừng sợ. Ta chỉ ôm nàng thôi, thanh dao găm kia… tạm thời cũng sẽ không hại người.”

“… Được.”

Sau đó, Hoắc Yếm nặng nề khép mắt. Hai người áp sát lồng ngực vào nhau, hắn mượn hơi lạnh từ thân thể mềm mại trong lòng, bắt đầu vận lực ép độc âm trong cơ thể xuống. Thi Nghê biết lúc này rất quan trọng, vì vậy mặc cho hắn ôm chặt, không dám tùy tiện mở miệng quấy rầy.

Ước chừng qua hai khắc, hàng mi hắn mới khẽ nâng, có động tĩnh.

Thi Nghê vội nhìn sang, liền thấy đáy mắt hắn đã khôi phục vẻ trong trẻo. Mà lưỡi dao đang áp bên đùi nàng cũng chậm rãi biến mất. Vì vậy nàng cũng thở phào nhẹ nhõm theo.

“Công tử đã… ổn rồi sao?”

Thân nhiệt Hoắc Yếm đã hạ xuống, nhưng hơi thở vẫn còn trầm nặng:

“Tạm thời ổn rồi. Chỉ là trước khi trừ tận gốc, vẫn sẽ luôn có tai họa ngầm.”

Nói xong lời này, Hoắc Yếm không tiếp tục giữ lấy nàng nữa, rất nhanh buông người ra, lại dặn nàng đi mặc áo ngoài vào, đừng để nhiễm lạnh.

Thi Nghê như được đại xá, nhanh chóng chuồn đi như bôi dầu dưới chân. Nhưng đi đến bên bờ, nhìn bộ y phục cung nữ nàng trộm được, động tác nàng khựng lại, trong nháy mắt không dám mặc nữa.

Bộ y phục này được đặc chế cho cung uyển, kiểu dáng rõ ràng, rất dễ nhận ra. Nếu nàng mặc vào, thân phận e rằng có nguy cơ bại lộ.

Mà Hoắc Yếm làm việc luôn nhanh gọn dứt khoát, tốc độ mặc y phục cũng nhanh hơn nàng rất nhiều. Khi hắn đi tới, liền thấy Thi Nghê vẫn chỉ mặc áo trong mỏng manh, ngồi xổm trên cỏ ôm một đống y phục không động đậy.

Nhìn xuống chân thì thấy nàng đã mang giày xong rồi.

Lần này hắn kiên nhẫn hơn một chút, không thúc giục, còn tháo áo choàng đen trên người xuống, khoác lên lưng Thi Nghê.

“Ngồi xổm ở đây ngẩn người làm gì? Còn không mặc vào, gió đêm sẽ khiến nàng chịu khổ đấy.”

Thi Nghê chột dạ đứng dậy, ôm chặt đống y phục thành một cục, tránh để hắn nhìn ra hoa văn hoàng gia chuyên dụng bên trên.

Nàng vội viện cớ qua loa:

“Ngươi quay người đi, ta mới mặc.”

Nghe vậy, Hoắc Yếm chỉ cho rằng nàng xấu hổ. Trong lòng vừa thấy thỏa mãn, vừa không cho là đúng, thầm nghĩ dù sao cũng đã là người của hắn rồi, còn có gì phải e thẹn không dám để người thấy.

Nhưng nhìn thân hình nhỏ nhắn mỏng manh của Thi Nghê, lại nghe gió đêm thổi qua, sợ nàng thật sự nhiễm lạnh, hắn chỉ đành tạm thời thuận theo nàng, dứt khoát xoay người đi.

Đồng thời hắn mở miệng nói:

“Sau này loại chuyện này, không cần tránh ta.”

Nếu đã ôm thân thể ướt đẫm của cô nương nhà người ta, Hoắc Yếm tự nhiên nghĩ đến việc phụ trách. Trong nhận thức của hắn, Thi Nghê hiện giờ đã xem như người của hắn, không cần câu nệ những chuyện này nữa.

Thật ra chuyện này đối với hắn cũng là ngoài dự liệu.

Hắn là người hành sát phạt trên chiến trường, sớm đã phó mặc sinh tử cho trời, chưa từng nghĩ sẽ quá sớm sa chân vào chuyện tình cảm nam nữ. Nhưng lần này ngoài ý muốn trúng độc, lại thêm thủ hạ tự ý làm chủ, kế hoạch cứ thế bị bất ngờ xáo trộn, nhất là vào đúng lúc vừa đại phá Tây Lương, thắng trận trở về.

Hơn nữa hắn cũng thừa nhận, nếu hôm nay người Kinh Thiện tìm đến là người khác, hắn sẽ không chỉ tùy tiện do dự một chút rồi muốn người đó.

Đã được gọi là Diêm La tướng quân, hắn sát phạt quyết đoán, đương nhiên không phải loại cỏ rác háo sắc khinh bạc. Hắn chỉ khi đối diện với đôi mắt đặc biệt lại nhút nhát như nai con kia, mới bằng lòng buông thả bản thân một lần.

Hoắc Yếm thu hồi suy nghĩ, trong lòng nghĩ hôm nay vẫn chưa thể trực tiếp đưa người về quân doanh. Ý chỉ của bệ hạ đã được truyền đến bằng thư khẩn nghìn dặm. Lần này hồi kinh, hắn mang hoàng mệnh trên người, phải phụ trách hộ tống mỹ cơ mà người Tây Lương đặc biệt dâng cho bệ hạ vào cung suốt dọc đường.

Người Tây Lương trước giờ xảo trá, Hoắc Yếm vô cùng khinh thường dáng vẻ mềm xương cầu hòa của bọn họ. Tự nhiên hắn cũng chẳng có thiện cảm gì với thứ hồng nhan họa thủy kia.

Hắn cảnh giác rất nặng, trong lòng đã nhận định cách làm lần này của hoàng thất Tây Lương là muốn dùng mỹ nhân kế để mê hoặc thánh thượng, ly gián tình thân giữa các hoàng tử.

Hoắc Yếm trung thành vì nước, trước mắt thánh mệnh khó trái, chỉ có thể đợi về đến Thượng Kinh rồi dâng thư khuyên can, đưa nữ tử này trả về Tây Lương.

Trước mắt, nữ tử Tây Lương kia đã chờ ở Hội Kê, quả thật khó giải quyết.

Mà hắn thân là chủ soái, vào doanh tự nhiên sẽ có nghi thức nghênh đón. Trong trường hợp như vậy, hắn thật sự không tiện cao điệu đưa nữ nhân của mình cùng vào, tránh vô cớ sinh ra vài chuyện rắc rối.

Vì vậy, Hoắc Yếm lấy từ trong ngực ra một tấm lệnh bài khắc chữ “Hoắc”. Sau đó vẫn giữ tư thế quay lưng, đưa ra phía sau, lại nói:

“Hôm nay ta không tiện trực tiếp đưa nàng về. Tấm lệnh bài này tạm thời giao cho nàng. Sau giờ ngọ ngày mai, nàng cầm lệnh bài này đến doanh Tử Sâm ở ngoại ô phía đông tìm ta. Khi ấy chỉ cần đưa lệnh bài này ra, tự nhiên sẽ có người dẫn nàng đến gặp ta.”

Lúc này Thi Nghê đã lộn ngược bộ y phục mặc vào. May mà kỹ nghệ may mặc của Đại Lương cao siêu, bên trong cũng không có chỉ thừa, hơn nữa mặc như vậy thì hoa văn cũng hoàn toàn đổi khác, có thể miễn cưỡng che giấu thân phận.

Nàng đang do dự không biết như vậy có thể che mắt được hay không, liền nghe hắn đột nhiên mở miệng, lại đưa một tấm thẻ gỗ tới.

Nàng phối hợp nhận lấy, nhìn ký tự bên trên, nhưng không biết chữ ấy có nghĩa gì.

Còn những lời hắn dặn dò, Thi Nghê tất nhiên không nghiêm túc nghe. Lúc này nàng một lòng chỉ muốn chuồn đi. Nghe vậy, nàng chỉ tùy tiện đáp một tiếng, lại vươn tay trả áo choàng cho hắn.

Hoắc Yếm không nhận, lại nói với nàng:

“Gió đêm lạnh, nàng cứ khoác đi.”

“… Ồ.”

Sau khi khoác lại áo choàng, Thi Nghê không nhịn được nhỏ giọng thúc giục:

“Ngươi đi trước đi, ta đi sau.”

Hắn còn chậm trễ tiếp nữa, bên A Giáng e rằng thật sự sẽ xảy ra chuyện. Lúc này Thi Nghê cực kỳ nóng ruột.

Hoắc Yếm nhìn dáng vẻ nàng cúi mắt không dám nhìn thẳng người khác, nào có thể nghĩ nàng vì chột dạ nên mới như thế. Thậm chí hắn còn một lòng tưởng rằng nàng lại vì ngượng ngùng nên mới không dám ngẩng mắt nhìn hắn.

Vì vậy mặt hắn vẫn cứng rắn lạnh lùng như cũ, giọng điệu lại vô thức dịu đi mấy phần:

“Có cần ta đưa nàng không?”

Lần này Thi Nghê đáp rất nhanh, lập tức vội lắc đầu từ chối:

“Không cần.”

Hoắc Yếm ừ một tiếng, xoay người đi được hai bước lại không nhịn được quay đầu, dặn dò nàng lần nữa:

“Đừng quên, sau giờ ngọ ngày mai đến tìm ta.”

Thi Nghê ngoài mặt mỉm cười nói được với hắn, trong lòng lại nghĩ, dù sao về sau cũng sẽ không còn cơ hội gặp lại nữa.

Cho dù lời nói dối bị vạch trần, hắn muốn tính sổ cũng không tìm được người nàng.

…

Trong quân doanh, A Giáng nghe tiếng huyên náo bỗng truyền đến từ tiền doanh, biết trong doanh nhất định đã có nhân vật quan trọng đến.

Các nàng ở Hội Kê chờ nhiều ngày, chính là để chờ chủ soái hồi thành, rồi cùng xuất phát đến đô thành Đại Lương. Trước mắt nếu trong doanh thật sự có đại nhân vật đến, không nghi ngờ gì chính là vị chủ soái tướng quân thần bí kia.

A Giáng không khỏi cầu nguyện trong lòng, thành tâm hy vọng vị chủ soái tướng quân này ngàn vạn lần đừng giống Phùng Chiêu đại nhân, sinh thành kiến với các nàng, hà khắc đối đãi. Nàng chỉ cầu cô nương có thể bình an đến Thượng Kinh suốt dọc đường, ngoài ra không mong gì khác.

Cảnh nghênh đón quả thật rất long trọng. Tiếng tù và uy nghiêm vang vọng, hàng thương kích xếp thành trận. Lúc này gần như tất cả mọi người đều đã đến tiền doanh xếp hàng hành lễ, chỉ có một mình A Giáng canh trong lều, gấp đến mức trán đổ mồ hôi, đi qua đi lại.

Thi Nghê chậm chạp chưa về, nàng chỉ sợ lát nữa có người truyền gọi các nàng cùng đến bái kiến tướng quân. Nếu thật sự như vậy, chuyện cô nương lén trốn khỏi doanh đi tắm e rằng không giấu được nữa.

May mà đợi động tĩnh ở tiền doanh hơi yên xuống, ngoài lều đột nhiên truyền đến một tiếng ho nhẹ như có như không. A Giáng hiểu ý nhìn qua, quả nhiên giây tiếp theo đã thấy Thi Nghê bước chân vội vã, mặt mang sắc đỏ, vén rèm đi vào.

“Cô nương, sao bây giờ người mới về? Thật sự làm A Giáng sốt ruột chết mất!”

Thấy Thi Nghê bình an trở về, tảng đá lớn treo trong lòng A Giáng cuối cùng cũng có thể rơi xuống. Nàng ghé đến bên Thi Nghê, lại sốt ruột quan tâm hỏi han một phen:

“Cô nương chậm trễ đến giờ, có phải trên đường xảy ra chuyện gì không? Chẳng lẽ bị binh sĩ tuần tra xung quanh phát hiện? Bọn họ có làm khó người không, hay có vô lễ động thô với người không?”

Thi Nghê chậm rãi bình ổn hơi thở. Vừa rồi để phòng nam nhân kia hối hận, nàng chạy một mạch trở về, gần như không có bước nào dám thả lỏng chậm lại.

Đời này lần đầu gặp sơn tặc, hiện giờ Thi Nghê hồi tưởng lại vẫn còn thấy sợ hãi. Hơn nữa hắn còn chiếm của nàng nhiều tiện nghi như vậy. Đợi nỗi sợ trong lòng hơi tan đi, liền chỉ còn lại xấu hổ và tức giận.

Thấy A Giáng vẫn đầy mặt lo lắng, Thi Nghê vội xoa dịu tâm trạng, mở miệng bảo nàng yên tâm:

“A Giáng yên tâm, ta không bị người khác phát hiện. Chỉ là lúc về nhớ nhầm đường, vòng tới vòng lui mấy lượt mới tìm được về, vì vậy mới chậm trễ thời gian.”

Chuyện ngoài ý muốn xảy ra với nam nhân kia thật sự khiến người ta khó mà mở miệng. Thi Nghê tự nhiên sẽ không nói với người ngoài, kể cả tỳ nữ thân cận mà nàng tin tưởng nhất. A Giáng tính tình hấp tấp, khó tránh có lúc miệng không kín.

Hơn nữa nghe nói dân phong Đại Lương bảo thủ nghiêm ngặt, từ trước đến nay rất coi trọng ranh giới nam nữ. Nữ tử chưa cưới gả mà từng có tiếp xúc da thịt với nam tử, tuyệt đối xem như chuyện nghiêm trọng vượt lễ cấm kỵ. Với thân phận đặc biệt của nàng, nếu cuộc gặp ngoài ý muốn hôm nay bị người khác biết được, e rằng sẽ dẫn đến không ít tai họa.

Nghĩ đến những điều này, Thi Nghê không thể không càng thêm cẩn thận.

Hai chủ tớ đang nói chuyện, bên ngoài bỗng truyền đến giọng một nữ quan xa lạ. Các nàng lập tức cảnh giác. Lại nghe lời sau đó mới biết hóa ra là Phùng Chiêu phái thủ hạ đến mời các nàng qua chủ doanh diện kiến chủ soái.

Từ khi các nàng từ Duy Viên đến đây, đã nghe nói chủ soái tướng quân bận quân vụ, đi đến thành lân cận, vì vậy các nàng vẫn chưa chính thức gặp mặt. Theo thông lệ, các nàng là lễ vật của nước bại trận, lẽ ra nên đến tham bái chủ tướng Đại Lương, biểu thị hàng phục.

Cho nên dù trong lòng Thi Nghê bất an sợ hãi, nàng vẫn không thể không nhận lời.

Nàng đang định mở miệng, lại bị A Giáng đột nhiên ngăn lại. Nàng hạ thấp giọng nói:

“Cô nương, vừa rồi khi Phùng Chiêu đại nhân kiểm kê nhân số, ta sợ chuyện cô nương ra khỏi doanh bị bại lộ, nên bất đắc dĩ lấy lý do cô nương nhiễm phong hàn để qua loa cho xong. Cho nên bây giờ…”

Nghe vậy, Thi Nghê phản ứng rất nhanh. Nếu A Giáng đã dùng lý do này, vậy lời nói dối ấy còn phải tiếp tục viên cho tròn. Đã như vậy, e rằng hôm nay các nàng không tiện đến tiền doanh lộ diện nữa.

Vì vậy Thi Nghê gật đầu, vội cởi y phục cung nữ ra giấu kỹ, lại lau sạch son trên môi rồi nằm vào trong chăn. Trên mặt nàng cố ý giả ra sắc bệnh tái nhợt. Cộng thêm vẻ mệt mỏi của nàng vốn không cần giả vờ, nên quả thật có thể đạt đến mức giống thật như giả.

Khi A Giáng dẫn nữ quan kia vào, Thi Nghê nằm co người trên giường, còn cố ý ho dữ dội vài tiếng. A Giáng bên cạnh thấy vậy vội cầu tình với nữ quan kia.

“Vị đại nhân này, cô nương nhà ta thân thể trước giờ yếu ớt. Lần này lại không cẩn thận nhiễm phong hàn, thật sự không tiện đứng dậy. Mức độ suy yếu của cô nương, đại nhân cũng đã thấy rồi. Không biết có thể xin đại nhân rộng lượng một chút, tạm hoãn chuyện diện kiến tướng quân lại một hai ngày được không?”

Nghe vậy, nữ quan kia nhíu mày tiến lên, thò đầu nhìn giường hai cái, tiếp đó mặt lộ vẻ khó xử, chỉ nói mình không thể làm chủ.

A Giáng dựa theo lời Thi Nghê đã dặn trước, nhân cơ hội thỉnh cầu:

“Bệnh của cô nương phát rất gấp. Hơn nữa nghe nói trong thôn gần đây có không ít người cũng nhiễm loại phong hàn tà bệnh này. Tuy triệu chứng khá nhẹ, nhưng lại dễ lây cho người khác. Đại nhân vẫn nên đứng xa một chút để bảo trọng quý thể thì hơn.”

Quả nhiên, nghe đến hai chữ “lây người”, nữ quan kia theo bản năng lùi về sau hai bước, ngay sau đó lại nâng tay áo che mũi miệng, bày ra vẻ ghét bỏ.

A Giáng cân nhắc rồi đề nghị:

“Nếu đại nhân không thể làm chủ, xin hãy giúp chúng ta trở về bẩm báo một tiếng cũng tốt. Nếu không, nếu thật sự lây cho quý nhân trong doanh, chẳng phải là tội của chúng ta sao?”

Nghe lời này, nữ quan kia nghiêm túc cân nhắc một chút, dường như cũng lo bị liên lụy. Vì vậy nàng ta nghiêm giọng, không tính là khách khí mà mở miệng:

“Thôi được rồi, ta về hỏi một tiếng là được. Trước khi triệu chứng giảm bớt, các ngươi nhớ đừng ra ngoài đi lại lung tung.”

Nữ quan vội vàng rời đi. Đại khái qua nửa nén hương, mới sai một tỳ nữ địa vị thấp đến truyền lời.

Tỳ nữ kia dường như cũng biết chút nội tình, sau khi đến thì nhất quyết không vào lều, chỉ làm ra vẻ nghiêm trọng đứng ở vị trí rất xa lều của các nàng, sau đó cất cao giọng báo rằng chủ soái đã đồng ý với thỉnh cầu của các nàng, bảo Thi Nghê yên tâm dưỡng bệnh, chọn ngày khác gặp lại.

Nghe vậy, Thi Nghê và A Giáng hơi thở phào nhẹ nhõm. Chuyện lén trốn khỏi doanh này xem như được lật qua ổn thỏa.

Đợi người đi rồi, A Giáng đỡ Thi Nghê từ trong chăn ngồi dậy, sau đó tự nói:

“Xem ra vị chủ soái tướng quân mà Đại Lương phái đến đón chúng ta cũng là một người khoan hòa. Sau này có ngài ấy ở đây, chắc hẳn Phùng Chiêu cũng sẽ thu liễm hơn, không đến mức tiếp tục hà khắc với cô nương như vậy nữa.”

Thi Nghê lại không dám tùy tiện đặt hy vọng lên người khác. Lúc này nàng lắc đầu thở dài một tiếng:

“Lần này Đại Lương tuy đại thắng, nhưng thật sự cũng có mấy nghìn binh sĩ tử trận. Quốc hận gia thù đan xen như vậy, muội nghĩ võ tướng Đại Lương nào sẽ vui vẻ hòa nhã với người Tây Lương chúng ta? Hắn không vì thế mà giận lây sang chúng ta, đã là may mắn rồi.”

Nghe lời này, A Giáng cũng không khỏi nản lòng. Các nàng một thân một mình đến dị hương, sau lưng không người chống đỡ, quả thật nơi nơi đều bị hạn chế, như đi trên băng mỏng. Thậm chí chỉ cần ai đó không vui, cũng có thể tùy tiện đến giẫm đạp các nàng vài cái.

Những uất ức này nàng có thể chịu, có thể nhịn, nhưng lại không nỡ để Thi Nghê chịu dù chỉ nửa phần.

Trong mắt A Giáng, Thi Nghê có dung mạo khuynh thành, sắc đẹp tuyệt thế hiếm có. Vốn ở vương điện Tây Lương, nàng được tôn sùng ái mộ, như một vị thần nữ tiên tử.

Hơn nữa lại có tam vương tử Thác Bạt Tắc yêu thương bảo vệ, cô nương tựa như mỹ nhân được cất giấu trong kim ốc, đi đâu cũng được người kính trọng cưng chiều. Bất kể ăn mặc sinh hoạt hay trâm vàng váy ngọc, thứ nào cũng đều hưởng loại tốt nhất.

So với cảnh ngộ trước sau, quả thật như một trời một vực. Trong lòng A Giáng khó tránh chua xót, lại nghĩ ngay cả nàng đã thấy như vậy, càng không biết trong lòng cô nương một mình chịu đựng bao nhiêu uất ức.

Thấy Thi Nghê không có gì khác thường, kéo màn xuống thay y phục, A Giáng thở dài một hơi, xoay người đi giúp Thi Nghê thu dọn bộ y phục cung nữ vừa cởi ra. Nàng đang định gấp lại cho ngay ngắn, lại bỗng sờ thấy bên trong có một tấm lệnh bài cứng, chất liệu như kim loại.

A Giáng khó hiểu lấy ra. Vừa mới xem xét hai cái, đã bị Thi Nghê nhanh tay lẹ mắt đoạt lại.

“Cô nương, đây là vật gì vậy? Sao nhìn không giống đồ của nữ nhi gia, lạ mắt lắm.”

Thi Nghê làm việc gì trước giờ cũng luôn chậm rãi thong dong. Đây vẫn là lần đầu tiên A Giáng thấy nàng hoảng hốt vội vàng như vậy, tựa như bị nhìn thấy bí mật gì không thể để người biết.

“Chỉ là đồ trang sức bình thường thôi, không có gì đặc biệt.”

Thi Nghê xoay người qua loa nói một câu, vội cất tấm lệnh bài kim loại có hoa văn phức tạp kia vào hộp trang sức của mình. Ngay sau đó lại cẩn thận ấn khóa ngầm xuống, trong lòng ảo não vì sự sơ ý bất cẩn của bản thân.

Lại nghĩ đồ của nam nhân kia không nên tiếp tục giữ bên người, phải tìm một lúc không có ai lén xử lý đi mới tốt.

Còn A Giáng đứng nguyên tại chỗ, không hiểu ra sao.

Trang sức của cô nương đều là nàng giúp thu dọn. Tấm yêu bài kim loại này nàng hoàn toàn xa lạ, nhưng không hiểu vì sao hoa văn màu đen vàng bên trên lại khiến nàng mơ hồ cảm thấy vài phần quen mắt, cứ cảm thấy như đã từng nhìn thấy ở đâu đó.

Nghĩ một lúc lâu vẫn không hiểu, A Giáng liền ném chuyện này ra sau đầu.

Nhưng các nàng không biết rằng, tấm lệnh bài chủ soái khắc chữ “Hoắc” đã bị khóa vào hộp gương. Mà giờ phút này ngoài quân trướng, quân kỳ Hoắc thị mang cùng chữ ấy đang tung bay phần phật trong gió, uy nghiêm đến lạ.

