Sống lại một đời, còn hiền lương thục đức làm gì nữa?

Thà để người khác chịu ấm ức, cũng đừng để bản thân phải khổ.

Nàng nói với thứ nữ:
“Con gái không cần tài hoa mới là có đức, tìm một nam nhân để gả mới là chuyện chính!”

Lại dạy dỗ thứ tử:
“Ăn chơi trác táng, cờ bạc rượu chè, kiểu gì cũng có một thứ hợp với ngươi!”

Còn đối với phu quân ruột thịt của mình thì:
“A Di Đà Phật, thiếp một lòng cầu phúc cho quốc gia, xin chàng hãy giữ mình, đoạn tuyệt nữ sắc!”

...', '2026-06-01 10:35:15.092485+00'), (10, 3, 1, 'Chương 1: Khuyên Nàng Rộng Lượng', '“Vãn Thu, con thân là chủ mẫu của Lục gia ta, đương nhiên phải có lòng bao dung, độ lượng!”

Tiếng ù vang trong đầu dần dần tan biến, tầm mắt cuối cùng cũng rõ ràng trở lại.

Trì Vãn Thu ngẩn ngơ đảo mắt nhìn quanh bốn phía.

Nàng thật sự đã trọng sinh rồi sao?

Nàng vậy mà lại trở về năm mười chín tuổi, một năm sau khi gả vào phủ tướng quân.

“Thiếu phu nhân, lão thái thái đang nói chuyện với người đấy!”

Tôn di nương của đại phòng lên tiếng nhắc nhở.

Trì Vãn Thu hoàn hồn, nhìn xuống phía dưới. Nơi đó đang đứng một nữ tử dáng người đẫy đà.

Hai bên tóc mai của nữ tử kia cài hai đóa hải đường nhiều cánh, cả người tỏa hương thơm nhàn nhạt. Đó chính là người trong lòng mà phu quân nàng mang về sau khi từ chiến trường trở lại — Mạnh Hương!

Bụng dưới của đối phương hơi nhô lên, rõ ràng đã có thai.

Lão thái thái thấy cháu dâu không đáp lời, lại bắt đầu đứng ra hòa giải:

“Thành thân hơn một năm rồi, bụng con vẫn chẳng có động tĩnh gì. Dù sao cũng phải nghĩ cho con nối dõi của Lục gia chứ!”

Trì Vãn Thu nói:

“Thưa tổ mẫu, ngày con thành thân, biên quan báo nguy. Phu quân vừa bái đường xong đã thay chiến giáp xuất chinh, một năm sau mới dẹp yên chiến loạn.”

“Bây giờ tuy người đã trở về, nhưng chàng lại chỉ ở thư phòng. Trong tình cảnh này, một mình con làm sao mà mang thai được?”

Nếu thật sự mang thai, Lục gia các người dám nhận sao?

Lão thái thái nghe xong lời này, ngược lại còn thở phào nhẹ nhõm:

“Nói như vậy, là con không đồng ý để Mạnh Hương vào cửa?”

Trì Vãn Thu thu hết sự thay đổi trên nét mặt bà ta vào mắt, trong lòng không nhịn được mà cười lạnh.

Thật ra bản thân lão thái thái vô cùng chán ghét nữ tử không rõ lai lịch trong viện kia. Chỉ là Lục Thừa Ân khăng khăng muốn đón người vào phủ, bà ta không muốn phá hỏng quan hệ với cháu trai, cho nên mới ném nan đề này cho cháu dâu.

Đời trước, vì không thể chấp nhận phu quân thanh mai trúc mã của mình đổi lòng, Trì Vãn Thu đã kiên quyết từ chối cho nữ tử kia vào cửa.

Kết quả, Mạnh Hương trở thành ngoại thất của Lục Thừa Ân.

Nữ tử kia vốn xuất thân thôn dã, lại có suy nghĩ trái luân thường, luôn rêu rao cái gì mà ai ai cũng bình đẳng, một đời một kiếp một đôi người.

Thậm chí nàng ta còn nữ cải nam trang, muốn trà trộn vào trường thi khoa cử, kết quả bị bắt ngay tại trận.

Triều đình còn tra ra nàng ta âm thầm chế muối tinh để buôn bán. Đây chính là trọng tội, trực tiếp liên lụy đến Lục Thừa Ân. Cả hai đều bị phán chém đầu!

Vì cứu Lục Thừa Ân, Trì Vãn Thu bôn ba khắp nơi, cuối cùng mới giữ được một mạng cho hắn, giảm thành mười năm tù.

Khi ấy, trong triều gần như chẳng còn ai muốn qua lại với Lục gia. Trì gia cũng muốn để Trì Vãn Thu hòa ly, nhưng lại bị nàng từ chối.

Mười năm qua, nàng vừa phải đề phòng những gian thương bên ngoài muốn xâu xé tài sản Lục gia, vừa phải dạy dỗ đệ đệ muội muội, đưa biểu cô nương xuất giá, lại thay lão thái thái lo liệu tang sự, mệt đến mức sinh ra một thân bệnh tật.

Khó khăn lắm mới đợi đến khi Lục Thừa Ân mãn hạn được thả, nàng chẳng nghe được một câu an ủi nào, trái lại còn hứng lấy một đống oán trách.

Biểu cô nương nói những năm qua nàng thường xuyên xuất đầu lộ diện, chắc chắn đã có dã nam nhân bên ngoài.

Nhưng nàng ta cũng chẳng nghĩ xem, năm đó nếu không có nàng trăm phương nghìn kế xoay xở, làm sao có thể giữ được Lục gia không bị liên lụy?

Người của đại phòng nói sổ sách cửa tiệm của nàng có vấn đề, chắc chắn nàng đã nuốt riêng tài sản Lục gia.

Nhưng bọn họ cũng chẳng nghĩ xem, nếu không có bạc để đút lót quan hệ, Lục Thừa Ân có thể bình an trong ngục suốt mười năm sao?

Còn về Lục Thừa Ân…

Hắn vậy mà lại oán hận Trì Vãn Thu năm đó không cứu được Mạnh Hương, hại mẹ con nàng ta một xác hai mạng!

Hắn còn nói, trong lòng hắn, Mạnh Hương mới là thê tử duy nhất!

Khi ấy, Trì Vãn Thu tức đến mức nôn ra máu.

Vì Lục gia, nàng đã vắt kiệt tuổi xuân và tâm huyết của mình.

Kết quả đám súc sinh này, ngay cả một đại phu cũng không gọi cho nàng.

Đường đường là con gái của nội các thủ phụ, vậy mà lại bị nhốt trong một viện vắng không người, sống sờ sờ bị bỏ đói đến chết!

Làm trâu làm ngựa hơn mười năm, nói cho cùng, là do chính nàng tự hạ thấp bản thân.

“Biểu tẩu? Tẩu làm sao vậy?”

Biểu cô nương Lâm Thần Thần đứng bên cạnh lão thái thái, giả vờ giả vịt quan tâm hỏi.

Thân thể Trì Vãn Thu cứng đờ. Chuyện cũ như khói thoảng qua, nàng ổn định tâm thần rồi mới nói:

“Ta không sao.”

Lão thái thái nói:

“Vãn Thu, nếu con đã không đồng ý tiếp nhận Mạnh thị, vậy cứ như thế đi! Chờ Thừa Ân trở về, ta sẽ phái người báo cho nó…”

Nhưng Trì Vãn Thu trực tiếp cắt ngang lời bà ta, mỉm cười nhìn nữ tử phía dưới.

“Con lại khá thích vị Mạnh cô nương này.”

Mạnh Hương liếc mắt nhìn sang, vẻ mặt kiêu căng.

Nha hoàn Cảnh Đông quát lạnh một tiếng:

“Phu nhân nhà chúng ta đang nói chuyện với ngươi đấy! Quỳ xuống trả lời!”

Trì Vãn Thu giơ tay, ra hiệu không sao.

Mạnh Hương khẽ cười khẩy:

“Ta cũng không phải nữ tử tầm thường. Chẳng buồn so đo với đám cổ nhân các người, tư tưởng vừa lạc hậu vừa hủ bại!”

Trong lời nói của nàng ta lại còn mang theo một vẻ thương hại từ trên cao nhìn xuống.

Trì Vãn Thu mở to mắt, hỏi ngược lại:

“Vậy tư tưởng của muội tiến bộ hơn sao?”

Mạnh Hương ngẩng đầu ưỡn ngực:

“Nữ tử vốn nên độc lập. Nhưng các người lại cam tâm làm vật phụ thuộc của nam nhân, chẳng đáng thương sao? Trên đời này ai ai cũng bình đẳng, ai kém ai chứ? Ta dựa vào đâu mà phải quỳ trước các người?”

Lão thái thái nghe đến mức nhíu chặt mày.

Lưu ma ma bên cạnh bà ta lập tức chỉ vào Mạnh Hương, mắng:

“Con tiện nhân không giữ nữ tắc, vậy mà dám nói ra thứ lời hỗn xược như thế!”

“Lão nô tài già! Ngươi chẳng qua chỉ là một con chó được chủ nhân nuôi mà thôi!”

Mạnh Hương trợn trắng mắt, sau đó kéo tay nha hoàn phía sau mình lại.

“Ta đối đãi với hạ nhân bên cạnh như tỷ muội ruột thịt, tuyệt đối sẽ không để họ quỳ trước ta. Không giống các người. Haiz, lễ giáo phong kiến đúng là hại người không cạn!”

Nàng ta càng nói càng không ra thể thống gì. Lão thái thái tức đến mức thở hổn hển.

“Thật là không có giáo dưỡng! Vãn Thu?”

Ánh mắt tất cả mọi người đều rơi xuống người Trì Vãn Thu, mong nàng mau chóng lên tiếng, đuổi nữ nhân điên này ra ngoài.

Thế nhưng, Trì Vãn Thu lại tỏ vẻ kinh hỉ, cảm thán:

“Muội muội, muội quả nhiên là một kỳ nữ! Khó trách tướng quân đối với muội tình sâu đến vậy. Sau này muội cứ ở lại đây đi!”

Mọi người đều kinh ngạc.

Trì Vãn Thu từ nhỏ đã ái mộ Lục Thừa Ân, hai người cũng coi như thanh mai trúc mã.

Năm đó nếu không phải nàng cố chấp hạ giá gả xuống, với gia thế như Lục phủ, làm sao có thể cưới được đích nữ của đường đường nội các thủ phụ?

Vậy mà bây giờ, nàng cứ thế chấp nhận một ngoại thất đang mang thai?

“Vãn Thu, con thật hồ đồ!”

Lão thái thái lập tức cuống lên.

“Sao có thể vì lấy lòng phu quân mình mà khiến nhà cửa sau này không được yên ổn?”

Trì Vãn Thu cắn khăn tay, nói:

“Nhưng dù sao nàng ấy cũng đã có cốt nhục của phu quân mà!”

Lão thái thái cố nén lửa giận:

“Tuy nói khai chi tán diệp cho Lục gia là chuyện chính sự, nhưng nhất định phải là nữ tử nhà lành, lai lịch rõ ràng!”

Nếu lỡ như nâng vào một kẻ còn dây dưa hôn ước không rõ ràng với nhà khác, hoặc là người thuộc tiện tịch, đều dễ để lại tai họa ngầm về sau.

Chuyện này liên quan đến thanh danh của cả gia tộc.

Mạnh Hương xoay chuyển tâm tư, sau đó bình tĩnh ứng đối:

“Nhà ta vì tránh loạn mà trốn vào núi sâu, nay chỉ còn một mình ta.”

Nhị phu nhân Vương thị lại là người mềm lòng:

“Haiz, không thân không thích, cũng thật đáng thương!”

Lão thái thái trừng bà ta một cái, thầm mắng đồ ngu, sau đó lại nhìn về phía Trì Vãn Thu.

“Vậy trước tiên cứ làm thiếp đi. Ở trong phủ dưỡng thân, nếu có thể sinh được con trai, sau này nâng lên làm di nương cũng chưa muộn!”

Trì Vãn Thu cúi đầu, mắt nhìn mũi, mũi nhìn tim, im lặng như không liên quan đến mình.

Ai ngờ, Mạnh Hương lại là người đầu tiên nhảy dựng lên phản đối:

“Ta mới không làm kẻ thứ ba của người khác đâu! Thừa Ân đã hứa với ta, sẽ cưới ta làm chính thê!”

Mọi người đều dùng ánh mắt như nhìn kẻ ngốc mà nhìn nàng ta.

Lão thái thái bị ồn đến đau đầu, trực tiếp sai người đưa nàng ta xuống.

Sự việc tạm thời được định đoạt, mọi người lần lượt tản đi.

Trở về Ngư Dược Các, Cảnh Xuân có chút lo lắng:

“Phu nhân, làm như vậy thật sự ổn sao?”

Lục Thừa Ân rất để tâm đến vị Mạnh cô nương kia, bây giờ lại chỉ định cho nàng ta một thân phận thiếp!

Chờ hắn trở về biết chuyện, chẳng phải sẽ làm ầm lên sao?

Trì Vãn Thu nhìn sân viện vừa quen thuộc vừa xa lạ trước mắt, thoải mái nằm xuống ghế đu.

“Mặc kệ hắn. Dù sao cũng không phải ta quyết định.”

Cứ chờ mà xem, sau này Lục gia còn có khối ngày gà bay chó sủa!', '2026-06-01 10:37:22.325994+00'), (11, 3, 3, 'Chương 2: Chỉ Muốn Hắn Chết', '“Phu nhân, Mạnh Hương kia vừa nhìn đã biết không phải người an phận. Chẳng qua là ỷ vào đứa bé trong bụng thôi, tướng quân nhà chúng ta nhiều lắm cũng chỉ mới mẻ với nàng ta vài ngày. Người không cần lo lắng!” Cảnh Xuân khuyên nhủ.

Trì Vãn Thu đương nhiên không lo.

Ngược lại, lúc này trong lòng nàng còn đang vô cùng sảng khoái. Có thể nói, nàng cực kỳ mong chờ những hành động tiếp theo của Mạnh Hương.

Đời trước, Mạnh Hương mang thai mà còn dám nữ cải nam trang, đại náo thanh lâu, nói cái gì mà giải phóng nữ nhân. Nàng ta còn ở Chiêu Hiền Quán cùng một đám nam nhân bàn luận quốc sự, không biết đã đắc tội bao nhiêu người.

Để một kẻ chuyên gây họa như vậy ở lại trong phủ, thật không dám tưởng tượng nàng ta sẽ chọc ra cái sọt lớn đến mức nào!

Trì Vãn Thu từng một lòng một dạ lo liệu, vun vén cho Lục gia, kết quả lại rơi vào kết cục như vậy.

Từ nhỏ đến lớn, tâm nguyện của nàng chính là được gả cho Lục Thừa Ân làm thê tử. Dù đối phương có nữ nhân khác bên ngoài, nàng vẫn tin chắc hắn chỉ nhất thời tham hoan.

Nhưng mãi đến khi Lục Thừa Ân phớt lờ mọi sự hy sinh nhiều năm của nàng, cố chấp nói rằng Mạnh Hương mới là thê tử duy nhất của hắn.

Cảm giác ấy giống như có người hung hăng đánh một gậy vào sau đầu nàng. Sau một thoáng choáng váng ngắn ngủi, cơn đau lại khiến người ta tỉnh táo đến lạ thường!

Cho nên đời này, đối với Lục Thừa Ân và Mạnh Hương, nàng chỉ có tôn trọng, chúc phúc!

Trì Vãn Thu ngồi trước gương, cẩn thận nhìn dung mạo của mình.

Trước đây, nàng lo liệu mọi chuyện lớn nhỏ trong phủ, mới ba mươi tuổi mà tóc mai đã điểm bạc, gần như sắp quên mất dáng vẻ vốn có của mình.

Tuổi trẻ thật tốt!

Cảnh Xuân bước tới, giúp nàng chỉnh lại những tua rua rối trên cây bộ diêu.

“Da phu nhân thật đẹp, trắng trong mịn màng, ánh mặt trời vừa chiếu vào trông như trong suốt vậy. Tướng quân sớm muộn gì cũng sẽ hồi tâm chuyển ý thôi!”

Trì Vãn Thu khẽ mỉm cười:

“Vậy sao?”

Ngoài cửa sổ, cây cối um tùm, trúc xanh lay động.

“Cảnh Xuân, ngươi đi chuẩn bị cho ta một thùng nước đá, loại thùng dùng để tắm ấy.” Trì Vãn Thu đột nhiên nói.

“Thiếu phu nhân muốn làm gì ạ?”

“Đừng hỏi nữa, mau đi đi.”

Rất nhanh, mọi thứ đã được chuẩn bị xong.

Trì Vãn Thu cho những hạ nhân khác lui xuống, tự mình cởi áo ngoài, sau đó chậm rãi bước vào thùng tắm, ngâm cả người trong làn nước đá.

Cứ thế ngâm suốt một canh giờ. Không ngoài dự đoán, đến chạng vạng, nàng bắt đầu phát sốt.

Mà lúc này, Lục Thừa Ân cũng đã hạ triều.

Biết được Mạnh Hương ngay cả thân phận di nương cũng không có, hắn làm ầm một trận trong viện của lão thái thái, sau đó hùng hổ xông đến Ngư Dược Các.

Hạ nhân thấy bộ dạng này của hắn thì vội vàng ngăn lại:

“Thiếu phu nhân bị bệnh, vừa uống thuốc xong đã ngủ rồi, xin ngài chờ…”

Lời còn chưa nói hết, người nọ đã bị Lục Thừa Ân đá văng ra.

“Trì Vãn Thu, rốt cuộc nàng có ý gì?”

Trong phòng, Trì Vãn Thu nằm trên giường mềm, đắp mấy lớp chăn. Bị đánh thức, nàng chậm rãi ngồi dậy.

“Khụ khụ… tướng quân về rồi… khụ khụ!”

Sắc mặt nàng mang theo một loại đỏ ửng cực kỳ bất thường, ngay cả giọng nói cũng yếu ớt không còn hơi sức.

Lục Thừa Ân sững người. Không ngờ nàng thật sự bệnh nặng đến vậy, hắn chỉ có thể cố gắng đè nén lửa giận, đi đến bên cạnh nàng ngồi xuống, mở miệng liền chất vấn:

“Nàng vậy mà chỉ để Hương Nhi làm một thị thiếp?”

Đối mặt với lời trách móc, Trì Vãn Thu chỉ nhàn nhạt đáp một câu:

“Đây là ý của tổ mẫu.”

Lục Thừa Ân bất mãn:

“Nàng đừng kiếm cớ! Hương Nhi từng cứu mạng ta, còn vất vả mang thai con của ta. Nếu nàng rộng lượng hơn một chút, kiên trì thêm một chút, chẳng lẽ tổ mẫu còn có thể bác bỏ thể diện của nàng, một chủ mẫu quản gia hay sao?”

Trì Vãn Thu lặng lẽ nhìn hắn, đồng thời còn phải cố kìm mình lại để không xông lên tát hắn một cái.

Người mà nàng ái mộ nhiều năm, hóa ra lại là một tên ngu xuẩn như vậy sao?

Nhưng thật ra Lục Thừa Ân chưa hề thay đổi. Thứ thay đổi chính là tình cảm của Trì Vãn Thu dành cho hắn.

“Cho dù Mạnh cô nương là con gái nhà lành, vẫn còn một vấn đề khác — quốc tang!”

Lục Thừa Ân nhíu mày, cảm thấy Trì Vãn Thu thuần túy chỉ đang ngụy biện.

“Thời gian quốc tang một năm đã qua rồi, nàng còn nhắc đến nó làm gì?”

Trì Vãn Thu nghiêm túc nói:

“Nhưng thai của Mạnh Hương đã được năm tháng rồi!”

Lục Thừa Ân chậm rãi phản ứng lại, sắc mặt dần dần trắng bệch.

Trì Vãn Thu nói tiếp:

“Ngày ngươi và ta thành thân, tiên đế đột nhiên băng hà, Bắc Địch xâm phạm, ngươi lập tức bị điều ra tiền tuyến. Bây giờ thời hạn quốc tang một năm vừa qua, ngươi đã từ chiến trường mang về một nữ tử mang thai bốn, năm tháng. Phu quân đã từng nghĩ đến hậu quả chưa?”

Sắc mặt Lục Thừa Ân lại trắng thêm một phần. Quả thật hắn chưa từng nghĩ đến điểm này.

“Nâng lên làm di nương nhất định phải đến quan phủ báo bị. Đến lúc đó, năm tháng sau nàng ta sinh con, thế tất sẽ khiến người khác chú ý. Lục gia chúng ta vốn xuất thân thương hộ, căn cơ trong triều có hạn. Cây bút của đám văn nhân kia, kẻ nào cũng độc địa hơn kẻ nào.”

“Đến lúc đó bọn họ sẽ nói thế nào? Nói Lục tiểu tướng quân trong thời gian quốc tang lại chơi nữ nhân trong quân doanh? Phu quân không sợ đồng liêu của ngươi nhân cơ hội này đổ một vài sai sót trên chiến trường lên đầu ngươi sao?”

Lục Thừa Ân nghe đến mức sau lưng toát mồ hôi lạnh.

Gia đình thương hộ muốn đi đường làm quan vốn đã không dễ. Nếu không phải hắn cưới đích nữ của nội các thủ phụ làm thê tử, e rằng đi đâu cũng bị người ta khinh thường.

Nhưng trong lòng hắn vẫn có chút không phục. Hắn vừa định giống như trước đây mà phản bác: “Chẳng phải vẫn còn Trì gia các nàng thay ta du thuyết trong triều sao?”

Nhưng khi hắn đối diện với đôi mắt trầm tĩnh pha lẫn lạnh nhạt của Trì Vãn Thu, những lời ấy lại không thể thốt ra được. Cuối cùng hắn chỉ có thể ngượng ngập nói:

“Xem ra tạm thời chỉ có thể như vậy.”

Trì Vãn Thu lại đẩy một xâu chìa khóa đến trước mặt Lục Thừa Ân.

“Dạo này thân thể ta không khỏe, không thể xử lý công việc trong phủ, có lẽ phải phiền mẫu thân rồi!”

Mắt Lục Thừa Ân sáng lên, dường như đã nghĩ đến một người thích hợp.

“Yên tâm, trong phủ không phải chỉ có mình nàng là có năng lực!”

Trong lòng Trì Vãn Thu cười lạnh. Hắn sẽ không cho rằng xử lý ăn mặc ở đi lại của mấy trăm người trên dưới Lục gia là chuyện đơn giản đấy chứ?

Lục Thừa Ân vội vàng trở về gặp mỹ nhân, đứng dậy nói:

“Nếu nàng đã nhiễm phong hàn, vậy ta không ở lại dùng cơm nữa.”

“Cũng được.”

Trì Vãn Thu tiễn hắn ra đến cửa. Bên cạnh vừa vặn đặt rượu mạnh mà Lục Thừa Ân mới mua về.

Lục Thừa Ân sợ nàng lại lải nhải, vội vàng giải thích:

“Một đồng liêu tặng, ta không uống đâu.”

Trì Vãn Thu lại cười vô cùng đúng mực:

“Phu quân chỉ có mỗi một sở thích này, thiếp sao lại ngăn cản chứ?”

Trong mắt Lục Thừa Ân hiện lên vẻ kinh ngạc. Hắn cảm thấy Trì Vãn Thu đêm nay đặc biệt dễ nói chuyện, nhưng cũng không nghĩ nhiều, xoay người rời đi.

Nhìn bóng lưng hắn, Cảnh Xuân không nhịn được nói:

“Nhưng rượu uống nhiều sẽ hại thân mà!”

Sắc mặt Trì Vãn Thu lại trầm xuống.

“Nữ tử lấy phu quân làm trời. Chỉ cần là thứ phu quân thích! Ngươi đi, mang hết rượu ngon cất trong kho đưa qua đó!”

Cảnh Xuân lập tức cúi đầu vâng lời.

Lục Thừa Ân khi chém giết trên chiến trường đã để lại không ít bệnh kín. Đặc biệt là một vết thương do tên bắn trên người, may mà khi ấy được Mạnh Hương cứu.

Nhưng y thuật của nàng ta chẳng cao minh gì. Dù bên ngoài trông như đã khỏi, vết thương ấy vẫn thường xuyên đau nhức.

Lục Thừa Ân ở chiến trường dùng thuốc không tiện, dần dần liền dưỡng thành thói quen uống rượu để giảm đau.

Cứ kéo dài như vậy, nhất định sẽ hại thân.

Trì Vãn Thu vốn lo hắn nghiện rượu, nên ngày nào cũng nhìn chằm chằm, vừa thúc giục hắn cai rượu, vừa khắp nơi tìm đại phu điều dưỡng.

Nàng còn quý trọng thân thể của hắn hơn cả chính hắn!

Nhưng đối phương chẳng những không nhớ đến cái tốt của nàng, trái lại còn cảm thấy nàng quản quá nhiều, suốt ngày giống như bà quản gia già, nhàm chán vô vị.

Lần này, Trì Vãn Thu sẽ không tự hạ thấp mình nữa. Thậm chí nàng còn sẽ hiền huệ chủ động sai người mang rượu qua!

Biết đâu một ngày nào đó, hắn lại “không cẩn thận” uống chết thì sao?

Đêm hôm ấy, nghe nói trong viện của Mạnh Hương náo loạn rất lâu, luôn miệng gào thét không chịu làm thiếp.

Nhưng sau đó, cũng không biết Lục Thừa Ân đã hứa hẹn gì với nàng ta, rất nhanh đã dỗ dành nàng ta ổn thỏa.', '2026-06-01 10:44:58.188556+00'), (12, 3, 4, 'Chương 3: Tự Xin Bị Hưu', 'Ngày hôm sau, Trì Vãn Thu ngủ đến khi tự tỉnh mới dậy.

Tuy nhiễm phong hàn nên hơi đau đầu, nhưng tinh thần nàng cũng không tệ.

Khi Cảnh Xuân chải tóc cho nàng, tiện thể bẩm báo chuyện trong phủ:

“Đại phu vừa mới tới, hình như lão thái thái bệnh rồi.”

Trì Vãn Thu kinh ngạc:

“Hôm qua chẳng phải vẫn còn khỏe mạnh sao?”

“Nghe nói vì biết tướng quân giao quyền quản gia cho Mạnh cô nương kia, lão thái thái không đồng ý. Hai bà cháu cãi nhau một trận, lão thái thái bị tức đến đổ bệnh!”

Trì Vãn Thu khẽ cười. Tám phần là lại giả bệnh rồi!

Lão thái thái này thích nhất là biết rõ mà giả hồ đồ.

Cứ lấy chuyện để Mạnh Hương vào cửa mà nói, rõ ràng chính bà ta không đồng ý, nhưng bà ta lại không chủ động mở miệng, mà ném nan đề cho Trì Vãn Thu. Bà ta luôn thích để người khác đi làm kẻ ác!

Đến khi thật sự không tránh được nữa, thì lại giống như hôm nay, giả bệnh.

Dù sao bà ta cũng là trưởng bối lớn nhất trong nhà. Thân là vãn bối mà làm lão tổ tông tức đến đổ bệnh, đó chính là bất hiếu. Chiêu này dùng lần nào cũng hiệu nghiệm.

Đáng tiếc, lần này trong chuyện của Mạnh Hương, bà ta đã đá phải tấm sắt rồi.

“Nếu đã là ý của phu quân, ngươi sai người mang cả đối bài và sổ sách trực tiếp đưa đến phòng Mạnh cô nương đi!”

Như vậy coi như Trì Vãn Thu đã ngầm thừa nhận quyền quản gia của Mạnh Hương.

Cảnh Xuân bĩu môi đáp lời.

Trì Vãn Thu trang điểm nhẹ, đánh phấn dày hơn một chút, khiến sắc mặt trông càng tiều tụy. Sau đó nàng khoác áo choàng dày, đi đến Thái An Uyển thỉnh an lão thái thái.

Đang đi được nửa đường, nàng đã nghe thấy tiếng quở trách ở phía trước.

Hóa ra là Tôn di nương của đại phòng. Người cúi đầu đứng đối diện bà ta, im lặng chịu mắng chính là Tiểu Cửu.

Nhìn thấy là hắn, Trì Vãn Thu theo bản năng dừng bước, dựng tai lắng nghe.

“…Bây giờ ngay cả bản thân ngươi còn nuôi không nổi, vậy mà còn đi nuôi một con chó rách không biết nhặt ở đâu về? Vừa bẩn vừa hôi, lỡ trên người nó có bọ chét thì sao? Tối qua nó rên ư ử suốt nửa đêm!”

Lục Cửu năm nay đã mười lăm tuổi, nhưng thân hình vô cùng gầy yếu. Rõ ràng đang ở tuổi phát triển, vậy mà nhìn bề ngoài cứ như chỉ mới khoảng mười ba.

Hắn cúi đầu, cũng không dám phản bác:

“Tiểu Hôi mới được một tháng, vẫn chưa cai sữa, ban đêm có lẽ là đói. Sau này con tuyệt đối sẽ không để nó quấy rầy người và đệ đệ nữa!”

Tôn di nương chẳng hề cho hắn sắc mặt tốt:

“Ngươi còn muốn sau này? Vừa rồi ta đã sai gã sai vặt ném con chó rách kia ra ngoài rồi!”

Lục Cửu khó tin ngẩng đầu lên:

“Ném đi rồi? Nhưng…”

“Nhưng cái gì? Ngươi không biết mình ở Lục gia có thân phận gì sao? Thật sự xem mình là chủ tử rồi à!”

Những lời phía sau càng lúc càng khó nghe. Trì Vãn Thu nhíu mày.

Nàng nhìn về phía Lục Cửu. Đối phương cúi đầu rất thấp, khiến người ta không thấy rõ vẻ mặt của hắn, chỉ có đôi tay siết chặt thành quyền.

Trì Vãn Thu nhớ lại đời trước, cuối cùng nàng bị giam trong biệt viện.

Hai nha hoàn bên cạnh nàng, một người vì muốn nàng được xem bệnh mà đâm đầu vào lưỡi đao chết thảm. Người còn lại muốn ra khỏi phủ báo tin cho Trì gia, kết quả bị đánh bằng loạn côn đến chết.

Người duy nhất còn lại từng đưa tay giúp nàng, chính là Lục Cửu này!

Khi ấy, Lục Thừa Ân không cho bất cứ ai đến xem bệnh cho nàng. Lục Cửu liền đợi đến nửa đêm, lén trèo tường vào, mang cho nàng ít thức ăn và thuốc viên.

Hắn coi như là người duy nhất trong Lục gia còn chút lương tâm.

Thế nhưng, hắn lại không phải người Lục gia thật sự, mà là nghĩa tử được Lục gia nhận nuôi.

“Sáng sớm mà Tôn di nương đã nổi giận lớn như vậy, Tiểu Cửu đã chọc gì đến ngươi sao?”

Trì Vãn Thu mỉm cười bước tới.

Hai người kia quay đầu nhìn sang. Lục Cửu lập tức khom người hành lễ.

Tôn di nương thong thả nói:

“Hóa ra là thiếu phu nhân. Ta dạy dỗ con nuôi của mình, chắc không có vấn đề gì chứ?”

Trì Vãn Thu cười nói:

“Đương nhiên không có vấn đề. Nhưng Tiểu Cửu cũng là nghĩa tử của lão thái gia, ít nhất cũng xem như nửa chủ tử. Ngươi ở trước mặt hạ nhân qua lại mà trách mắng hắn như vậy, e là không thích hợp lắm.”

Tôn di nương bĩu môi.

Lão thái gia đã chết bao nhiêu năm rồi! Ai còn quan tâm đến nghĩa tử của ông ấy chứ?

Nhưng lời này bà ta nào dám nói ra.

“Ta đang định đi thỉnh an tổ mẫu, chi bằng chúng ta đi cùng nhau đi!”

Trì Vãn Thu rõ ràng là cho Tôn di nương một bậc thang để xuống.

“Vậy được.”

Tôn di nương không cần thiết phải so đo trong loại chuyện nhỏ nhặt này. Nhưng sự chú ý của bà ta rất nhanh lại bị món đồ Cảnh Xuân ôm trong lòng thu hút.

“Đây là gì vậy?”

“Là mấy xấp gấm vóc Nam Cống nhà mẹ đẻ ta đưa tới, vừa hay chia cho mọi người.”

Trì Vãn Thu vừa ứng đối, vừa ra hiệu cho Cảnh Đông bên cạnh tiễn Lục Cửu một đoạn, cũng tiện thể nhắn vài câu.

Lục Cửu biết Trì Vãn Thu đang giúp hắn giải vây, không có ác ý, lúc này mới dám ngẩng đầu nhìn theo hướng các nàng rời đi.

Kết quả vừa đúng lúc đối diện với ánh mắt Trì Vãn Thu nhìn sang. Nàng mỉm cười với hắn.

Hắn đứng sững một lát, rồi mới rời đi.

Trên đường đoàn người đi đến Thái An Uyển, có hai người làm vườn đang thì thầm trong luống hoa.

“…Thiếu phu nhân xuất thân tốt cũng vô dụng… tướng quân lại quý Mạnh cô nương kia như bảo bối… sau này trong phủ này e là phải đổi chủ…”

Tuy chỉ nghe rõ vài từ, nhưng cũng không khó đoán bọn họ đang bàn tán chuyện gì.

Thật ra Tôn di nương rất vui khi thấy nhị phòng bị chê cười, nhưng ngoài mặt vẫn phải giả vờ một chút:

“Thiếu phu nhân, đừng để trong lòng!”

Trì Vãn Thu nhàn nhạt mỉm cười.

Đợi hai người đến Thái An Uyển, Lâm Thần Thần đang hầu hạ lão thái thái uống thuốc.

Tôn di nương lập tức hỏi han ân cần:

“Bệnh của lão thái thái có nghiêm trọng không?”

Lão thái thái dùng tay chống trán, nghiêng người tựa trên giường thấp:

“Già rồi, vô dụng rồi. Dù là cháu ruột, cũng chẳng xem bà già này ra gì!”

Sau đó bà ta lại liếc xéo Trì Vãn Thu một cái:

“Ta nghe nói, con đã đưa cả đối bài và sổ sách đến chỗ Mạnh Hương rồi?”

Trì Vãn Thu gật đầu, giọng điệu hơi mang oán trách:

“Vâng. Phu quân đã hạ lệnh giao quyền quản gia cho nàng ấy, con không dám trái lời.”

“Hừ!”

Rõ ràng lão thái thái rất có ý kiến với nàng.

Lâm Thần Thần bên cạnh lại là người đầu tiên chú ý đến lễ vật mà các nha hoàn đang bưng.

“Gấm này thật đẹp!”

Theo lý mà nói, thứ như vậy đáng lẽ phải để lão thái thái chọn trước. Nhưng Lâm Thần Thần lại mang vẻ mặt đương nhiên, trực tiếp chọn xấp đẹp nhất.

“Vậy ta miễn cưỡng lấy cái này vậy!”

“Được, đều cho con!”

Lão thái thái cưng chiều gật đầu.

Hiển nhiên mọi người cũng đã sớm quen rồi. Dù sao trong phủ, ai chẳng biết biểu cô nương là bảo bối trong lòng lão thái thái.

Lục lão thái thái tổng cộng sinh được ba người con. Trưởng tử theo đường buôn bán, thứ tử tòng quân vào triều làm quan, tiểu nữ nhi thì gả cho một vị quan kinh thành.

Cũng chính nhờ tầng quan hệ thông gia này, Lục gia mới có cơ hội dọn đến kinh đô.

Đáng tiếc, tiểu nữ nhi gả qua đó không lâu thì bệnh mất, chỉ để lại một cô con gái mồ côi, cũng chính là Lâm Thần Thần.

Lão thái thái thương xót, liền đón nàng ta đến bên cạnh mình nuôi dưỡng.

Thế nhưng, Trì Vãn Thu lại cầm xấp gấm kia về.

“Không được.”

“Chỉ là một xấp gấm thôi mà!”

Lâm Thần Thần cảm thấy mất mặt, giọng nói có chút không vui.

“Biểu tẩu cần gì phải keo kiệt như vậy?”

Lão thái thái không vui nhìn về phía Trì Vãn Thu:

“Phần của ta không cần nữa, đưa cho con bé là được chứ gì!”

“Xấp gấm này là để tặng Mạnh cô nương.”

Vẻ mặt Trì Vãn Thu nghiêm túc, lại nhìn Lâm Thần Thần, lời nói thấm thía:

“Biểu muội, Mạnh cô nương không chỉ là thiếp thất trong phủ, nàng ấy còn là ân nhân cứu mạng của ca ca muội. Muội phải hiểu chuyện một chút!”

“Ta không hiểu chuyện chỗ nào?”

Lâm Thần Thần vừa ấm ức vừa không cam lòng. Tâm trạng tốt đẹp ban nãy lập tức tan biến sạch sẽ. Nàng ta đẩy đồ ra.

“Thôi, ta không cần nữa.”

Nàng ta bắt đầu giở tính tiểu thư, chờ người khác đến dỗ dành.

Thế nhưng lần này, Trì Vãn Thu căn bản không thèm để ý đến nàng ta.

Lão thái thái cảm thấy cháu dâu này càng ngày càng không ngoan thuận, sắc mặt trầm xuống, lên tiếng giáo huấn:

“Trưởng tẩu như mẹ. Sao con có thể ức hiếp muội muội của mình như vậy? Đừng tưởng Thừa Ân trở về, có người chống lưng cho con, thì con không xem bà già này vào mắt!”

Mọi người không dám lên tiếng. Ai cũng biết lão thái thái đang đem sự bất mãn với cháu trai trút giận lên người cháu dâu.

Trì Vãn Thu lại bình tĩnh đứng dậy, lấy từ trong tay áo ra một tờ giấy đặt lên bàn.

“Tổ mẫu dạy rất phải. Vậy thì xin Lục gia hưu con đi!”

Thân thể lão thái thái lảo đảo. Lần này bà ta suýt nữa thật sự ngất xỉu.', '2026-06-01 10:53:34.188566+00'), (13, 4, 1, 'Văn án', 'Đêm Tân Hôn, Thái Tử Điên Cuồng Đoạt Ta Vào Cung
Tác giả: Quy Yến
Thể loại: Ngôn tình
Tình trạng: Hoàn thành
【Cường thủ hào đoạt + truy thê hỏa táng tràng + nam chính điên cuồng như chó dữ】
Trước năm mười sáu tuổi, Khương Dung Âm là đích công chúa, được vạn người kính ngưỡng, cao quý đến mức không ai dám với tới.
Sau năm mười sáu tuổi, Khương Dung Âm trở thành con chim hoàng yến được Khương Quân nâng niu trong lòng bàn tay, có vùng vẫy thế nào cũng không thể thoát khỏi hắn.
Thế nhân đều ca tụng Thái tử điện hạ thanh cao sáng trong như gió mát sau mưa, là bậc quân tử ôn nhuận như ngọc, là người tốt hiếm có trên đời.
Nhưng chỉ có Khương Dung Âm biết, ẩn sâu trong cốt tủy hắn là sự cố chấp đến bệnh hoạn, là tuyệt tình và máu lạnh.
Mỗi khi đêm xuống, sự chiếm hữu điên cuồng của hắn, từng tiếng “hoàng huynh” nàng gọi ra, đều hóa thành chiếc lồng giam cầm nàng không lối thoát.
Người mở miệng giữ lại kẻ giả mạo như nàng là hắn.
Nhưng đến cuối cùng, người muốn giết nàng cũng chính là hắn.
Ngày ấy trên đại điện, tiểu vương gia của nước Đại Diệu mở lời cầu cưới Khương Dung Âm. Nàng đan mười ngón tay với người ấy, nói rằng hai người lưỡng tình tương duyệt, tình sâu không hối.
Tiếng áo giáp va chạm vang lên lạnh lẽo, nam nhân từng bước tiến tới.
Giọng hắn rét buốt, ẩn chứa cơn giận đang bị đè nén, tựa như giông bão sắp ập xuống.
“Lưỡng tình tương duyệt?”
“Nàng chính là dùng cách này để lừa cô sao?”
Khương Quân đương nhiên biết nàng lấy lòng hắn là vì điều gì. Vậy nên những lời nàng dịu dàng dỗ dành hắn, ngay từ đầu, hắn vốn chẳng tin lấy một chữ.', '2026-06-01 11:03:32.078291+00'), (14, 4, 2, 'Chương 1: Tiểu Cửu của cô muốn gả cho ai?', 'Sau cơn mưa, trời vừa hửng sáng. Khương Dung Âm ngồi trước cửa Quang Hoa điện, lặng lẽ nhìn những giọt mưa tí tách rơi xuống từ mái hiên.
“Công chúa.”
Cung nữ Bảo Ngân bước tới, vừa chạm phải ánh mắt nàng, trong mắt đã lộ vẻ đau lòng.
“Điện hạ từ Giang Nam trở về rồi, lúc này đang ở Khôn Ninh cung. Vừa rồi nô tỳ gặp Chung cô cô, cô cô nói Hoàng hậu nương nương mời người qua đó.”
Câu nói ấy khiến Khương Dung Âm lập tức đứng bật dậy, trái tim cũng trầm xuống một đoạn.
Sao Khương Quân lại về nhanh như vậy?
Vậy kế hoạch của nàng…
Bàn tay buông bên người của Khương Dung Âm khẽ siết chặt hơn.
Nàng không muốn gặp Khương Quân.
Càng không muốn nhìn thấy hắn, rồi lại nhớ đến những đêm dài khổ sở khó chịu kia.
Là cổ tay bị mài đến đỏ ửng, là khóe mắt đỏ hồng vương đầy hơi thở của Khương Quân, còn có những lời hắn ép nàng phải nói.
Đối với Khương Dung Âm mà nói, bất cứ điều nào trong số ấy cũng đều là ký ức nàng không muốn nhớ lại.
Một năm trước, Khương Quân theo đại quân nhà họ Ngụy trở về kinh thành. Chỉ trong một sớm, Khương Dung Âm từ đích công chúa lại biến thành công chúa giả.
Còn Khương Quân, người bị Khương Dung Âm chiếm mất thân phận suốt mười sáu năm, thì được lập làm Thái tử, phong quang vô hạn.
Đến lúc này, mọi người mới biết Khương Dung Âm chẳng qua chỉ là món hàng giả mà năm xưa Hoàng đế tìm về để an ủi Ngụy hoàng hậu.
Khương Dung Âm cũng hiểu ra vì sao suốt mười sáu năm qua, Ngụy hoàng hậu chưa từng yêu thích nàng. Thậm chí sau khi thân phận bị vạch trần, bà còn muốn đưa nàng đi hòa thân với Đại Nguyệt.
Chỉ là chẳng ai ngờ được, người mở miệng giữ Khương Dung Âm lại, lại là Khương Quân.
Hắn lương thiện, là chính nhân quân tử. Hắn không so đo những khổ sở lưu lạc suốt mười sáu năm qua, còn cho Khương Dung Âm một chốn dung thân.
Vậy nên bọn họ đều nói, Khương Dung Âm phải biết cảm kích Thái tử điện hạ.
Nhưng nếu biết cái giá của việc được giữ lại là cả đời này nàng phải trở thành món đồ cấm của Khương Quân, Khương Dung Âm thà rằng đi hòa thân với Đại Nguyệt.
Dù có chết trên đường, hay chết ở Đại Nguyệt, nàng cũng cam lòng nhận mệnh.
Mang theo những suy nghĩ ấy, Khương Dung Âm đi đến trước cửa Khôn Ninh cung. Bên trong truyền ra tiếng cười của Ngụy hoàng hậu, bước chân nàng khựng lại.
“Lần này con từ Giang Nam trở về, vụ án thuế riêng ấy, phụ hoàng con khen con không dứt lời. Lại thêm một tháng nữa chính là Yến Xạ yến, vừa hay cũng có thể nhân đó chọn Thái tử phi cho con.”
“Đợi sau khi con thành hôn, bổn cung sẽ tìm một cái cớ gả Khương Dung Âm ra ngoài. Nghe nói tiểu công tử nhà họ Tần qua lại khá gần với nàng ta, phụ hoàng con cũng có ý này. Như vậy lại xem như hời cho nàng ta rồi.”
Giọng Ngụy hoàng hậu dịu dàng, tràn đầy yêu thương từ ái. Những lời như vậy, bà chưa từng nói với Khương Dung Âm.
Dù nàng đã làm con gái bà suốt mười sáu năm, bà cũng chưa từng có nổi một ngày hòa nhã với nàng.
Chỉ là những lời phía sau của Ngụy hoàng hậu lại khiến sắc mặt Khương Dung Âm hơi tái nhợt.
Bà nhắc đến Tần Thời Ngôn trước mặt Khương Quân.
“Cửu công chúa? Sao người lại đứng ngoài cửa không vào?”
Chung nữ quan đi ra, nhìn thấy Khương Dung Âm thì hơi sững lại, sau đó mỉm cười nói một câu.
Khương Dung Âm giải thích rằng mình cũng vừa mới đến.
“Nô tỳ đưa người vào nhé.”
“Lần này điện hạ từ Giang Nam trở về có mang theo không ít đồ đấy.”
Chung nữ quan nói xong, nhìn Khương Dung Âm đang cúi đầu im lặng, trong lòng khẽ thở dài.
“Nương nương, Cửu công chúa đến rồi.”
Nghe Chung nữ quan nói vậy, ý cười trên mặt Ngụy hoàng hậu liền nhạt đi. Bà thản nhiên liếc nhìn Khương Dung Âm đang bước vào.
“Ngồi đi. Thái tử có mang đồ về cho con, xem thử thích thứ gì.”
Ngụy hoàng hậu xưa nay vốn không thích Khương Dung Âm. Dù những năm qua, Khương Dung Âm luôn dè dặt lấy lòng bà đủ điều, bà vẫn cảm thấy chính vì Khương Dung Âm mà con trai bà mới không thể trở về.
Năm đó, đứa bị mang ra khỏi cung rốt cuộc là con trai hay con gái, sao Ngụy hoàng hậu lại không phân biệt được?
Sau khi Hoàng đế đưa Khương Dung Âm vào cung, ông cũng không còn phái người đi tìm tung tích Khương Quân nữa.
Ngụy hoàng hậu sao có thể hòa nhã với Khương Dung Âm cho được?
Nhưng người là do Hoàng đế đưa về, Ngụy hoàng hậu cũng không thể quá hà khắc với nàng. Những năm qua, hai người cứ lạnh nhạt với nhau như vậy.
“Đa tạ điện hạ.”
Khương Dung Âm ngồi xuống, ngước mắt nhìn về phía Khương Quân. Chỉ một cái liếc mắt, nàng lại lập tức cúi đầu.
Khương Quân chưa bao giờ cho phép Khương Dung Âm gọi hắn là hoàng huynh.
“Tiểu Cửu, nàng xứng sao?”
Nghĩ đến câu nói ấy, Khương Dung Âm rũ mắt.
Nàng không xứng.
Một kẻ giả mạo, sao xứng gọi hắn là hoàng huynh?
Khương Quân theo cữu cữu nhà họ Ngụy tòng quân. Một thân sát khí của hắn là do chém giết trên sa trường mà thành. Nay cởi giáp trụ, thay bằng gấm vóc, tự nhiên lại có vẻ tôn quý hiếm ai sánh được.
Ngón tay đặt trên tay vịn ghế khẽ gõ một cái. Khương Quân bỗng bật cười thành tiếng.
“Cô quên mất, lễ vật dành cho Tiểu Cửu vẫn còn ở Đông cung.”
Nghe câu này, sắc mặt Khương Dung Âm lập tức thay đổi.
“Không sao đâu, điện hạ còn nhớ đến Dung Âm là được rồi, ta…”
“Tiểu Cửu đi cùng cô một chuyến đến Đông cung đi.”
Không đợi Khương Dung Âm nói hết câu, lời Khương Quân đã tiếp ngay sau đó.
Giọng điệu không cho phép nghi ngờ, cứng rắn đến cực điểm.
Ngụy hoàng hậu liếc nhìn dáng vẻ Khương Dung Âm gần như co rúm lại như chim cút.
“Đi đi. Thái tử còn nhớ đến con, con phải biết tri ân báo đáp.”
Có lời này của Ngụy hoàng hậu, Khương Dung Âm không còn cách nào từ chối.
Dù nàng có không muốn đến Đông cung thế nào, nàng cũng buộc phải đi.
Khương Quân đứng dậy, hành lễ với Ngụy hoàng hậu rồi xoay người bước ra ngoài. Khương Dung Âm đi theo bước chân hắn.
Đến lúc này, nàng xem như đã hiểu. Hắn bảo nàng đến Khôn Ninh cung, vốn chẳng phải vì muốn nàng nhận lễ vật gì cả.
Mà là để nàng nghe thấy những lời của Ngụy hoàng hậu.
Trên con đường cung vắng vẻ, Khương Quân đi phía trước, Khương Dung Âm theo sau hắn, từ đầu đến cuối vẫn giữ khoảng cách năm bước.
“Nghe nói phụ hoàng có ý ban hôn cho nàng và Tần Thời Ngôn?”
Bất chợt, hắn lên tiếng nói một câu. Tim Khương Dung Âm lập tức thắt lại.
“Chỉ từng nhắc qua thôi.”
“Muốn gả?”
Hai chữ ấy vừa rơi xuống, bước chân Khương Quân cũng dừng lại. Khương Dung Âm đang cúi đầu đi đường, suýt nữa thì đụng phải hắn.
“Ta nghe theo điện hạ.”
Nàng vội vàng dừng lại. Khương Quân xoay người, đôi mắt đen kia tựa như vực sâu tối tăm không thấy đáy.
“Nghe theo cô?”
Hơi thở của Khương Quân gần ngay gang tấc. Hắn giơ tay bóp lấy cằm nàng, ép Khương Dung Âm phải ngẩng đầu lên.
“Trên đường cô trở về, đã gặp Tần Thời Ngôn.”
Đồng tử Khương Dung Âm hơi mở lớn. Khương Quân lạnh lùng cười khẽ, gọi nàng:
“Tiểu Cửu.”
“Điện hạ…”
Khương Quân trước mắt tựa như hóa thành một con quỷ quái đang há cái miệng đầy máu, chỉ chờ khoảnh khắc tiếp theo sẽ xé nàng ra rồi nuốt trọn vào bụng.
Khương Dung Âm rất sợ.
Nàng sợ Tần Thời Ngôn đã nói gì đó với hắn, càng sợ Tần Thời Ngôn sẽ không giữ được mạng.
Thế nhân đều ca tụng Thái tử điện hạ thanh cao sáng trong như gió mát sau mưa, là bậc quân tử ôn nhuận như ngọc, là người tốt hiếm có trên đời.
Nhưng chỉ có Khương Dung Âm biết, ẩn sâu trong cốt tủy hắn là sự cố chấp đến bệnh hoạn, là tuyệt tình và máu lạnh.
Nàng biết, Khương Quân có cách khiến Tần Thời Ngôn biến mất không một tiếng động.
Nhưng nàng càng sợ Khương Quân biết được, trong quãng thời gian hắn không ở đây, nàng đã lén sau lưng hắn làm những gì.
“Tần Thời Ngôn sắp cưới vợ rồi. Đến lúc đó, cô sẽ đưa Tiểu Cửu đi dự hôn yến.”
“Sau khi thành hôn, hắn sẽ đến Lĩnh Nam. Đời này, hắn sẽ không bao giờ trở lại kinh thành nữa.”
Mỗi một chữ Khương Quân nói ra, sắc mặt Khương Dung Âm lại trắng bệch thêm một phần.
Hắn biết hết rồi.
Hắn biết chuyện nàng vì muốn thoát khỏi hắn, đã xin phụ hoàng ban hôn cho nàng và Tần Thời Ngôn.
“Điện hạ, có thể hay không…”
“Nếu nàng cầu tình cho hắn, cô sẽ khiến hắn chết trên đường đến Lĩnh Nam. Nghĩ cho kỹ rồi hãy nói.”
Bàn tay đang bóp cằm Khương Dung Âm càng thêm dùng sức. Trên gương mặt trắng nõn của cô nương hằn lên vệt đỏ. Chỉ một câu ấy đã khiến Khương Dung Âm không còn dám lên tiếng.
Khương Quân nhìn vào đôi mắt hoảng sợ bất an của Khương Dung Âm, trong lòng lại dâng lên vài phần vui sướng kỳ dị.
Nàng nên vĩnh viễn ở bên cạnh hắn.
Cả đời này cũng đừng mong giãy thoát.
Những gì nàng nợ hắn, hãy ngoan ngoãn trả lại cho hắn từng chút một.
“Không cần về Quang Hoa điện nữa, đến Đông cung.”
Tay Khương Quân buông xuống. Ánh mắt hắn lướt qua gương mặt Khương Dung Âm, khóe môi cong lên một nụ cười, hỏi ngược lại:
“Làm sai chuyện, chẳng lẽ không nên nhận lỗi với cô sao?”
Dứt lời, Khương Quân xoay người rời khỏi nơi này.
Khương Dung Âm thất thần, ngã ngồi xuống đất. Bảo Ngân vội bước lên đỡ lấy nàng, trong mắt đầy đau xót.
“Công chúa.”
“Ta biết ngay mà… hắn sẽ không vô duyên vô cớ trở về.”
Đi Giang Nam điều tra vụ thuế riêng, là chính miệng Khương Quân nói.
Là nàng ngu xuẩn, lầm bước rơi vào cái bẫy của hắn, còn tưởng có thể nhân cơ hội này cắt đứt hoàn toàn quan hệ giữa hai người.
Không ngờ đến cuối cùng, lại hại người hại cả mình.
Khương Quân chính là muốn nàng làm con chim trong lồng của hắn cả đời, vĩnh viễn không thể thoát khỏi chiếc lồng giam mang tên hoàng cung này!', '2026-06-01 11:05:36.427793+00'), (15, 2, 8, 'Chương 7: Thu phòng', 'Trong doanh trướng chủ soái, Hoắc Yếm nghe mấy vị phó tướng dưới trướng báo cáo xong việc bố trí công thủ trong thành Hội Kê, lại hỏi tình hình bách tính trong thành ra sao.

Từ sau khi bọn họ chiếm được Hội Kê, dân chúng Tây Lương trong thành tự nhiên ôm mối quốc hận gia thù, oán giận sâu nặng với binh tướng Đại Lương.

Nhưng Hoắc Yếm lại không giống những tướng lĩnh bình thường, dùng cách giết gà dọa khỉ, dựa vào sát phạt để khiến người ta cúi đầu. Hắn ban xuống chiếu lệnh khoan hậu, cho phép bọn họ tự do đi hay ở.

Ban đầu, dân chúng Tây Lương quả thật từng nhóm lớn như chạy nạn mà tràn sang những thành trì Tây Lương lân cận. Nhưng Tây Lương vương lại không thể kịp thời có biện pháp cứu tế, giúp đỡ dân chạy nạn. Điều này dẫn đến những nạn dân rời khỏi Hội Kê không những không có chỗ tạm thời an ổn, thậm chí còn ngược lại bị cường đạo cùng tộc cướp bóc, suýt nữa người mất của cũng không còn.

Cũng vì vậy, dù chiếu lệnh của Hoắc Yếm từ đầu đến cuối chưa từng thay đổi, bách tính Hội Kê cũng không còn ai nguyện mạo hiểm rời thành nữa. Thậm chí còn có không ít người bắt đầu tự nguyện nhập hộ tịch Đại Lương, trở thành dân Đại Lương.

Sau đó, lấy thành Hội Kê làm tấm gương điển hình, dân chúng trong những thành hàng phục khác của Tây Lương cũng dần dần thần phục quy hàng.

Tướng quan dưới trướng báo cáo xong tình hình, Hoắc Yếm như đã sớm đoán được, chỉ gật đầu, sau đó phất tay ra hiệu cho mọi người lui xuống.

Phó quan Kinh Thiện đứng chờ một bên. Đợi mọi người rời khỏi trướng, hắn tiến lên nói tiếp:

“Tướng quân, huynh đệ bên Xích Phong đoạt được từ tay tướng quan địch một thanh bảo kiếm hiếm có trên đời. Nghe nói còn được rèn bằng kỹ nghệ đã thất truyền từ tiền triều. Bọn họ sai người đưa đến Hội Kê, muốn đặc biệt dâng lên tướng quân.”

Nghe vậy, Hoắc Yếm ngẩng đầu nhìn Kinh Thiện một cái, ánh mắt có chút hàm ý. Sau đó hắn hào phóng nói:

“Mấy trận ác chiến với Tây Lương lần này, ngươi giết địch anh dũng, công lao không nhỏ. Nếu ngươi thích thanh kiếm này, thưởng cho ngươi cũng không sao.”

Nghe lời này, Kinh Thiện trong nháy mắt vừa mừng rỡ, nhưng nhiều hơn vẫn là cảm thấy bất ngờ.

Hắn từ nhỏ đã đi theo bên cạnh Hoắc Yếm, có thể nói là rất hiểu hắn. Tuy Hoắc Yếm thưởng phạt phân minh, nhưng phần nhiều vẫn lấy uy nghiêm làm chính. Ngày thường nếu không phải liên tiếp lập kỳ công, rất khó được hắn trực tiếp ban thưởng rộng rãi không tiếc lời như vậy.

Cho nên lúc này, Kinh Thiện thật sự có cảm giác được sủng ái mà kinh hãi.

Nghĩ kỹ lại, những việc hắn làm đều nằm trong bổn phận, thật sự không dám lấy đó kể công.

Vì vậy hắn tiến lên một bước, ôm quyền quỳ một gối đáp lời:

“Tướng quân, không công không nhận lộc. Thanh kiếm này quý giá khác thường, Kinh Thiện e rằng nhận lấy sẽ hổ thẹn!”

Thấy hắn do do dự dự, Hoắc Yếm hơi nhíu mày, tựa hồ có vài phần mất kiên nhẫn. Ngay sau đó, giọng điệu cũng lạnh nghiêm hơn mấy phần.

“Đã thưởng cho ngươi thì cứ cầm lấy. Lề mề như đàn bà làm gì.”

Nói xong, thấy Kinh Thiện vẫn bày ra vẻ do dự không hiểu gì, tựa như nếu lúc này không nói rõ công lao của hắn, hắn sẽ không dễ dàng nhận thưởng.

Vì vậy, Hoắc Yếm bất đắc dĩ dời mắt đi. Sau đó có chút mất tự nhiên mà bổ sung một câu:

“Chuyện hôm nay, ngươi làm rất tốt.”

Lời này nói ra mặt ngoài, đối với Hoắc Yếm mà nói quả thật hơi khó mở miệng. Nhưng nữ tử mà Kinh Thiện tìm đến kia, quả thật ở mọi phương diện đều hợp ý hắn.

Nếu không phải hôm nay khi về doanh trận thế nghênh đón quá lớn, thậm chí hắn có thể trực tiếp ôm người lên ngựa, thẳng tay đưa nàng vào trong trướng của mình.

Mà Kinh Thiện nghe xong lại càng như rơi vào mây mù. Sau khi đứng dậy, hắn vẫn luôn suy nghĩ rốt cuộc hôm nay mình đã làm gì khiến tướng quân hài lòng đến vậy, thậm chí bảo kiếm hiếm có cũng nói thưởng là thưởng.

Nghĩ tới nghĩ lui, hắn chẳng qua chỉ là lúc tướng quân đến Hàn Trì giải độc, đã xua những người không liên quan gần vùng nước ấy rời đi, sau đó một mình quay về quân doanh, ngoài ra không làm gì khác.

Nhưng những việc bình thường nhỏ nhặt ấy, sao đến mức được thưởng?

Nghĩ đến đây, Kinh Thiện lại lo lắng cho độc chứng của Hoắc Yếm, vì vậy tạm thời ném nghi hoặc trong lòng ra sau đầu, tiếp đó hỏi thăm tình trạng thân thể của hắn.

“Tướng quân, hôm nay đến Hàn Trì giải độc có thuận lợi không? Khoảng cách phát tác của độc chứng này càng lúc càng thất thường, độc hiệu cũng càng ngày càng mạnh. Để cầu ổn thỏa, chúng ta vẫn nên sớm khởi hành hồi kinh, tìm ngự y trong cung chữa tận gốc thì hơn.”

Nghe vậy, Hoắc Yếm che giấu bằng một tiếng ho nhẹ, ngay sau đó sắc mặt cũng bỗng thay đổi một chút.

Kinh Thiện đi theo Hoắc Yếm nhiều năm, tự nhiên có thể nhạy bén nhận ra sự biến hóa trong cảm xúc của hắn. Lúc này hắn gần như có thể khẳng định, tướng quân quả thật có tâm sự. Hơn nữa hiện tại hắn vô thức lộ ra vài phần giận mà thẹn, càng là điều cực kỳ hiếm thấy.

Thấy Hoắc Yếm mãi không nói, Kinh Thiện lại lo lắng lên tiếng nhắc nhở:

“Tướng quân?”

Hoắc Yếm nghiêm mặt thu lại suy nghĩ, sau đó lạnh mặt, cố ý trầm giọng mở miệng:

“Ừm, chuyện khởi hành quả thật không nên chậm trễ thêm. Ngươi cứ truyền lệnh xuống, lệnh cho toàn quân thu kích chỉnh trang, ba ngày sau, đội ngũ tiến về phía đông hồi kinh.”

“Vâng!”

Nhận lệnh xong, Kinh Thiện lại lo xa nói:

“Đường hồi kinh xa xôi gian khổ. Để phòng âm độc tái phát, ngày mai mạt tướng sẽ đến y quán trong thành, bảo đại phu chuẩn bị trước vài thang thuốc hạ tâm hỏa.”

“Không cần.”

Hoắc Yếm lời ít ý nhiều ngăn hắn lại.

Sau này có nàng ở bên cạnh, nếu độc tính lại phát tác, hắn cũng không cần dựa vào thuốc đắng, một mình gian nan nhẫn nhịn nữa.

Hoắc Yếm thừa nhận, sau khi ôm mỹ nhân vào lòng, hưởng qua một lần hương mềm ngọc ấm đầy tay, hắn khó mà khống chế bản thân sa vào mê luyến, quả thật đã nghiện cảm giác ấy.

Nói thật, độc tính này tuy dữ dội, nhưng mấy lần phát tác trước hắn cũng có thể cắn răng chịu đựng được. Chỉ là khi nhìn thấy nàng, hắn lại cố tình không muốn nhịn nữa.

Đôi mắt đẹp mềm mại quyến rũ hồn người ấy mơ mơ hồ hồ câu lấy hắn. Khi đó, điều hắn nghĩ nào chỉ là ôm nàng, rõ ràng là hận không thể lập tức lột sạch nàng, chiếm lấy nàng.

Chỉ là lúc ấy, nhìn dáng vẻ rụt rè của nàng, còn mang theo chút sợ hãi, quả thật khiến hắn tự nhiên sinh ra vài phần thương tiếc và không nỡ.

Vì vậy hắn nghĩ, dù sao cũng đã là người của hắn, không cần vội nhất thời. Đợi sau này đưa nàng về Thượng Kinh, hắn muốn kim ốc tàng kiều thế nào, cũng chẳng ai có quyền hỏi đến một lời.

Hoắc Yếm chậm rãi thu lòng, xua tan gương mặt kiều diễm hiện lên trong đầu. Sau đó hắn lên tiếng dặn dò Kinh Thiện:

“Sau giờ ngọ ngày mai, ngươi đích thân đến cổng chính tiền doanh thay ta đón người vào. Nhớ khi ấy tránh tai mắt một chút, đón được rồi trực tiếp đưa nàng vào trướng của ta.”

Kinh Thiện không biết là người nào lại quan trọng như vậy, có thể khiến tướng quân nhớ kỹ trong lòng như thế.

Hắn đang định hỏi kỹ, bỗng nghe bên ngoài có người lên tiếng xin gặp:

“Tướng quân có ở đó không? Nữ quan Thượng y Phùng Chiêu có việc muốn bẩm báo với tướng quân.”

Hoắc Yếm gật đầu ra hiệu. Kinh Thiện thấy vậy liền cất giọng nói ra ngoài trướng:

“Vào đi.”

Phùng Chiêu dẫn theo ba vị nữ quan cùng cấp đi vào, sau đó hơi khuỵu gối, cung kính hành lễ.

Được cho đứng dậy, Phùng Chiêu nhìn thẳng phía trước, mở miệng nói:

“Đêm muộn còn đến quấy rầy tướng quân, thật sự là lỗi của chúng ta. Chỉ là chuyện này liên quan đến mỹ cơ Tây Lương dâng đến, chúng ta không gánh nổi trách nhiệm, lại không dám tự quyết, cho nên đặc biệt đến xin tướng quân chỉ thị.”

Nghe vậy, Hoắc Yếm hơi nhíu mày, đối với lời này rất không cho là đúng.

Hắn khẽ cười lạnh một tiếng ngắn ngủi, giọng điệu khinh thường:

“Không gánh nổi trách nhiệm? Một nữ tử Tây Lương hiến hàng, nay đã vào quân doanh Đại Lương chúng ta thì nên an phận thủ thường, biết rõ thân phận của mình. Chẳng lẽ ở đây nàng ta còn muốn ra vẻ, bắt các ngươi gọi nàng ta một tiếng chủ tử sao?”

Phùng Chiêu nghe lời này, như đã đạt được ý muốn mà thở phào nhẹ nhõm. Ngay sau đó, khóe miệng nàng ta cũng khẽ cong lên một đường đắc ý.

Trước đó, vì ghen ghét Thi Nghê được thái tử khen ngợi dung mạo, trong lòng nàng ta vẫn luôn nghẹn một hơi. Vì vậy nàng ta không nhịn được mà ôm tư tâm, ngoài sáng trong tối hà khắc với Thi Nghê và tỳ nữ của nàng.

Ban đầu, nàng ta chẳng qua chỉ muốn dạy cho đối phương một bài học. Không ngờ Hoắc tướng quân lại hồi doanh nhanh như vậy, còn đúng lúc gặp Thi Nghê mắc bệnh cấp tính.

Nàng ta còn chưa ngu xuẩn đến mức thật sự không biết nặng nhẹ. Nếu để hai chủ tớ Thi Nghê đi trước nói oan ức với Hoắc tướng quân, e rằng mười phần thì tám chín phần nàng ta sẽ bị hỏi tội.

Vì vậy Phùng Chiêu dứt khoát chiếm tiên cơ trước, nói lý lẽ đều kéo về phía mình. Dù sao thân là võ tướng Đại Lương, lưỡi đao nhuốm máu, ngăn cách thù hận, Hoắc tướng quân dù thế nào cũng sẽ không đứng về phía một nữ tử Tây Lương.

Phùng Chiêu phỏng đoán tâm tư Hoắc Yếm, nhân cơ hội nói tiếp:

“Nữ tử Tây Lương kia có lẽ trước kia quen được người khác hầu hạ rồi, đến trong doanh có thể nói là kén cá chọn canh. Nước mà các tướng sĩ vất vả gánh về để nấu cơm, còn phải chia ra một phần riêng cho nàng ta dùng để tắm rửa. Dù như vậy, nàng ta vẫn trăm điều không hài lòng, kiều quý thật như công chúa vậy.”

“Ngay vừa rồi thôi, nàng ta lại nói mình nhiễm phong hàn. Cũng không biết nàng ta thật sự mắc bệnh cấp tính, hay là biết tướng quân hồi doanh, nên cố ý trì hoãn không muốn đến hành lễ bái kiến tướng quân.”

Những lời này Phùng Chiêu đã chuẩn bị trong lòng rất lâu. Nàng ta biết rõ, lời này vừa nói ra, Hoắc Yếm tự nhiên sẽ sinh bất mãn và chán ghét Thi Nghê.

Nếu các nàng bị chủ soái ghét bỏ, nghĩ đến trên đường hồi kinh này chắc chắn sẽ chẳng sống dễ chịu gì. Nghĩ đến đây, Phùng Chiêu chỉ cảm thấy vô cùng hả giận.

Hoắc Yếm phất tay, giữa mày đã hiện ra vài phần mất kiên nhẫn:

“Nếu đã nhiễm bệnh, vậy trước tiên phái quân y chữa trị cho nàng ta. Đợi bệnh khỏi rồi, năm thùng nước mà hậu phương quân bị cần dùng, đều bảo nàng ta đến gánh đầy. Đây là quân doanh, không ai ở đây cưng chiều công chúa, nuôi dưỡng người nhàn rỗi. Số nước dưới bếp nàng ta lãng phí trước kia, tự nhiên nên tự tay trả lại.”

“Tướng quân nói phải, hạ quan nhất định làm theo.”

Nghe lời dặn lạnh lùng của Hoắc Yếm, vẻ hả hê trên mặt Phùng Chiêu gần như sắp không che giấu nổi.

Nàng ta vừa thầm đắc ý, vừa không nhịn được cảm thán, nói đến thủ đoạn nghiêm khắc, ai có thể sánh bằng Hoắc tướng quân?

Lại thầm nghĩ, đừng nói gì đến thương hương tiếc ngọc. Cho dù là hồ ly tinh như Thi Nghê, ánh mắt lẳng lơ đưa đẩy, biết phát xuân quyến rũ nam nhân, dán sát trước mặt hắn, chắc hẳn Hoắc tướng quân vẫn sẽ thiết diện vô tư, ngay cả mày cũng không nhíu một chút.

Dáng vẻ yêu kiều quyến rũ ấy của nàng ta, người khác thấy có lẽ sẽ sinh lòng thương yêu, nhưng gặp phải Hoắc tướng quân thì chính là ruột mềm đụng ván sắt, trăng sáng soi xuống mương bùn.

Tưởng tượng đến những ngày tháng khổ sở của Thi Nghê sau này, Phùng Chiêu trong lòng sảng khoái lui xuống.

Đợi người rời đi, Kinh Thiện ở bên cạnh hơi do dự mở miệng:

“Tướng quân, hình phạt gánh đầy năm thùng nước có phải quá nặng rồi không? Nữ tử Tây Lương kia dù sao cũng là người sẽ được dâng vào cung. Cho dù không làm được nương nương, khả năng cao cũng sẽ bị vị điện hạ nào đó thu vào phòng. Chúng ta làm như vậy, e rằng sẽ đắc tội với người ta.”

Nghe vậy, trong đôi mắt dài hẹp của Hoắc Yếm lóe lên vài phần khinh thường:

“Người Tây Lương trước giờ xảo trá. Lần này dùng nữ tử hiến sắc lấy lòng thánh thượng, tâm tư đáng khinh của bọn họ đã rõ như ban ngày.”

Kinh Thiện hơi suy nghĩ, lại tỏ vẻ đồng tình:

“Tướng quân lo lắng phải lắm. Nghe nói bức họa của nữ tử Tây Lương này vừa xuất hiện trong cung yến, tam hoàng tử lập tức khen dung mạo nàng ta vô song, khắp Thượng Kinh không có người thứ hai. Ngay cả thái tử điện hạ là người sáng trong như trăng gió như vậy, cũng không nhịn được mà công khai tán thưởng, khen bức họa công bút khắc họa sống động như thật. Theo thuộc hạ thấy, thái tử điện hạ nào phải đang thưởng tranh, rõ ràng cũng là nhìn trúng mỹ nhân trong tranh rồi.”

“Mới chỉ thấy tranh mà đã là tình trạng như vậy. Nếu nữ tử này đích thân đến Thượng Kinh, chẳng phải sẽ khiến sóng ngầm nổi dậy, lại dẫn đến một phen tranh đoạt sao.”

Nói đến đây, Kinh Thiện cũng không nhịn được tò mò, muốn tận mắt đi nhìn thử dung mạo của vị mỹ nhân khuynh thành tuyệt thế ấy.

Chỉ tiếc mỹ nhân đang bệnh, lần gặp mặt này của hắn còn phải lùi lại sau.

Mà Hoắc Yếm nghe vậy lại không cho là đúng, lạnh lùng cười nhạt một tiếng. Ngay sau đó, hắn hờ hững mở miệng:

“Loại hồng nhan họa thủy như vậy, vẫn nên tránh xa một chút thì hơn.”', '2026-06-01 11:55:06.040697+00'), (16, 2, 9, 'Chương 8: Chủ tử đứng đắn ', 'Trăng treo trên màn trời, sao lạnh lơ lửng nơi cao.
Hoắc Yếm nằm trên giường lăn qua lộn lại, mãi không ngủ được. Chỉ cần vừa nhắm mắt, hắn lại như thân lâm kỳ cảnh, trở về dòng nước chảy xiết ở Hàn Trì, ôm nữ tử kia sát vào lòng, kề cận trong từng hơi thở.
Trên người nàng rất thơm, hương hoa mộc cận thoang thoảng quanh quẩn nơi chóp mũi, khiến hắn đến tận bây giờ hồi tưởng lại vẫn cảm thấy khó quên.
Hoắc Yếm thầm nhớ nhung trong lòng. Nếu ngày mai nàng đến, hai người tự nhiên sẽ cùng ở chung chăn gối. Vậy thì trong trướng không nên tiếp tục âm u trầm lặng, bày biện đơn sơ như thế này nữa.
Xung quanh giường nằm dù sao cũng nên thêm một lớp bình phong che chắn tầm mắt, hoặc thêm chút sắc màu ấm áp tươi sáng.
Lại nghĩ, gần Hàn Trì có không ít hoa phù tang màu hồng phấn cam tươi đang nở. Hương thơm thanh nhã mà nhạt, bảo người hái đến đặt trong phòng, dùng để trang điểm cảnh trí thì thích hợp vô cùng.
Nghĩ đến, nàng hẳn cũng sẽ thích.
Dần dần chìm vào giấc ngủ, tâm tư Hoắc Yếm trầm xuống, hiếm khi sa vào mộng cảnh.
Trước mắt hắn mơ hồ, nơi nhìn thấy đều hư ảo. Chỉ có hương hoa mộc cận vấn vít nơi chóp mũi càng lúc càng chân thật, càng lúc càng thơm ngát. Sau đó, hắn cũng lần theo hương hoa ấy, thân thể đón nhận một cảm giác xao động xa lạ.
Giấc ngủ này, hắn ngủ đặc biệt thoải mái.
…
Sáng sớm hôm sau, trong chiếc lều thấp ở một góc chật hẹp sơ sài của quân doanh.
Thi Nghê ngồi trước gương đồng, để mặc A Giáng vấn tóc trang điểm cho nàng, thoa son vẽ mày. Chỉ là ánh mắt nàng trước sau vẫn lơ đãng, nhìn qua liền biết không có tinh thần gì.
Cũng không trách nàng tâm trạng sa sút. Thật sự là trong lòng có điều lo lắng, lại không có nơi nào để giải tỏa.
Vốn tưởng rằng chủ soái vào quân doanh, Phùng Chiêu sẽ thu liễm việc hà khắc với các nàng, ít nhất sẽ không còn chuyện thiếu ăn thiếu mặc rõ ràng ngoài mặt nữa.
Nhưng Thi Nghê lại không ngờ, chính vì nàng đột nhiên tuyên bố mình nhiễm bệnh cấp tính, mới khiến Phùng Chiêu chột dạ đến vỡ mật. Vì vậy nàng ta tiên hạ thủ vi cường, dùng chiêu ác nhân cáo trạng trước.
Sau khi nghe được, Thi Nghê ngược lại không quá để ý những chuyện khác, chỉ sợ Phùng Chiêu nói bừa nói bãi, ác ý dẫn dắt khiến vị chủ soái tướng quân kia sinh lòng bất mãn với các nàng, vô cớ thêm chán ghét phiền lòng.
Nàng rất rõ, thân là nữ tử Tây Lương được dâng lên cầu hàng, bị võ tướng Đại Lương không thích cũng là chuyện bình thường. Nhưng vào đúng thời điểm mấu chốt này, nếu lại có người bịa đặt vô căn cứ, mượn cớ làm khó, e rằng những ngày tháng sau này thật sự sẽ gian nan khổ sở.
Hơn nữa, vị chủ soái tướng quân vào doanh kia nàng còn chưa từng gặp mặt, không biết tính tình người ấy ra sao.
Trước mắt nàng chỉ mong rằng, tướng quân sẽ là một người công chính biết lý lẽ, không đến mức để hai chủ tớ các nàng không nơi nương tựa, thật sự bị bắt nạt đến mức không có chỗ phân trần.
“Cô nương, chúng ta tạm thời nhịn một chút. Nghe nói quân đội Đại Lương mấy ngày nữa sẽ khởi hành tiến về Thượng Kinh. Đợi chúng ta vào đô thành, thân ở dưới chân thiên tử, với tài mạo và dung sắc đặc biệt của cô nương, còn lo gì không tìm được quyền quý che chở. Đến lúc ấy, một nữ quan Thượng y nho nhỏ như nàng ta còn có gì đáng sợ nữa?”
Ý định ban đầu của A Giáng là muốn an ủi Thi Nghê, sợ trong lòng nàng uất ức bất bình lại không người giãi bày. Nhưng bất đắc dĩ, lời này vừa nói ra, lại chỉ khiến Thi Nghê thêm một phen bi thương đau lòng.
“Ngay cả trong quân doanh này, muốn cầu chút công bằng đã khó khăn đến thế, làm sao biết vào Thượng Kinh rồi sẽ không càng cô độc hơn? Xưa nay nơi trung tâm quyền lực mới thật sự là hang hổ ổ sói.”
Thi Nghê khẽ thở dài nói.
Thật ra tâm thái của Thi Nghê trước giờ vẫn luôn lạc quan, nhưng khó tránh cũng có lúc cảm thấy vô cùng nản chí.
Nhất là lúc này, đội ngũ sắp tiến về phía đông. Nàng mang trên mình số mệnh không thể tự lựa chọn, một khi đi rồi sẽ không thể quay đầu nữa.
A Giáng thấy nàng suy nghĩ sa sút như vậy, trong lòng cũng theo đó khó chịu. Vì vậy nàng ở bên cạnh mềm giọng khuyên nhủ:
“Cô nương không cần chán nản như thế. Trước kia ở vương điện Tây Lương, lần nào cũng có tam vương tử bảo vệ cô nương. Sau này vào Đại Lương, cô nương lại sinh ra đáng thương đáng yêu như vậy, muốn tìm chỗ dựa chắc chắn không phải chuyện khó. E là đến lúc ấy, nam nhi Đại Lương bọn họ tranh nhau cướp nhau quỳ dưới váy người, muốn làm hộ hoa sứ giả cho cô nương nhà chúng ta ấy chứ.”
Lời này của A Giáng hiển nhiên chỉ là thuận miệng nói ra, không suy nghĩ kỹ càng cách dùng từ. Nhưng nếu lọt vào tai người Đại Lương, không biết lại sẽ rước lấy bao nhiêu khinh thường châm chọc.
Có điều cũng may, A Giáng vẫn biết nặng nhẹ. Dù có ăn nói không giữ miệng, nàng cũng chỉ lén nói nhỏ vài câu với Thi Nghê trong riêng tư, sẽ không thật sự mở miệng với người ngoài, dẫn họa vào thân.
A Giáng tuổi còn nhỏ, tâm tư cũng đơn giản. Để phòng ngừa hậu hoạn, Thi Nghê vẫn định dặn dò đôi câu, nhắc nàng sau này dù ở nơi riêng tư cũng phải chú ý cẩn thận.
Nào ngờ nàng còn chưa kịp mở miệng, cánh cửa lều đơn sơ phía sau bỗng bị người ta kéo bật ra. Ngay sau đó, tiếng bước chân hỗn loạn cũng truyền đến.
Nghe thấy động tĩnh, trong lòng Thi Nghê không khỏi lộp bộp một tiếng. Nàng ngước mắt nhìn sang, liền thấy Phùng Chiêu dẫn theo một đám thủ hạ, khí thế hung hăng xông vào.
Ngay tức khắc, lòng Thi Nghê thoáng căng thẳng, không biết lời A Giáng vừa nói có rơi vào tai người ngoài hay không.
Thi Nghê gắng gượng trấn định, đứng dậy nghênh tiếp. Vốn dĩ, Phùng Chiêu nên hành lễ với nàng, nhưng nàng ta ỷ mình là người Đại Lương, về thân phận có ưu thế thiên thời địa lợi nhân hòa, cho nên nơi nơi ngang ngược. Không những không chịu cúi người hành lễ, ngược lại còn muốn Thi Nghê đối đãi với mình cung kính lễ độ.
Mà những chuyện này, dù quan tướng trong doanh biết được, cũng đều mắt nhắm mắt mở cho qua.
Không biết bọn họ thật sự chán ghét nàng vì thân là người Tây Lương, hay là cố kỵ thể diện của trưởng công chúa đứng sau lưng Phùng Chiêu.
Đã sống nhờ dưới mái hiên người khác, Thi Nghê sẽ không lấy trứng chọi đá. Huống hồ những hư lễ này nàng cũng không để ý.
Vì vậy nàng hạ thấp tư thái, chủ động mở miệng hỏi:
“Trong trướng đơn sơ, không biết Phùng đại nhân hạ mình đến đây là có việc gì chỉ giáo?”
Nghe vậy, Phùng Chiêu hừ lạnh một tiếng, dáng vẻ cao cao tại thượng, trong ánh mắt càng lộ ra vẻ khinh miệt mười phần.
Thấy thế, Thi Nghê thật sự không hiểu, rốt cuộc Phùng Chiêu hơn người ở chỗ nào. Chẳng lẽ chèn ép nàng, thật sự có thể mang lại cho nàng ta cảm giác thành tựu lớn đến thế sao?
Thi Nghê biết nhìn thời thế, âm thầm ghi nhớ tất cả trong lòng. Có người đối xử tốt với nàng, nàng tự sẽ nhớ ơn. Nhưng nếu có người ỷ thế hiếp người, nàng cũng sẽ không dễ dàng cười một tiếng xóa hết ân oán.
Lúc này, Phùng Chiêu hất cằm phất tay, tập hợp đám thủ hạ lại một chỗ, sau đó bày ra dáng vẻ quan cách mà mở miệng:
“Có người nhìn thấy tỳ nữ thân cận của ngươi sáng nay nhân lúc phát cơm, lén lén lút lút chuồn vào doanh trướng cung nữ. Bổn quan đặc biệt đến điều tra. Ai biết nàng ta có bị người nào xúi giục, tay chân không sạch sẽ, trộm thứ gì ra ngoài hay không.”
Thi Nghê nhìn A Giáng một cái, nghĩ đến chuyện sáng nay nàng ấy quả thật lặng lẽ đi trả y phục cung nữ, đoán đại khái là làm việc không cẩn thận, bị người ta nhìn thấy ngay tại chỗ.
A Giáng vốn đang không phục mà giận dữ trừng mắt nhìn đám khách không mời này, nghe vậy bỗng chột dạ trong thoáng chốc. Tự biết mình đã gây họa cho cô nương, nàng liền rũ mắt xuống, vô cùng luống cuống.
Thi Nghê là người đầu tiên bình tĩnh lại. Nàng biết chuyện này quả thật khó giải quyết, trước mắt các nàng cũng chỉ có thể cắn chết không nhận.
Vì vậy nàng phủ nhận:
“Đại nhân, trong chuyện này liệu có hiểu lầm gì không? Chúng ta từ Tây Lương xa xôi đến Thượng Kinh, không nói đến số bạc tiền mang theo bên người, chỉ riêng vàng tuế lễ tiến cống đã đem đến không dưới mười xe đấu. Đã như vậy, chúng ta sao đến mức phải đi trộm cắp để chuốc lấy hiềm nghi?”
Phùng Chiêu hơi nheo mắt, ánh nhìn ép xuống:
“Đúng là miệng lưỡi sắc bén. Nếu các ngươi đã không thừa nhận, vậy đừng trách ta không nể mặt cô nương, gọi người dưới trướng tự mình lục soát một phen.”
Nàng ta ra hiệu bằng mắt. Trong trướng lập tức loạn thành một đoàn. Bốn năm nữ tỳ cùng chen lên, bắt đầu xắn tay áo tùy tiện lục soát.
Có Phùng Chiêu chống lưng, các nàng ta có thể nói là không chút kiêng dè, hoàn toàn không bận tâm Thi Nghê đang có mặt.
Bất kể là giường nằm, bàn thấp, hay hộp trang điểm, hộp son phấn, tất cả đều bị lật tung đến hỗn loạn không chịu nổi.
A Giáng muốn tiến lên ngăn cản, lại bị Thi Nghê nắm lấy cổ tay, dùng ánh mắt ra hiệu nàng đừng hành động thiếu suy nghĩ.
Nếu đã trả lại y phục cung nữ, vậy sẽ không có chứng cứ đối chất. Thi Nghê tự nhiên không sợ bị lục soát. Lúc này nàng chỉ lo, không biết tấm lệnh bài huyền kim mình giấu trong ngăn tối có bị phát hiện hay không.
Đồ của nam nhân xa lạ kia, là chuyện ngoài ý muốn duy nhất mà nàng không thể giải thích.
May mắn thay, bảo vật nàng mang ra từ vương điện Tây Lương không ít. Chiếc hộp gương có khớp mộng tinh xảo này chính là một trong số đó. Đám cung nữ phần lớn chưa từng thấy món đồ khéo léo như vậy, cho nên chỉ lục ra những cây bộ diêu, trâm cài, trang sức vàng ngọc, hoa cài phỉ thúy đặt trên tầng mặt hộp, vẫn chưa phát hiện huyền cơ nơi ngăn tối.
Thấy vậy, Thi Nghê mới buông lỏng nắm tay đang siết chặt giấu trong tay áo.
Đối với tình hình này, Phùng Chiêu lại không hài lòng. Nàng ta lập tức quát mắng thủ hạ một tiếng “vô dụng”, sau đó nhìn chằm chằm Thi Nghê, lại nói:
“Ai biết chủ tớ hai người các ngươi âm thầm mưu tính, sau lưng người khác làm chuyện mờ ám gì. Các ngươi đã cứng miệng như vậy, vậy đừng trách ta dùng hình.”
Nàng ta vừa dứt lời, đã có một nữ quan khác ghé sát tới, hạ thấp giọng nhắc nhở. Ánh mắt còn lo ngại liếc về phía Thi Nghê, dường như đang khuyên Phùng Chiêu rằng làm vậy không ổn.
Nhưng Phùng Chiêu đã quen tác oai tác phúc. Dù không thể động đến Thi Nghê, nàng ta cũng quyết tâm phải ra oai một phen. Vì vậy nàng ta hừ lạnh một tiếng, chuyển ánh mắt bất thiện sang người A Giáng.
“Nha đầu này tay chân không sạch sẽ. Ta thấy đánh nàng ta mười gậy sát uy, xem thử có thể khiến nàng ta nói thật hay không. Người đâu! Dẫn đi!”
Thi Nghê nghe vậy thì hoảng hốt, vội bước nhanh lên trước, che chở A Giáng sau lưng mình, thẳng thắn nói rằng các nàng không lục được chứng cứ thì không thể tùy tiện bắt người. Nhưng người ở đây vậy mà không có ai nguyện ý nói lý với nàng.
Phùng Chiêu hùng hổ dọa người. Đám thủ hạ đi theo tuy có do dự, nhưng cuối cùng vẫn nghe theo phân phó của Phùng Chiêu, dùng dây trói lại, dễ dàng tách Thi Nghê và A Giáng ra.
Thân hình Thi Nghê yếu ớt, tự nhiên ít không địch lại nhiều. Trong lúc giằng co, chẳng biết bị ai đẩy mạnh một cái, nàng bất ngờ ngã xuống đất, còn bị trầy xước cánh tay, đau đến mức lập tức nhíu chặt mày.
A Giáng bị người ta trói lại rồi đẩy ra ngoài, thấy thế sốt ruột quay đầu, từng tiếng từng tiếng gọi “cô nương”.
Còn Phùng Chiêu thì vô tình ngăn cách tầm mắt hai người, dẫn A Giáng ra ngoài trướng, lại uy hiếp bảo nàng sớm khai rõ, lén chuồn vào doanh trướng cung nữ rốt cuộc đã làm gì. Nếu không nói, e rằng sẽ phải chịu nỗi đau da thịt.
A Giáng tự nhiên trung thành. Bất kể đối phương uy hiếp dụ dỗ thế nào, nàng chỉ nghiến răng kiên trì nói mình đi nhầm đường, rồi tìm nhầm phòng, chứ không hề làm chuyện trộm cắp.
Lời giải thích không thay đổi này của A Giáng dần dần hao hết kiên nhẫn của Phùng Chiêu. Vì vậy nàng ta trực tiếp quát lệnh thủ hạ đưa A Giáng đến sân luyện binh trong doanh, ý định dùng hình.
Có người lúc này khuyên can:
“Đại nhân, nếu để Hoắc tướng quân biết chúng ta lạm dụng tư hình trong doanh, e rằng sẽ bị trách phạt.”
Phùng Chiêu lại tự cho là đúng:
“Sợ gì chứ? Hoắc tướng quân ngày lo trăm việc, lại xưa nay chán ghét người Tây Lương, làm gì có thời gian rảnh đi quản những chuyện này. Hơn nữa, hiện giờ nàng ta bị chúng ta vây lại, sao có thể cầu viện bên ngoài?”
“Nhưng nàng ấy dù sao cũng là người được dâng đến Thượng Kinh, cho con cháu hoàng tộc quý tộc làm tiểu chủ. Chúng ta như vậy…”
Phùng Chiêu liếc ngang qua, lạnh giọng cắt ngang lời người kia:
“Tiểu chủ? Nàng ta chẳng qua chỉ là thứ tiện nghi dâm mị, toàn thân đều lộ ra vẻ mềm xương tục mị. Có ai sẽ thật sự xem nàng ta là chủ tử đứng đắn?”
Nghe vậy, thủ hạ kia không dám nói thêm nữa. Nhưng trong lòng lại không tán đồng mà nghĩ, với lớp da xinh đẹp yêu diễm kia của Thi cô nương, trời sinh đã khiến nữ tử ghen ghét, nhưng lại càng khiến nam tử thương yêu tiếc ngọc.
Hoắc tướng quân nổi danh không gần nữ sắc, cho nên nàng không dám chắc. Nhưng những hoàng tử trong kinh, có ai không yêu kiểu đại mỹ nhân mềm mại yếu ớt, phong vận khiến người thương tiếc như vậy?
E rằng sau khi Thi cô nương vào kinh, thật sự sẽ có muôn vàn người che chở, bị người ta tranh nhau nâng trong lòng bàn tay, trở thành chủ tử đứng đắn ấy chứ.
Lời tác giả:
Trong mắt người ngoài: Hoắc tướng quân nổi danh không gần nữ sắc.
Thi Nghê mờ mịt: Sao, sao lại muốn ôm nữa rồi…
Chương sau lộ  thân phận!
', '2026-06-01 15:31:03.213297+00'), (17, 2, 10, 'Chương 9: Thân phận', 'A Giáng bị dẫn đi đã nửa canh giờ, còn Thi Nghê lại bị nhốt trong trướng không ra được. Mặc cho nàng cầu xin thế nào, hai nữ tỳ phụ trách canh giữ ngoài trướng đều làm như không nghe thấy.
Lại qua thêm một lúc, cuối cùng cũng đợi được một người canh giữ đi nhà xí. Thi Nghê nhìn chuẩn thời cơ, thử dùng vàng bạc âm thầm hối lộ nữ tỳ còn lại.
Tình thế hiện tại nguy cấp, nàng chỉ có thể đánh cược một phen.
Thi Nghê là người giỏi quan sát. Nàng tỉ mỉ phát hiện, y phục vải lụa của nữ tỳ ngoài cửa này là cũ kỹ tối màu nhất trong tất cả mọi người.
Hơn nữa từ vừa rồi đến bây giờ, nàng ta luôn theo bản năng cúi đầu, dáng vẻ ít nói lặng lẽ, mặc người khác sai khiến.
Thi Nghê dựa vào đó suy đoán, cô nương này ở dưới tay Phùng Chiêu, nhất định cũng sống không dễ dàng gì.
Vì vậy, nàng thử hỏi:
“Nếu lần này ngươi bằng lòng giúp ta, không chỉ những tiền tài này đều thuộc về ngươi, ta còn có thể hứa với ngươi một điều. Nếu ngày sau ta vào Thượng Kinh, may mắn được quý nhân nâng đỡ, ta sẽ xin ngươi đến bên cạnh mình, bảo đảm sau này ngươi không cần chịu người khác ức hiếp nữa.”
Những lời hứa phía sau dường như còn hấp dẫn hơn cả tiền bạc phía trước. Lời nàng vừa dứt không lâu, liền nghe bên ngoài truyền đến tiếng thăm dò rất khẽ, rất cẩn thận.
“Lời cô nương nói… là thật sao?”
Nghe vậy, Thi Nghê thầm biết mình đã cược đúng, vì vậy giọng điệu chắc chắn nói:
“Tự nhiên là thật. Ngươi chịu ra tay giúp chúng ta trong nghịch cảnh, đây đã là ân tình rất lớn. Sau này nếu ta có năng lực, nhất định cũng sẽ làm chỗ dựa cho ngươi.”
Nhận được lời hứa của Thi Nghê, đối phương gian nan đưa ra quyết định. Nhân lúc nữ tỳ kia còn chưa trở về, nàng ta vén một góc rèm trướng, rụt rè ló mặt ra nhìn Thi Nghê.
Nhìn gương mặt còn hơi non nớt của đối phương, biết nàng hẳn cũng xấp xỉ tuổi A Giáng, Thi Nghê liền dịu giọng, ôn hòa hỏi:
“Ngươi tên gì?”
Đối phương cúi đầu xuống:
“Nô tỳ tên Tiểu Ngọc. Cô nương… cần nô tỳ làm gì?”
Thời gian cấp bách, Thi Nghê chỉ đành nói thẳng vào vấn đề:
“Tiểu Ngọc, ngươi có biết bọn họ đưa A Giáng đi đâu không? Có thể chỉ đường cho ta không?”
Tiểu Ngọc do dự đưa tay chỉ về một phương hướng bên ngoài. Khi rụt tay về, nàng lại tốt bụng nhắc nhở:
“Cô nương đừng xúc động. Bọn họ đều nghe lời Phùng đại nhân, cho dù cô nương lúc này có qua đó cũng vô ích thôi.”
Bọn họ, hẳn không chỉ chỉ những nữ quan tùy tùng kia, mà còn cả binh sĩ canh giữ trong doanh.
Vì vậy Thi Nghê nhíu mày, thần sắc nặng nề, trong lòng lập tức sinh ra vài phần bất lực.
Ngay sau đó, ánh mắt nàng chợt định lại, bỗng nghĩ đến điều gì.
“Trong quân doanh này, chẳng lẽ Phùng Chiêu thật sự có thể một tay che trời như vậy sao? Lẽ nào chủ soái trong doanh cũng hoàn toàn nghe theo nàng ta?”
Tiểu Ngọc bị lời Thi Nghê dọa đến run lên, thân thể cũng khẽ phát run.
“Tướng quân tự nhiên không phải, nhưng…”
Nhưng Hoắc Yếm tướng quân chán ghét người Tây Lương, tìm hắn làm chỗ dựa e rằng không được.
Vì sợ uy thế lạnh lẽo của Hoắc Yếm, những lời bàn luận về tướng quân, Tiểu Ngọc tất nhiên không dám nói ra. Vì vậy lời đến bên miệng lại bị nàng nuốt ngược trở về.
Còn Thi Nghê thì một lòng lo lắng cho an nguy của A Giáng. Lúc này nàng căn bản không có thời gian suy nghĩ chu toàn, vì vậy tiến lên nắm lấy cánh tay Tiểu Ngọc, giọng điệu tha thiết.
“Không thể tiếp tục chậm trễ nữa. A Giáng còn đang chờ ta đến cứu. Đi cầu xin chủ soái là cách duy nhất ta có thể nghĩ ra.”
Thấy Thi Nghê kiên trì như vậy, Tiểu Ngọc chỉ đành cắn răng đồng ý, tiếp đó chỉ về một hướng:
“Doanh trướng của tướng quân ở sâu nhất phía đông. Chủ trướng bố trí uy nghi rộng lớn, hẳn rất dễ nhận ra. Chỉ là gần đó có rất nhiều binh sĩ tuần tra, cô nương còn phải cẩn thận một chút, càng phải nhớ mau chóng trở về.”
Ánh mắt Thi Nghê đầy cảm kích. Nàng nắm tay Tiểu Ngọc nói:
“Lần này phải nhờ ngươi giúp ta kéo dài thời gian, lại khiến ngươi vô cớ gánh nguy hiểm. Mà ta lại không có gì báo đáp, chỉ có một lời hứa hư vô, thật sự hổ thẹn.”
Tiểu Ngọc lắc đầu, đồng thời ánh mắt cũng kiên định hơn rất nhiều:
“Đây là cơ hội xoay chuyển vận mệnh của ta. Ta tin cô nương. Bảo châu nhất định sẽ không mãi bị phủ bụi.”
…
Thi Nghê rời đi chưa được bao lâu, người canh giữ còn lại đã đi nhà xí trở về.
Nàng ta nhận ra bên trong trướng yên tĩnh khác thường, liền định vào trướng kiểm tra một phen.
Chỉ là còn chưa kịp vén rèm lên, đã bị Tiểu Ngọc đứng chờ một bên vươn tay kéo cổ tay lại. Sau đó nghe nàng nói:
“Thi cô nương đã ngủ rồi. Vừa rồi ta mới vào xem qua một lượt, bên trong không có gì khác thường.”
Nữ tỳ bị ngăn lại cũng lười biếng, nghe vậy liền không cố chấp nữa. Vì vậy nàng ta dừng bước, lại rũ vai xuống, lười nhác nghiêng người ngáp một cái.
“Trời nóng thế này, chúng ta đứng phơi nắng chịu tội, nàng ta lại biết hưởng thụ. Tỳ nữ thân cận cũng bị dẫn đi chịu hình rồi mà còn yên tâm gối đầu ngủ được. Đúng là kiều quý.”
Người này âm dương quái khí nói.
Mượn thế của Phùng đại nhân, các nàng cáo mượn oai hùm, tựa như trong doanh này ai ai cũng có thể khinh rẻ vị mỹ nhân dị hương đường xa từ Tây Lương đến.
Tiểu Ngọc nghe vậy chỉ im lặng, không tỏ thái độ. Nhưng trong lòng lại thầm nghĩ ánh mắt các nàng nông cạn.
Trước mắt là ở nơi quân doanh nhỏ hẹp này, Phùng đại nhân dựa vào việc Hoắc tướng quân không thích người Tây Lương, nên mới dám ngoài mặt làm một kiểu, sau lưng giở uy phong.
Nhưng đợi vào Thượng Kinh thì sao? Những hoàng tôn quý tộc Đại Lương kia xưa nay sống trong nhung lụa, xa rời chiến trường, bọn họ nào sẽ tính toán gì thù oán binh sĩ tử trận.
Thứ bọn họ nhìn thấy, chỉ là tiểu nương tử xinh đẹp trước mắt này, dáng vẻ yếu đuối đáng thương, khiến người ta sinh lòng thương tiếc.
E rằng đến khi ấy, quyền quý vì muốn đổi lấy một nụ cười của mỹ nhân, chỉ cần tùy ý phất tay đã xem mạng người như cỏ rác, dễ dàng trừng phạt nghiêm khắc những kẻ từng gây khó dễ trên đường.
Tiểu Ngọc khẽ thở dài, biết đây cũng là cơ hội chuyển ngoặt vận mệnh của chính mình.
…
Trong doanh trướng chủ soái, Hoắc Yếm uy nghi đứng thẳng, cúi nhìn bản đồ địa hình trải trên mặt đất. Hai bên trái phải của hắn mỗi bên đều có một hiệu úy mặc giáp đen đứng hầu, mọi người cùng bàn định lộ tuyến hồi kinh.
Mông Tranh đề nghị khởi hành hồi kinh ngay trong ngày, từ Hội Kê đi về phía đông, chạy đến Yển Pha. Đây là tuyến đường thuận tiện nhất cho đại quân hành tiến, không cần vòng vèo, lại đi qua từng con đường quan đạo, có thể nói là thông suốt.
Còn một hiệu úy khác là Đan Khởi lại có ý kiến trái ngược. Hắn đề nghị đại quân nên đi từ hành lang Xuyên Hà, vượt sông vòng xuống phía nam rồi hồi kinh. Đây mới là tuyến đường tốt nhất.
Sau đó hắn lại trình bày tỉ mỉ nguyên do. Đại Lương và Tây Lương liên chiến mấy tháng, tuy thắng bại đã phân, chiến sự đại thắng, nhưng bất kể bên nào, tài lực, nhân lực, vật lực các phương diện đều thật sự bị tiêu hao.
Mà trai cò tranh nhau, điều sợ nhất chính là ngư ông đắc lợi. Miện Châu quốc nằm ở phương nam, hiện giờ đang ẩn trong bóng tối, hổ rình mồi, thật sự không thể không phòng.
Vì vậy, Đan Khởi khom người can gián:
“Tướng quân, chi bằng khi đại quân hồi kinh thì vòng qua Xuyên Hà, đến Miện Nam nghênh ngang đi một vòng. Nếu không có thương kích trọng giáp uy hiếp, khó tránh bọn họ không biết tự lượng sức mình, vô cớ sinh ra dã tâm lang sói.”
Nghe vậy, thần sắc Hoắc Yếm hơi ngưng lại, lại nhớ đến mấy phần suy đoán nghi ngờ trước đây.
Sau một phen suy nghĩ, đôi đồng tử đen nhánh của hắn hơi nheo lại. Sau đó hắn ngửa tay rút thanh bảo kiếm Sát La ánh lạnh bức người ra khỏi vỏ kiếm. Lưỡi kiếm vung xuống, mũi kiếm chỉ về hành lang sơn đạo Xuyên Hà.
Hắn nghiêm giọng nói:
“Toàn quân tướng sĩ chỉnh trang sẵn sàng. Giờ Dần ngày kia, nổi trống xuất quân, vòng qua Xuyên Hà!”
“Vâng! Tướng quân!”
Đợi hai vị hiệu úy Mông Tranh và Đan Khởi cáo lui, phó tướng Kinh Thiện chờ ngoài trướng mới chậm rãi cung kính đi vào.
Nhìn thấy người đến, Hoắc Yếm theo bản năng nhìn ra phía sau Kinh Thiện, nhưng lại không thấy bóng dáng kiều mềm mà mình muốn gặp. Vì vậy ánh mắt hắn rơi vào khoảng không, dừng lơ lửng ở một chỗ.
Chưa đợi hắn hỏi, Kinh Thiện đã ôm quyền bẩm trước.
“Tướng quân, thuộc hạ làm theo phân phó, trước giờ hẹn một khắc đã đến cửa phụ hậu doanh yên lặng chờ. Nhưng đến giờ ngọ rồi lại qua thêm một nén hương, vẫn không thấy bóng dáng bất kỳ ai.”
Nghe vậy, Hoắc Yếm khẽ nhíu mày, không khỏi lo lắng nàng có phải nhớ nhầm thời辰, quên hai người đã hẹn sau giờ ngọ hay không.
“Có lẽ vẫn còn đang trên đường. Ngươi cứ tiếp tục lưu ý chờ nàng.”
Hoắc Yếm bình thản lên tiếng, giọng điệu không có dao động gì. Nhưng Kinh Thiện theo hắn quá lâu, cho nên lúc này có thể nhạy bén nhận ra, trong khẩu khí của tướng quân rõ ràng lộ ra vài phần sốt ruột, tựa như vội vã mong được gặp người kia đến mức nào.
Đối với chuyện này, Kinh Thiện có vài phần ngẩn ra, không biết rốt cuộc là thần tiên phương nào dám ra vẻ lớn như vậy, vậy mà khiến tướng quân phải chờ đợi như thế.
Kinh Thiện tự nhiên vô cùng tò mò về thân phận vị “quý khách” này, nhưng vì kính sợ uy thế của tướng quân, nên không dám tùy ý mở miệng hỏi thăm.
Trong lòng hắn lại không khỏi suy nghĩ, đại khái từ sau lần âm độc phát tác trước, tướng quân luôn có vài hành động kỳ quái. Ví như phá lệ thưởng cho hắn một thanh bảo kiếm hiếm có, còn luôn vòng vo nói lần này hắn có công. Lại như hôm nay, thần thần bí bí bảo hắn đi tiếp đón khách bên ngoài doanh.
Kinh Thiện mơ mơ hồ hồ. Hai ngày nay không ít lần được tướng quân thể tất khao thưởng, bản thân hắn cũng hết sức được sủng mà lo.
Nghĩ đến hiện tại, hắn không khỏi liên tưởng, sự khác thường hai ngày nay của tướng quân liệu có liên quan đến vị quý khách đến muộn kia hay không.
Hắn còn chưa nghĩ thông, rất nhanh đã tiếp tục nhận lệnh. Vì vậy chỉ đành quay lại hậu doanh, khổ sở đội mặt trời nóng rực tiếp tục chờ người.
Còn Hoắc Yếm một mình ở lại trong trướng, ngồi ngay ngắn trước bàn án, cụp mắt lật xem công văn nhọc lòng. Chỉ là còn chưa nghiêm túc đọc xong mấy quyển, hắn đã không nhịn được phiền躁 mà đứng thẳng dậy.
Có phải trên đường đã xảy ra chuyện gì ngoài ý muốn không…
Trong mắt Hoắc Yếm lóe lên vài phần lo lắng. Vì vậy hắn không do dự nhiều, trực tiếp vén rèm ra khỏi trướng, định tự mình đi đón một chuyến.
Mà Hoắc Yếm không biết rằng, giờ phút này người trong lòng khiến hắn lo lắng nhớ mong thật ra đã sớm đến gần trướng của hắn. Chỉ là vì trong lòng khiếp sợ, nàng do dự thật lâu vẫn không dám tiến lên.
…
Bên cạnh chủ trướng, sau một đống lều thấp, Thi Nghê co người nhỏ nhắn đáng thương, âm thầm quan sát. Đồng thời vì căng thẳng, lòng bàn tay nàng không ngừng toát mồ hôi lạnh.
Trong quân doanh, ai ai cũng nói chủ soái tướng quân không thích, thậm chí khinh thường người Tây Lương. Vì vậy nàng rất sợ mình mạo muội đến cầu tình như vậy, chỉ càng chọc hắn khinh miệt chán ghét thêm.
Nhưng trước mắt vì A Giáng, ngoài hạ mình cầu xin, nàng thật sự không còn cách nào khác.
Không lâu sau, nàng nhìn thấy hai quân tướng mặc giáp đen một trước một sau đi ra từ chủ trướng. Thi Nghê tập trung tinh thần, tim đập nhanh hơn. Lại nhận ra một trong hai người chính là Mông hiệu úy, vì vậy càng xác nhận rằng nàng không tìm nhầm chỗ.
Chủ soái tướng quân lúc này hẳn đang ở trong trướng này.
Sau một hồi do dự, Thi Nghê cắn răng định tiến lên. Không ngờ lúc này trong trướng lại bỗng có một người đi ra, dọa nàng vội khựng chân lại, hoảng hốt cúi đầu xuống.
May mà người kia không chú ý đến động tĩnh bên nàng. Sau khi ra khỏi trướng, hắn nhanh chóng sải bước rời đi. Thi Nghê cẩn thận quan sát, đánh giá kiểu dáng giáp trụ và bao tay giáp của người này hơi giản lược, đoán rằng hắn hẳn chỉ là một phó tướng bên cạnh chủ soái.
Thi Nghê cẩn thận dừng lại thêm một lúc. Xác nhận trong trướng sẽ không còn người nào đi ra nữa, lúc này nàng mới lần nữa lấy hết dũng khí tiến lên.
Nhưng vạn lần không ngờ, nàng vừa mới dời người ra khỏi sau lều thấp, đã thấy rèm trướng lại bị người bên trong đột nhiên vén lên. Nàng khựng bước nhìn kỹ, lập tức nghi ngờ có phải mình xuất hiện ảo giác hay không.
Nam tử đột ngột hiện ra trước mắt có dáng người cao lớn uy nghi, mày kiếm lạnh lẽo mang theo sát khí. Nhưng vì sao… hắn lại giống tên sơn tặc kia đến vậy?
Thi Nghê sững sờ đứng nguyên tại chỗ, không dám động đậy nữa. Trong đầu càng rối thành một mớ hồ nhão, không thể sắp xếp rõ ràng mấu chốt trong đó.
Mà ông trời lại càng không chiều lòng người. Lúc này, cát bụi bỗng bị một trận gió bắc dữ dội cuốn lên, thổi lá cờ phía sau Thi Nghê lắc lư nghiêng ngả, suýt nữa đổ xuống.
Nghe thấy động tĩnh, nàng theo bản năng ngẩng đầu nhìn lên, liền thấy một lá quân kỳ đỏ bốn góc đang phấp phới trên đầu, chực chờ đổ xuống phía mình.
Trong khoảnh khắc nguy cấp này, lòng Thi Nghê chấn động. Đồng thời nàng quên cả né tránh, chỉ mở to mắt, cứng đờ nhìn chằm chằm chữ viết trên lá cờ phía trên.
Thi Nghê không thể tin nổi, bởi vì ký tự xa lạ trên mặt cờ ấy, rõ ràng nàng đã từng thấy.
Đêm tắm nơi khe suối hoang dã, tín vật lệnh bài mà tên sơn tặc thô lỗ nàng gặp để lại cho nàng, bên trên vậy mà khắc cùng một chữ “Hoắc”.
Thì ra, đó là chữ Đại Lương.
Vậy nên, thân phận của hắn…
Trong kinh ngạc chấn động, ánh mắt hai người đột nhiên giao nhau giữa không trung.', '2026-06-01 15:36:16.229096+00'), (18, 2, 11, 'Chương 10: Mỹ nhân thật cao tay ', 'Trong lòng muôn vàn kinh hãi, cột cờ cũng sắp đổ xuống.

Trong khoảnh khắc ngàn cân treo sợi tóc, đầu óc Thi Nghê choáng váng, hoảng hốt kêu lên một tiếng. Nhưng cơn đau bị đập trúng trong dự liệu lại không truyền đến, chỉ có cổ tay bị người ta mạnh mẽ nắm lấy, cảm giác rõ ràng mãnh liệt.

Đối phương dùng sức rất lớn, cả người nàng loạng choạng trong chốc lát, sau đó thân thể xoay một vòng, dễ dàng bị hắn ôm vào lòng bảo vệ.

Lúc này, đầu óc Thi Nghê vẫn ong ong mờ mịt, chỉ nhận ra cái ôm này của hắn rất chắc. Lòng bàn tay hắn áp sát vào da thịt nàng, hoàn toàn không tránh hiềm nghi nam nữ.

Giống hệt sự cường thế của hắn đối với nàng đêm ấy.

“Có bị thương không?”

Giọng nói trầm thấp quen thuộc truyền vào tai, khiến Thi Nghê lần nữa xác nhận, tất cả những chuyện này đều không phải ảo giác.

Tên sơn tặc ngày ấy ở Hàn Trì ngang ngược giữ lấy nàng, chính là vị chủ soái tướng quân lần này Đại Lương phái đến Hội Kê, hộ tống cống lễ Tây Lương vào kinh.

Mà vì âm sai dương sai, hắn đã nhận nhầm nàng thành nữ tử đến hầu hạ hắn. Chuyện này thật sự quá… hoang đường!

“Sợ rồi sao? Kinh Thiện sao lại để nàng một mình ở đây, hắn đâu?”

Hoắc Yếm đương nhiên cho rằng Kinh Thiện đã đón được người. Hắn giơ tay vỗ nhẹ lưng nàng hai cái như an ủi, giọng điệu cũng rất dịu.

Nhưng dưới hơi nóng bỏng trong lòng bàn tay hắn, Thi Nghê căn bản khó mà thả lỏng, thậm chí sống lưng không khỏi càng thêm cứng đờ.

Nàng không dám động, càng không dám nói. Nếu có thể, lúc này nàng chỉ muốn che mặt biến mất ngay tại chỗ, trốn khỏi nơi này.

“Sao không nói gì?”

Mãi không nhận được câu trả lời, Hoắc Yếm lo lắng liệu nàng có thật sự bị thương hay trẹo chân không. Hắn cúi mắt cẩn thận nhìn xuống, lại thấy trên mặt nàng không lộ vẻ đau đớn, lúc này mới yên tâm.

Có điều, nàng cứ né tránh ánh mắt, không dám nhìn hắn, thần thái cũng kiều khiếp rụt rè. Thấy vậy, Hoắc Yếm khẽ cong môi, chỉ cho rằng nàng vẫn chưa quen ở bên cạnh mình.

Hắn giơ tay nắm lấy cằm nàng, nâng lên, muốn nàng đối diện với mình. Vì vậy Thi Nghê run rẩy bị ép ngẩng đầu, trong ánh mắt lấp lánh vẻ khiếp sợ cùng vài phần cảm xúc khó nói.

Sau một hồi do dự, cuối cùng nàng khó khăn gọi ra:

“Tướng… tướng quân…”

Một tiếng mềm như nước chảy này khiến Hoắc Yếm không hiểu sao tâm tình vô cùng khoan khoái. Vùng da non mềm bị đầu ngón tay hắn vuốt qua cũng theo đó hiện lên một mảng đỏ nhạt.

Hắn căn bản không dùng sức, là nàng quá đỗi mềm yếu.

Ánh mắt Hoắc Yếm càng thêm trầm đậm, trong lòng hơi tê dại. Hắn lại không nhịn được cúi đầu sát gần nàng hơn, giọng điệu cũng mang theo ý trêu chọc:

“Bắt ta chờ lâu như vậy, nàng tự nói xem, có nên phạt không?”

Giọng điệu mang theo vài phần sủng nịch này rõ ràng là lời thì thầm dành cho tình nhân. Trong lòng Thi Nghê phức tạp khó chịu. Hóa ra hắn vẫn chưa biết, nhưng hắn lập tức sẽ biết chân tướng.

Một bên là mỹ nhân cống lễ của bại quốc dâng lên, một bên là chủ soái Đại Lương phụ trách hộ tống trên đường. Quan hệ thân phận vi diệu như thế, cộng thêm cuộc gặp gỡ ban đầu không hợp thời đến vậy, nếu đổi lại là nàng, e rằng cũng sẽ cho rằng bên trong có âm mưu do người sắp đặt.

Thi Nghê đã chuẩn bị cho tình huống xấu nhất trong lòng. Thậm chí nàng từng tưởng tượng, nếu hắn biết chân tướng, có lẽ sẽ giận dữ lôi đình, rồi trực tiếp lấy lý do nàng ôm lòng hiểm độc, rút kiếm lấy mạng nàng.

Nghĩ đến đây, nàng càng thêm sợ hãi, vì vậy theo bản năng co rụt trong lòng hắn, như trốn tránh chờ chết mà không dám động đậy.

Hoắc Yếm lại ôm đến hưởng thụ, nhẹ giọng nói:

“Được rồi, cũng đâu phải thật sự định phạt nàng, sợ cái gì.”

Nói xong, hắn lại khẽ cọ chóp mũi nàng, cười nàng nhát gan, nhưng trong lòng thực ra lại vô cùng hưởng thụ sự gần gũi của nàng.

Hắn vốn là võ nhân thô dã chinh chiến sa trường, sát phạt quyết đoán, dựa vào lưỡi đao nhuốm máu, thương kích đoạt hồn, khiến tướng địch đối trận nghe tiếng đã mất vía. Hắn cũng vì thế mà có được danh hiệu sát khí như Diêm La tướng quân.

Nhưng một chiến thần kiêu hùng như vậy, người trong lòng hắn thích lại không phải nữ tướng oai phong giỏi giang, ngược lại thiên vị kiểu mỹ nhân yếu mềm quyến rũ, tay trói gà không chặt, vừa kiều vừa đáng thương thế này.

Hoắc Yếm có chút xấu hổ phải thừa nhận rằng, hắn tổng cộng mới gặp người ta hai lần, nhưng lần nào cũng dễ dàng bị ánh mắt rụt rè của nàng câu lấy. Cả thân lẫn tâm đồng thời dâng lên một loại dục vọng chinh phục khác thường.

Khoảnh khắc ấy, hắn cam tâm tình nguyện khuỵu gối, trở thành thần tử dưới váy nàng.

“Tướng quân, ngài… ngài có biết tên ta không…”

Bị áo giáp lạnh cứng trên người hắn cấn vào, Thi Nghê cũng vì vậy tỉnh táo hơn vài phần. Nàng nghẹn một hơi đến tận cổ họng, sau đó chủ động gian nan hỏi.

Lúc này điều nàng nghĩ là, nếu có thể lập tức bị hắn trách phạt, có lẽ trong lòng còn dễ chịu hơn một chút. Vẫn tốt hơn hiện giờ, bị hắn ôm lấy che chở, trong lòng lại giày vò đến muốn chết.

Sự ôn tình này của hắn vốn sẽ không dành cho một nữ tử Tây Lương.

Nghe vậy, Hoắc Yếm không do dự mà thẳng thắn mở miệng:

“Hình như chưa từng hỏi qua. Có điều, tên chỉ là một cách xưng hô hư danh mà thôi. Ta nhận định chính là con người nàng. Bất kể nàng tên gì, sau này nàng đều là của ta.”

“…”

Nghe hắn ghé tai nói như vậy, Thi Nghê chỉ cảm thấy sau lưng toát mồ hôi lạnh. Sự việc dường như càng lúc càng không thể khống chế.

Vì vậy, Thi Nghê đành cắn răng, uyển chuyển nhắc nhở:

“Nhưng có đôi khi… tên họ thân phận, tông tộc địa vị của một người, từ khi sinh ra đã được định sẵn. Hơn nữa những trói buộc mà nó mang đến ở khắp mọi phương diện, không thể dễ dàng vượt qua giới hạn.”

Nghe vậy, Hoắc Yếm chăm chú nhìn nàng, hiếm khi không cho là đúng mà cười cười:

“Sao vậy, có phải thôn làng của các nàng nhiều quy củ, người nhà nàng không muốn nàng đi theo ta? Nàng yên tâm, tiền tài bạc lượng không phải vấn đề, những chuyện khác cũng đều có thể thương lượng. Hơn nữa, ta thật lòng thích nàng. Theo ta về kinh, ta sẽ thương nàng.”

Những lời thẳng thắn này khiến Thi Nghê sững sờ trong chớp mắt, trong lòng càng lóe lên vài phần phức tạp khó nói.

Quả thật, nếu bỏ qua thân phận tướng lĩnh địch quân của hắn, công bằng mà nói, Hoắc Yếm người này anh liệt uy mãnh, dũng mãnh vô song, xem như cường giả tuyệt đối. Có thể nhận được lời hứa miệng từ một nhân vật như vậy, đối với một nữ tử đáng thương mệnh như bèo trôi như Thi Nghê, sao có thể không động lòng?

Nhưng nàng không có số mệnh tốt như vậy. Thân là hàng lễ của nước bại trận, ngoài hoàng tộc Đại Lương, thiên hoàng quý tộc ra, còn ai dám muốn nàng?

Nghĩ đến đây, Thi Nghê rốt cuộc cũng nhụt chí, không còn sức tiếp tục lá mặt lá trái như vậy nữa. Vì vậy nàng thở dài, khó khăn mở miệng:

“Tướng quân, thật ra ta…”

Nàng còn chưa nói xong, từ xa đột nhiên có một đội binh sĩ tuần tra đi đến. Hoắc Yếm phản ứng nhanh chóng, trước khi bọn họ đến gần, hắn ôm nàng nghiêng người tránh qua, không để người trong lòng rơi vào mắt kẻ khác.

Theo quân mang một nữ tử hồi kinh vốn đã là ngoại lệ, Hoắc Yếm biết rõ chuyện này không nên tiếp tục phô trương.

Mà Thi Nghê càng căng thẳng hơn. Khi có người đến, gần như theo bản năng nàng vùi vào lòng hắn trốn tránh.

Nàng không biết đội tuần tra đã đi xa hay chưa, cho nên vẫn giữ nguyên động tác, không dám động lung tung. Cho đến một lúc lâu sau, Hoắc Yếm trên đỉnh đầu nàng mới dùng giọng nghiêm túc, lại tựa như mang theo vài phần ý cười mà mở miệng:

“Đợi lát nữa vào trướng rồi mặc nàng ôm. Bây giờ còn đang ở bên ngoài, khó tránh nhiều người nhiều mắt. Quấn quýt như vậy không hợp quy củ.”

Quấn quýt…

Cách dùng từ không đứng đắn của hắn khiến gò má Thi Nghê không khỏi đỏ lên. Nàng hoảng hốt lùi về sau một bước, ánh mắt có chút vô tội.

“Ta, ta không có…”

Hoắc Yếm thuận thế buông nàng ra, không so đo với nàng. Sau đó hắn giơ tay chỉ về phía chủ soái doanh trướng sau lưng nàng, lại nói:

“Đại quân còn phải chỉnh đốn ở đây hai ngày. Trong doanh cũng không còn trướng bồng thích hợp dư ra. Hai ngày này, nàng tạm thời ở cùng ta.”

Nói xong, ánh mắt hắn cũng mất tự nhiên một chút, nhưng rất nhanh lại khôi phục bình tĩnh.

Hắn nhìn nàng, ngay cả ánh mắt cũng mang theo vẻ bá đạo.

Thi Nghê không chịu nổi nữa. Lúc này, nàng hoảng hốt ngẩng mắt, liền thấy phía sau Hoắc Yếm, đối diện đang có hai vị tướng quan đi tới.

Thấy vậy, nàng không khỏi nín thở nhìn kỹ, căng thẳng đến mức tim đập như trống. Bởi vì một trong hai người đó nàng nhận ra rất rõ, chính là Mông hiệu úy đóng giữ quân doanh, người thường xuyên gặp mặt nàng, Mông Tranh.

Rất nhanh, Mông Tranh cũng đối diện nhìn thấy nàng. Hắn lập tức nhíu mày, ánh mắt đảo qua giữa nàng và Hoắc Yếm, trong mắt phức tạp hơn rất nhiều.

“Tướng quân!”

Hoắc Yếm đang xuất thần, nghe vậy mới nhận ra điều gì mà nhíu mày quay đầu. Hắn theo bản năng ánh mắt cảnh giác, đồng thời chắn Thi Nghê ở sau lưng.

Ngẩng mắt lên, thấy người đến là Kinh Thiện và Mông Tranh, lúc này hắn mới buông lỏng phòng bị. Hai người này đều là tâm phúc thuộc hạ của hắn, không cần che giấu.

Nhưng không ngờ, sau khi Mông Tranh đi đến gần, ánh mắt lại trực tiếp dừng trên người Thi Nghê. Hoắc Yếm có chút khó chịu không rõ nguyên do, đang định mở miệng, liền thấy Mông Tranh đã ôm quyền nhận lỗi trước.

“Chuyện nhỏ như vậy còn phải quấy rầy tướng quân, thật sự là mạt tướng xử lý không thỏa đáng. Mạt tướng nguyện lĩnh tội.”

Hoắc Yếm nheo mắt, không hiểu hành động của hắn là vì sao.

Mà Mông Tranh vẫn khom người, ngừng một chút rồi nói tiếp:

“Vừa rồi ta đã đến sân luyện binh tìm hiểu đại khái sự việc, biết lần này quả thật là mỹ nhân chịu uất ức. Hiện tỳ nữ thân cận A Giáng của mỹ nhân đã được an toàn đưa về, Phùng đại nhân cũng đã nhận lỗi. Sự việc xem như xử lý thỏa đáng.”

“Ngươi gọi nàng là gì?”

Hoắc Yếm nghe xong lời Mông Tranh thuật lại, sắc mặt đã hoàn toàn trầm xuống. Hắn không quay người nhìn Thi Nghê, chỉ dùng đôi đồng tử đen nhánh lạnh nhạt, ánh mắt sắc bén chất vấn Mông Tranh.

Mà Mông Tranh hiển nhiên vẫn chưa hiểu tình hình hiện tại, nghe vậy không chút kiêng dè, cung kính đáp:

“Thi cô nương là người Tây Lương kính dâng vào cung. Nhưng dù sao nàng ấy vẫn chưa chính thức hầu chủ, cũng chưa được ban phong hiệu ngự tứ, cho nên tạm gọi là mỹ nhân, hẳn là hợp quy chế.”

Hầu chủ…

Cơn giận vừa rồi khó khăn lắm mới khắc chế được, sau khi nghe thấy hai chữ này, rốt cuộc không thể áp chế mà bộc phát dữ dội. Đáy mắt hắn cuồn cuộn lửa giận bị tôi luyện, quanh thân lại lạnh lẽo bức người.

Hắn xoay người nhìn Thi Nghê, trong mắt không còn vẻ thương tiếc, chỉ còn sự phẫn nộ và khinh thường sau khi bị lừa gạt.

Trước mặt hai thuộc hạ, hắn trầm mặc hồi lâu, cuối cùng vẫn không nói gì. Chỉ dùng ánh mắt nhìn chằm chằm nàng, ánh mắt sắc bén như dao, đâm đến nàng không còn mảnh giáp, tựa như chịu đủ roi vọt.

“Mông Tranh, ngươi lui xuống. Kinh Thiện theo ta vào trướng!”

“… Vâng!”

Hai người nhìn nhau, không hiểu vì sao tướng quân đột nhiên đổi sắc mặt.

Bọn họ không dám hỏi nhiều, nghe vậy liền vội làm theo.

Mông Tranh rời đi, Kinh Thiện thì cất bước theo sau. Chỉ là vừa đi được hai bước, hắn liền thấy tướng quân thô bạo nắm lấy cổ tay Thi cô nương, không chút thương tiếc trực tiếp kéo người cùng vào trong trướng.

Cảnh tượng này khiến Kinh Thiện hoàn toàn mờ mịt. Tướng quân tuy là quân tướng múa đao dùng thương, nhưng cũng chưa bao giờ vô lễ với nữ tử như vậy. Chẳng lẽ vì đối phương là nữ tử Tây Lương nên mới bản năng không thích?

Nhưng trừ điểm thân phận này ra, Thi cô nương dung mạo diễm lệ, đẹp đến kinh người, nhìn thế nào cũng là người khiến kẻ khác yêu thích. Hơn nữa nghe Mông hiệu úy nói, tính tình nàng ôn hòa dịu dàng, đến doanh mấy ngày cũng an phận thủ thường.

Đã như vậy, tướng quân xưa nay công chính, cho dù trong lòng không thích, ngoài mặt cũng nên hòa nhã với người ta một chút mới phải.

Trong trướng chỉ có ba người bọn họ. Hoắc Yếm không nói lời nào, bọn họ cũng không dám mở miệng. Vì vậy không khí trầm lặng, bầu không khí dị thường quỷ dị.

Một lúc lâu sau, Hoắc Yếm mở miệng:

“Kinh Thiện, ngươi có nhận ra nàng không?”

Kinh Thiện mờ mịt thành thật đáp:

“Trước đây không quen biết, hôm nay gặp rồi mới biết thân phận của nàng ấy.”

“Ngày đó bệnh cũ của ta tái phát, ngươi nói muốn tìm một nữ tử đến Hàn Trì hầu hạ, đúng hay không?”

Kinh Thiện càng mờ mịt hơn, không biết vì sao tướng quân đột nhiên nhắc đến chuyện cũ.

Hắn cung kính trả lời:

“Thuộc hạ quả thật có đề nghị này, nhưng khi đó tướng quân đã nói rõ từ chối, thuộc hạ tự nhiên không dám có chút trái lệnh nào.”

Không dám trái lệnh…

Lời vừa dứt, Hoắc Yếm im lặng rất lâu.

Mãi đến một lúc sau, hắn mới dùng giọng khàn khàn quát:

“Cút ra ngoài.”

Kinh Thiện nhìn Thi Nghê một cái, ngơ ngác lui xuống.

Thi Nghê nghĩ ngợi, lại đợi thêm một chút. Thấy hắn không còn lời nào khác, liền cảm thấy câu “cút” vừa rồi hẳn cũng có phần của nàng.

Vì vậy nàng khuỵu gối hành lễ, muốn thoát khỏi sự giày vò này, nhanh chóng rời đi.

Chỉ là vừa xoay người, lời nói sắc bén lạnh lẽo phía sau đã chói tai truyền đến.

“Mỹ nhân đúng là thủ đoạn hay. Bây giờ còn chưa vào Thượng Kinh, đã không kịp chờ mà giở bao nhiêu tâm tư hoa hòe dọc đường. Quả thật vì mẫu quốc mà hao tổn tâm cơ.”

Hắn sắc bén cười lạnh, tiếp tục châm chọc:

“Có điều cô nương hy sinh cũng không nhỏ. Đêm đó ở Hàn Trì, cô nương y phục không che thân, cả người từ trên xuống dưới gần như đều bị tại hạ sờ qua một lượt. Quả thật da như mỡ đông, mềm mịn như ngọc. Chúng ta áp sát nhau lâu như vậy, không biết sau đó cô nương có hồi vị vài phần không?”

Thi Nghê đỏ bừng mặt vì xấu hổ giận dữ, chỉ lắc đầu phủ nhận:

“Tướng quân, ta thật sự không có…”

“Đủ rồi! Không cho phép nàng gọi ta!”

Hoắc Yếm lạnh giọng cắt ngang.

Không còn vẻ giễu cợt cố tỏ ra thoải mái, Hoắc Yếm không che giấu được nữa. Vài phần cảm xúc chân thật trong đáy mắt hiện ra. Màu mắt hắn sâu thẳm, xen lẫn nỗi tổn thương và sa sút sau khi bị lừa gạt.

Hắn tự nhận mình đầy một lòng chân ý, vậy mà nữ tử kia lại tâm địa hiểm ác, cố ý tiếp cận, chỉ vì muốn ly gián quan hệ quân thần Đại Lương.

Đem chân tâm của hắn giẫm đạp như cỏ rác…

Lời tác giả:

Tướng quân đang cầu được dỗ dành, ha ha.', '2026-06-01 15:38:51.249896+00'), (19, 2, 12, 'Chương 11: Sắc hồng', 'Thi Nghê đứng nguyên tại chỗ, nín thở không dám nói lời nào. Nàng nhìn thần sắc của Hoắc Yếm lúc này, đại khái biết hắn đã chán ghét nàng đến tận cùng.
Nhưng chuyện nàng chưa từng làm, nàng sẽ không nhận.
Cho dù đối phương mang theo thành kiến, trong lòng đã định tội nàng rồi.
Hai người im lặng giằng co thật lâu, mãi đến khi ánh mắt Hoắc Yếm dời sang bên, tâm tư lạnh trầm xuống.
Khi hắn mở miệng lần nữa, giọng điệu trầm tối cực chậm, đồng thời cũng thấm đầy mỉa mai lạnh lẽo:
“Nghe ta vì nàng hứa hẹn, nghiêm túc nói về tương lai sau này, trong lòng nàng chắc đắc ý lắm nhỉ?”
Dứt lời, hắn tự giễu cười một tiếng, không cho Thi Nghê cơ hội đáp lại, càng giống như đang tự nói với chính mình.
“Nàng quả thật nên đắc ý. Hai nước giao chiến, ta là chủ soái địch quân, liên tiếp đoạt mấy trọng thành nơi biên thùy Tây Lương. Nàng vì quốc thù mà oán hận ta, nhân cơ hội lấy thân mạo hiểm câu dẫn trả thù. Sau đó thấy ta chìm đắm trong ôn hương nhuyễn ngọc, không thể tự khống chế, trong lòng hẳn là rất thoải mái đi?”
Thoải mái?
Lúc đó rõ ràng nàng sợ đến sắp chết mà.
Nghĩ xem, nàng chỉ là một cô nương chưa xuất giá. Khi tắm rửa lại suýt nữa bị một nam tử xa lạ nhìn sạch, sau đó còn bị hắn không nói không rằng bá đạo ôm hết lần này đến lần khác. Trong tình cảnh như vậy, nàng có gì để đắc ý chứ?
Rõ ràng… là hắn chiếm đủ tiện nghi, còn thoải mái hưởng thụ hơn nhiều.
Đương nhiên, những lời này Thi Nghê tự nhiên không dám nói thẳng, cũng biết trong mắt hắn, những trùng hợp ngoài ý muốn ấy đều là âm mưu do người sắp đặt.
Nhưng lúc này bị hắn liên tiếp châm chọc nhiều câu, cho dù là người tính tình tốt như Thi Nghê, cũng khó tránh cảm xúc cuộn trào.
Vô cớ bị oan uổng, bất kỳ ai cũng sẽ cảm thấy tủi thân.
Thi Nghê tự nhủ nhất định phải nhịn, đừng khóc. Sau đó nàng lấy hết dũng khí nhìn thẳng hắn, đôi mắt ướt long lanh, dáng vẻ vừa đáng thương vừa quật cường.
Nàng cất giọng hỏi ngược lại, âm lượng không lớn, nhưng từng chữ từng câu đều nói rất nghiêm túc:
“Chuyện xảy ra ngày đó, phiền tướng quân cẩn thận hồi tưởng lại một lần. Từ lúc gặp tướng quân lần đầu đến sau khi tách ra, có phải toàn bộ mọi việc đều do tướng quân chủ đạo hay không? Hơn nữa khi ấy, ta không biết Hàn Trì là hồ tắm riêng của tướng quân, càng không biết thân phận của tướng quân. Thậm chí ta còn tưởng mình gặp phải sơn tặc cướp mạng, nên chỉ đành bị ép phối hợp…”
Nói đến đây, giọng Thi Nghê dần yếu xuống.
Sau đó hắn đã làm gì, chính bản thân hắn hẳn là rõ ràng nhất.
“Miệng lưỡi sắc bén.”
Hoắc Yếm nghe vậy nhíu mày lạnh mặt, hiển nhiên không tin.
“Hàn Trì đường cong lối khuất, ẩn nấp như vậy, sao có thể để nàng dễ dàng tìm được?”
Thi Nghê có lý có cứ đáp lại:
“Mấy ngày trước khi tướng quân về doanh, trong doanh quả thật thiếu nước dùng. Điểm này tướng quân có thể tìm Mông hiệu úy để xác minh. Ta chưa được cho phép đã tự ý ra khỏi doanh tìm suối tắm rửa, hành động này quả thật không thỏa đáng. Nếu tướng quân vì vậy trách phạt, ta tự nhiên nhận. Nhưng việc tìm được Hàn Trì quả thật là do đi nhầm lạc bước, tuyệt đối không phải như lời tướng quân nói, rằng ta mưu tính đã lâu, cố ý khỏa thân câu dẫn.”
Thi Nghê căng thẳng nghẹn một hơi, cuối cùng cũng nói hết những lời muốn nói.
Lúc này tuy như được trút gánh nặng, nhưng chóp mũi vẫn không tự chủ được mà cay cay.
Hoắc Yếm nghe lời kể của nàng, hơi trầm tư. Lúc này lòng phòng bị của hắn rất nặng, tự nhiên sẽ không chỉ nghe ba lời đôi câu của nàng rồi để nàng phủi sạch bản thân, từ đó xóa bỏ nghi ngờ.
Trong lòng hắn vẫn còn giận. Nhưng nhìn ánh lệ thấp thoáng trong đáy mắt nàng lúc này, dáng vẻ tủi thân muốn khóc lại cố nhịn, trong lòng hắn không khỏi cũng nổi lên vài phần phiền muộn.
“Tướng quân… ngài có tin ta không?”
Mãi không đợi được phản ứng của hắn, Thi Nghê có chút sốt ruột lên tiếng hỏi.
Tội danh câu dẫn chủ soái Đại Lương thật sự quá nặng. Nàng lại có thân phận vi diệu như vậy, làm sao gánh nổi.
Nhưng Hoắc Yếm nghe vậy lại không trực diện trả lời nàng. Sau khi suy nghĩ cẩn thận, hắn không bỏ qua chút sơ hở nào mà lại mở miệng chất vấn:
“Đêm đó vì muốn khiến nàng an tâm, ta từng không chút keo kiệt giao lệnh bài chủ soái cho nàng. Mà trước đó, nàng cũng đã ở trong quân doanh mấy ngày. Trong doanh nơi nơi đều có quân kỳ chữ Hoắc, trên lệnh bài cũng khắc phù văn giống hệt. Nàng nói nàng không biết thân phận của ta, cách nói này có phải quá gượng ép rồi không?”
Hoắc Yếm uy nghiêm nhìn nàng chằm chằm, ánh mắt lạnh lẽo nghiêm ngặt, như thể lúc này đang thẩm vấn một phạm nhân thật sự.
Thi Nghê chịu đựng ánh nhìn bức người của hắn, không khỏi hơi sững sờ.
Nhớ đến trước kia khi hắn nói chuyện với nàng, hắn đều cố ý thu lại phong mang trên người, hết sức phóng ra chút dịu dàng ấm áp. Còn bây giờ, hắn khôi phục uy nghi của chủ soái, từ trên cao nhìn xuống, không còn chút thương tiếc yêu thương nào nữa.
Không hiểu vì sao, trong lòng nàng không nhịn được mà chua xót trong thoáng chốc.
“Ta biết tướng quân đã định tội ta trong lòng. Ta có giải thích nhiều hơn nữa, tướng quân cũng có thể tìm ra chỗ kỳ lạ. Giống như bây giờ, nếu ta nói từ sau khi vào doanh, ta và tỳ nữ thân cận của mình bị sắp xếp ở góc chật hẹp nhất trong doanh, nơi nơi bị hạn chế, cũng chưa từng để ý đến ký tự trên quân kỳ, tướng quân cũng sẽ không dễ dàng tin, đúng không? Thậm chí ngài còn sẽ suy đoán chúng ta có phải đang cố ý tỏ yếu để cầu thương hại, bịa đặt lung tung chỉ để đổi lấy đồng tình khoan thứ hay không.”
Thi Nghê bình tĩnh kể ra những đối đãi bất công và oan khuất mình phải chịu.
Dù trong lòng vẫn sợ hãi, nàng vẫn cắn răng kiên trì nói hết.
Không chỉ là uất ức phải chịu hôm nay, mà những hà khắc vô cớ từ khi vào doanh đến nay, nàng đều nhớ rõ từng chuyện. Nàng càng biết rõ hiện giờ, ngoài việc tự mình tranh một hơi ra, nàng không còn bất cứ ai để dựa vào nữa.
Vì chính mình, vì A Giáng, nàng đều nhất định phải kiên cường lên.
Nghe vậy, Hoắc Yếm đứng im chăm chú thật lâu, như đang nghiền ngẫm trong lời nàng rốt cuộc có mấy phần chân thật.
Mãi đến một lúc sau, hắn mới dùng ánh mắt u tối, không rõ hàm ý mà lại mở miệng:
“Hóa ra nàng giỏi ăn nói như vậy. Trước kia gặp nàng, nói một câu cũng rụt rè sợ hãi.”
Thi Nghê rũ mắt xuống, tránh đi ánh nhìn của hắn, giọng nói lại trở về vẻ nhỏ nhẹ yếu ớt:
“Khi ấy tướng quân cứ dùng dao găm kề vào ta, ta… ta tham sống sợ chết, làm sao còn dám nói nhiều.”
“…”
Nghe tiếng nàng, đáy mắt Hoắc Yếm lập tức tối xuống. Cảm xúc vừa mới khó khăn lắm mới trấn định lại, lúc này chỉ vì một câu đơn giản của nàng trêu chọc, lại dễ dàng dấy lên ngàn tầng sóng dữ.
Hắn nheo mắt trầm xuống, bước mấy bước ép sát Thi Nghê, sau đó mạnh mẽ nắm cằm nàng nâng lên, buộc nàng đối diện với mình.
“Còn kêu oan gọi khuất, nói mình không phải tâm cơ khó lường, vậy bây giờ nàng như thế này là có ý gì?”
Lời nói trêu chọc, ánh mắt ướt át, còn nói không phải câu dẫn?
Thi Nghê bị ép ngẩng đầu, mờ mịt chớp mắt nhìn Hoắc Yếm. Thấy trong đáy mắt hắn không hiểu sao lại dâng lên một luồng giận dữ, lúc này nàng thật sự không hiểu ý hắn là gì.
“Bây giờ… bây giờ ta chỉ muốn tướng quân đừng tiếp tục hiểu lầm nghi ngờ chúng ta nữa. Nếu có thể, cũng phiền tướng quân làm chủ, trên đường hồi kinh đừng để chủ tớ chúng ta tiếp tục vô cớ chịu hà khắc.”
Nghĩ một chút, Thi Nghê cảm thấy dù sao cũng là cầu người giúp đỡ, vẫn nên nói lời dễ nghe hơn. Vì vậy nàng lại bổ sung:
“Tướng quân lập uy trong trăm quân, tự nhiên công chính biết lý, thưởng phạt phân minh. Vừa sẽ không để một người vô tội bị oan, cũng sẽ không dung túng thủ hạ ác ý bắt nạt người khác. Chúng ta tin tướng quân.”
Không biết Hoắc Yếm có nghe lọt lời nàng hay không. Nàng cuối cùng cũng nói xong, nhưng Hoắc Yếm lại không đáp lại.
Nàng đang định mở miệng lần nữa, Hoắc Yếm bỗng ép người lại gần hơn một chút. Tư thế cường thế, tựa như muốn ôm trọn nàng vào nơi an toàn.
“Tướng quân…”
Gần như vậy, Thi Nghê không khỏi có chút mất tự nhiên.
“Không cần nịnh nọt ta.”
Giọng Hoắc Yếm rõ ràng đã khàn hơn một chút.
Dưới sự bao phủ hoàn toàn của hắn, giọng Thi Nghê nhỏ yếu, khí thế hoàn toàn không còn.
Chênh lệch thân hình hai người lại lớn. Hắn áp sát không hợp quy củ như vậy, Thi Nghê tựa như cả người đều lọt thỏm trong lòng hắn, trông càng đặc biệt nhỏ nhắn yếu mềm.
“Bây giờ còn tham sống sợ chết không?”
Hai mắt hắn u ám, ác ý áp sát nàng một chút.
Thi Nghê nhận ra điều gì đó, thân thể lập tức cứng đờ, không dám động nữa. Lúc này, thanh dao găm sắc bén của hắn lại như đang uy hiếp, thật sự chọc vào hõm eo nàng.
“Sợ… sợ chứ.”
Nàng khiếp nhược thành thật đáp, không muốn ôm oan mất mạng ở đây.
Nghe vậy, Hoắc Yếm lại giật khóe môi châm biếm, muốn xem nàng rốt cuộc có thể giả ngây giả dại đến khi nào.
Hắn căng mặt, dùng sức nắm cổ tay nàng, sau đó thử chậm rãi kéo xuống dưới.
“Nếu nàng sợ nó, vậy tự mình lấy ra đi.”
Hắn muốn dùng cách cực đoan, cưỡng ép nàng lộ sơ hở.
Thi Nghê không tự chủ được ngẩng mắt lên. Lúc này nàng thấy ánh mắt hắn đậm đặc, bên trong như cuồn cuộn hơi nóng.
Ánh mắt này Thi Nghê cảm thấy quen thuộc. Ngày đó khi tắm ở khe suối Hàn Trì, lúc âm độc của hắn phát tác, trong ánh mắt cũng từng lóe lên dục niệm giống như vậy.
Vậy lúc này, hắn lại đang nghĩ gì…
Suy nghĩ trôi nổi hơi lâu, Hoắc Yếm dường như đã chờ đến mất kiên nhẫn.
“Sao, không làm được à?”
Hắn dùng giọng điệu như đã đoán trước, đáy mắt đầy vẻ mỉa mai. Đồng thời cũng buông cổ tay nàng ra, như thể đã nhìn thấu nàng.
Mà Thi Nghê lại khó hiểu. Nàng rất thản nhiên lắc đầu, sau đó mờ mịt hỏi:
“Việc này rất dễ, vì sao lại không làm được?”
Nói xong, nàng làm bộ đưa tay xuống thăm dò. Mà Hoắc Yếm không kịp ngăn lại, sắc mặt lập tức trầm xuống như muốn giết người.
Đầu nhọn sắc bén vừa mới lướt qua đầu ngón tay nàng, hắn đã không kìm được mà khẽ thở gấp một tiếng.
Thi Nghê khựng lại, tai không hiểu sao cảm thấy hơi tê ngứa.
Nhưng nàng còn chưa kịp thật sự nắm lấy, đã bị Hoắc Yếm dùng sức đẩy mạnh ra. Bước chân nàng không vững, lảo đảo một cái, không cẩn thận ngã xuống đất.
Vạt váy màu vàng nhạt như màu uất kim hương trải rộng trên mặt đất. Ánh mắt Thi Nghê ngơ ngác, trong đáy mắt toàn là mờ mịt.
“Đủ rồi!”
Hoắc Yếm như tránh né hồng thủy mãnh thú, hoảng loạn lùi liền ba năm bước. Ngay sau đó, một tầng đỏ ửng khác thường nhanh chóng lan khắp gương mặt tuấn tú và cổ hắn.
Thi Nghê ngồi tại chỗ khó hiểu. Tướng quân vì sao lại nổi giận lớn như vậy nữa.
Lời tác giả:
Hoắc Yếm: !!
Thi Nghê: ?
Một mình chàng binh hoang mã loạn, ha ha.', '2026-06-01 15:46:35.196343+00'), (20, 2, 13, 'Chương 12: Làm chỗ dựa ', 'Một tiếng quát trầm của Hoắc Yếm lập tức khiến thủ hạ bên ngoài cảnh giác đề phòng.

Nhất là Kinh Thiện, phản ứng nhanh nhất. Chưa đến chốc lát, hắn đã đến gần ngoài trướng, ngay sau đó cung kính xác nhận hỏi:

“Tướng quân, bên trong xảy ra chuyện gì, có cần chúng thuộc hạ can thiệp không?”

Hỏi xong một lúc lâu, bên trong vẫn không truyền ra chút động tĩnh nào.

Kinh Thiện nhíu mày, lòng phòng bị lập tức càng nặng. Hắn đang định mở miệng lần nữa thì nghe giọng nói trầm khàn căng chặt của Hoắc Yếm lạnh lùng truyền đến:

“Vào đây!”

Nhận lệnh vào trướng, ánh mắt đầu tiên của Kinh Thiện lướt qua mỹ nhân yếu mềm đang ngã trên đất. Miệng hắn hơi hé ra, đáy mắt thoáng hiện vẻ kinh ngạc.

Hắn tự nhiên không dám tùy tiện bàn luận hành vi của chủ soái, nhưng lúc này cũng khó tránh khỏi suy nghĩ, cho dù tướng quân không thích nữ tử Tây Lương này đến đâu, cũng không đến mức ra tay trước mặt với một nữ tử yếu ớt tay trói gà không chặt chứ.

Nếu chuyện này truyền ra ngoài, e rằng sẽ tổn hại uy nghi của tướng soái.

Lại nhìn lúc này, trên mặt tướng quân đang đỏ lên bất thường vì tức giận. Hắn liền mơ hồ đoán rằng, hai người có lẽ thật sự đã xảy ra tranh chấp.

Kinh Thiện không dám nói nhiều, chỉ đành đứng nguyên tại chỗ, khom người im lặng chờ lệnh.

Một lúc lâu sau, cuối cùng cũng nghe tướng quân lên tiếng. Hắn nói ngắn gọn rõ ý, lạnh lùng nói:

“Ngươi tự lo liệu cho tốt.”

Nghe vậy, Kinh Thiện căng thẳng ngẩng mắt, liền thấy ánh mắt tướng quân rơi sang bên, sắc mặt lạnh lẽo. Hắn lập tức biết lời này đại khái không phải nói với mình.

Lại nhìn Thi cô nương, lúc này ánh mắt nàng ướt át, dáng vẻ mờ mịt đến đáng thương.

“Kinh Thiện, đưa nàng về.”

Hoắc Yếm mất kiên nhẫn phất tay, quanh thân đầy lệ khí, như thể không muốn nhìn thêm nàng dù chỉ một cái.

Thấy vậy, Kinh Thiện mang lòng nghi hoặc, nhưng cũng vội đáp lời nhận lệnh. Sau đó hắn tiến lên nửa bước, khom người định đỡ Thi Nghê đang nửa ngã trên đất đứng dậy.

Lúc này hắn đưa tay ra hoàn toàn là xuất phát từ lòng tốt bản năng muốn giúp đỡ. Nào ngờ giây tiếp theo, hắn bỗng nhạy bén cảm thấy sau lưng có một ánh mắt sắc bén như mũi nhọn đang lạnh lẽo quét qua.

Ngay sau đó, một tiếng quát quen thuộc mà uy nghiêm trực tiếp truyền đến chói tai:

“Đừng chạm vào nàng.”

Kinh Thiện nghe tiếng thì sống lưng cứng đờ, động tác còn chưa chạm tới nàng cũng vì thế mà khựng lại.

Hắn do dự thu tay về, lại khó hiểu quay đầu nhìn Hoắc Yếm.

Chỉ thấy sắc mặt hắn rất trầm, lời nói càng cứng rắn không lành:

“Nàng tự có tay có chân, cần ngươi giúp làm gì?”

Xem ra tướng quân thật sự có khúc mắc không nhỏ với Thi cô nương. Nghĩ đến đây, Kinh Thiện đứng trở về chỗ cũ, không dám tự ý làm chủ nữa.

Còn Thi Nghê thì khẽ thở dài một hơi, không nói thêm gì, bèn tự mình nhịn cơn đau nhức nơi mắt cá chân, gian nan chậm rãi chống người đứng dậy.

Thấy hai người giữ khoảng cách nhất định, sắc mặt Hoắc Yếm hơi dịu lại, thu đi tia lạnh trong mắt.

Nhưng hắn không biết, sự thay đổi cảm xúc thoáng qua trong nháy mắt này đã bị Kinh Thiện nhạy bén bắt được.

Kinh Thiện ngẩn ra tại chỗ, cảm thấy hẳn là mình nhìn lầm rồi. Ánh mắt vừa rồi của tướng quân lạnh lẽo nặng nề, rõ ràng toàn là chiếm hữu.

Tựa như đó là vật thuộc về hắn, chạm vào là giết không tha.

Bàn tay kia của hắn đúng là không nên đưa ra.

…

Trên đường trở về, Kinh Thiện đi bên cạnh Thi Nghê, dựa theo bước chân của nàng mà chậm lại tốc độ của mình.

Hắn mấy lần muốn nói lại thôi, mỗi lần lời đến cổ họng lại cảm thấy không ổn mà thôi.

Cuối cùng, vẫn là Thi Nghê nhận ra điều gì, ánh mắt liếc sang bên, nhìn ra ý định của hắn.

“Nếu phó tướng có lời muốn nói, cứ nói không sao.”

Nàng ôn hòa nhìn hắn nói.

Kinh Thiện mím môi, do dự nhìn Thi Nghê.

Hắn là người tin vào tướng mạo. Lần đầu gặp Thi Nghê, hắn đã cảm thấy nàng giọng nói ôn hòa dịu dàng, tính tình hiền thiện, không giống người sẽ dùng quỷ kế âm độc.

Chỉ là hiện giờ tướng quân thành kiến với nàng khá sâu, hắn đứng bên nhìn cũng có vài phần không đành lòng, lúc này mới quyết định nhắc nhở đôi câu.

Hắn định thần lại, lập tức nghiêm mặt mở miệng nói:

“Cô nương chớ trách ta nhiều lời. Ta đi theo chủ soái nhiều năm, hiểu rất rõ tính tình của tướng quân. Những năm qua, vì bảo vệ biên cảnh Đại Lương yên ổn, ngài ấy chinh phạt sát lục, dùng máu tế lưỡi đao, vì thế ở sáu nước có được danh hiệu sát khí khiến người người khiếp sợ là Quỷ Diêm La. Nhưng bản thân ngài ấy tuyệt đối không phải loại hung tàn bạo ngược, cũng sẽ không vô cớ trách phạt bất công.”

“Trước mắt… có lẽ vì lập trường đối địch trước đây của hai nước, tướng quân mới nghi tâm nặng nề, cũng có thành kiến bất mãn với cô nương. Ta tuy không biết hôm nay giữa hai người rốt cuộc đã xảy ra chuyện gì, nhưng cũng đại khái đoán được cuộc nói chuyện trong trướng vừa rồi dường như không thuận lợi. Cho nên ta muốn khuyên cô nương, tướng quân xưa nay là người ăn mềm không ăn cứng. Khi gặp chuyện, nếu cô nương có thể mềm lời thuận theo ngài ấy một chút, trên đường vào kinh sau này hẳn sẽ dễ chịu hơn.”

Kinh Thiện không hề keo kiệt dạy Thi Nghê đạo sinh tồn. Không chỉ vì tướng mạo Thi Nghê hợp mắt hắn, mà còn vì trong nhà hắn có một tỷ tỷ tuổi tác xấp xỉ Thi Nghê.

Lần đầu nhìn thấy nàng, trong lòng hắn hơi chua xót, liền cảm thấy thân thiết khác thường.

Trong ký ức, tỷ tỷ hắn cũng dịu dàng yểu điệu như vậy, đẹp như tiên tử.

Nghe hắn liên tiếp nói nhiều như thế, Thi Nghê có chút bất ngờ. Đến doanh nhiều ngày, Kinh Thiện xem như người Đại Lương duy nhất đối xử hiền hòa với nàng.

Vì vậy nàng thành tâm cảm tạ:

“Đa tạ lời thật lòng chỉ điểm của phó tướng, ta sẽ nghiêm túc ghi nhớ. Ta đương nhiên biết tướng quân không phải người tàn bạo hung ác. Vừa rồi… chỉ là chúng ta sinh hiểu lầm, nhưng bây giờ đều đã nói rõ rồi.”

Nghe nàng nói vậy, Kinh Thiện gật đầu, lúc này mới yên tâm.

Mắt thấy đã đi đến trước trướng, Thi Nghê khuyên hắn dừng bước, sau đó muốn thi lễ nhẹ một cái, lại bị Kinh Thiện vội vàng ngăn lại.

“Cô nương tuyệt đối không được làm vậy. Trên dưới toàn quân, ngoài tướng quân ra, còn ai dám nhận lễ của cô nương?”

Nghe vậy, Thi Nghê khựng lại một chút, sau đó ánh mắt cố ý mờ mịt.

Nàng không chỉ đích danh bất kỳ ai, nhưng lời nói lại rõ ràng mang theo vài phần hàm ý.

“Thì ra là vậy. Chỉ là ban đầu khi mới vào doanh, vì lễ chế hai nước khác biệt, ta không biết phải hành lễ bái kiến thế nào mới hợp nghi, nên đã lần lượt hành lễ với người tiếp ứng. Khi ấy cũng không có ai nhắc nhở hành động này không ổn. Sau đó gặp lại, cũng đều là ta khuỵu gối trước, đối phương ở trên.”

Nghe lời này, Kinh Thiện lập tức nhíu chặt mày, giọng nói cũng lạnh xuống mấy phần.

“Ai ăn gan hùm mật báo vậy! Đón cô nương vào kinh là phụng thánh chỉ của bệ hạ, vậy mà có người dám ở ngay dưới mắt tướng quân tác oai tác phúc, chê mạng mình quá dài sao! Cô nương đừng cố kỵ, cứ yên tâm nói là ai, tướng quân tự sẽ công chính trách phạt.”

Thi Nghê trước là lộ vẻ kinh ngạc, sau đó lắc đầu, khoan hòa thay người kia giải vây:

“Đây không phải chuyện lớn gì, sao đến mức phải quấy rầy tướng quân. Sau này gặp lại, ta nhắc nhở các nàng là được.”

Kinh Thiện nói:

“Cô nương tự nhiên tâm thiện, chịu uất ức rồi vẫn chỉ muốn bao che cho người khác. Nhưng cô nương cho dù không nói, ta đại khái cũng đoán ra được. Có phải Phùng Chiêu, Phùng đại nhân không? Nàng ta dựa vào thế của trưởng công chúa, xưa nay mắt cao hơn đầu. Nhưng hiện giờ nơi này không phải công chúa phủ, mà là quân doanh Hoắc thị. Mặc kệ nàng ta quan giai mấy phẩm, đã sai quy củ thì nên chịu phạt.”

Nói đến đây, mục đích của Thi Nghê đã đạt được, cũng không cần tiếp tục giả vờ ngăn cản nữa. Vì vậy nàng khẽ mỉm cười, mang theo vẻ cảm kích mà nói:

“Vậy thì vất vả tướng quân, vất vả phó tướng, làm chủ chống lưng cho chúng ta rồi.”

Sau khi Kinh Thiện rời đi, vẻ mặt khiếp nhược vô tội của Thi Nghê chậm rãi thu lại.

Mười mấy năm qua, dù sao nàng cũng ở trong vương điện Tây Lương, ngày ngày làm bạn với sài lang hổ báo đội lốt người, sao có thể thật sự mềm yếu vô năng, vô duyên vô cớ mặc người ức hiếp?

Liên tục bị xâm phạm, nàng lười dây dưa với những kẻ vô nghĩa. Đã làm, thì chỉ làm một đòn đánh trúng chỗ hiểm.

…

Kinh Thiện làm việc nhanh gọn dứt khoát, quả nhiên không khiến Thi Nghê thất vọng.

Mới qua một đêm, những bất công trước đây nàng gặp phải trong doanh đều lần lượt truyền vào tai Hoắc Yếm.

Vốn dĩ nàng còn lo lắng, với thành kiến của Hoắc Yếm đối với mình, dù có chống lưng làm chủ, đại khái cũng chỉ trách mắng Phùng Chiêu vài câu ngoài miệng, sẽ không trách phạt rõ ràng, càng không thật sự làm lớn chuyện.

Nhưng điều khiến người ta không ngờ là, Hoắc Yếm trị quân cực nghiêm, trong mắt thật sự không chứa nổi một hạt cát.

Nghe nói hôm đó, hắn gọi Phùng Chiêu vào trướng trách hỏi hồi lâu, không biết đã nói gì. Đợi đến khi cửa trướng mở ra lần nữa, Phùng Chiêu đã mất hết thể diện, khóc đến đầy mặt nước mắt nước mũi.

Phùng đại nhân ngày thường nơi nơi uy phong trong doanh, khi ấy đã chẳng còn nửa phần uy nghi, mặt mũi càng mất sạch sẽ triệt để.

Nhưng càng khiến người ta không kịp phản ứng hơn là, chuyện đầu tiên Phùng Chiêu làm sau khi ra khỏi trướng, chính là trước mặt toàn quân trên dưới, hạ mình cúi đầu, đi đến cửa chiếc lều thấp chật hẹp mà nàng ta ban đầu sắp xếp cho Thi Nghê, khuỵu gối quỳ xuống.

Sau đó đợi Thi Nghê bước ra, nàng ta vang vang dập đầu với nàng ba cái thật sự rõ ràng.

Thi Nghê có vài phần sững sờ. Đối diện đại lễ dập đầu của Phùng Chiêu, nàng chỉ cảm thấy hơi không thích ứng.

Nhưng sau khi trấn định lại, trong lòng quả thật dâng lên vài phần sảng khoái như được hả giận.

A Giáng cũng đứng bên cạnh Thi Nghê. Vì chuyện trước đó, nàng bị thủ hạ của Phùng Chiêu quất mấy roi, khó tránh còn sợ hãi. Cho nên gặp lại Phùng Chiêu, nàng không khỏi tự nhiên sinh ra vài phần khiếp sợ.

Nhưng lúc này, với tư thế áp chế như vậy, nàng lại nhờ hào quang của cô nương, đồng dạng nhận được phần quỳ lễ này của Phùng Chiêu. Vì vậy nàng không tự chủ được mà ưỡn thẳng lưng, khôi phục vài phần thần thái và kiêu ngạo ngày trước.

Phùng Chiêu tiếp tục ngoài mặt phục tùng nhưng trong lòng không phục, cúi đầu nhận lỗi:

“Trước đây là ta bị mỡ heo che tâm, không biết thân phận tôn ti, vô lễ với cô nương. Lần này đặc biệt đến chịu đòn nhận tội, xin cô nương trách phạt.”

Chỉ nghe giọng nói căng cứng của nàng ta, nhìn sống lưng cứng đờ của nàng ta, liền biết lúc này Phùng Chiêu miệng nói một đằng lòng nghĩ một nẻo, không phục đến mức nào.

Nhưng điều đó không quan trọng. Thi Nghê không để ý nàng ta có thành tâm hay không, chỉ để ý nàng ta đã nhận chủ trước mặt mình. Sau này nàng ta dù có thần khí đến đâu, thân phận cũng là nô.

Không, nàng ta đã không còn thần khí nổi nữa.

Thi Nghê sẽ không được đằng chân lân đằng đầu. Đối phương đã nhận lỗi, nàng liền đúng lúc bày ra vẻ hiền hòa rộng lượng tha thứ, đồng thời giữ cao tư thái của mình.

Nhìn Phùng Chiêu cụp mắt âm thầm nghiến răng nghiến lợi, nàng liền càng cảm thấy khoan khoái.

Khổ tận cam lai. Thi Nghê thầm nghĩ, đây đại khái là khoảnh khắc hả lòng hả dạ nhất của các nàng kể từ khi vào doanh đến nay.

Ánh mắt rơi sang bên, dáng người Thi Nghê bỗng khựng lại.

Ở một góc xa xa không ai chú ý, Hoắc Yếm đang uy nghiêm đứng nhìn xuống, dễ dàng thu hết mọi việc xảy ra bên dưới vào mắt.

Không biết vì sao, mỗi khi có hắn ở đó, Thi Nghê lại cảm thấy mình không hiểu sao chẳng thể nâng nổi khí thế.

Tầm mắt nàng không kịp thu về, hai người bất ngờ đối diện nhau giữa không trung. Chỉ là vì khoảng cách hơi xa, vẻ mặt thần sắc của hắn đều có vẻ mơ hồ.

Rất nhanh, hắn xoay người, bóng dáng biến mất nơi khúc ngoặt.

Một vở náo nhiệt hư ảo rườm rà cuối cùng cũng hạ màn. Phùng Chiêu phẫn hận rời đi, mọi người cũng lần lượt tản ra.

Sau đó chưa được bao lâu, Kinh Thiện không biết từ đâu lén lút đi tới, lên tiếng quan tâm:

“Cô nương, ta đã nói tướng quân sẽ bảo vệ nàng, chống lưng cho nàng mà.”

“Bảo vệ ta?”

Ánh mắt Thi Nghê không khỏi khựng lại.

Kinh Thiện gật đầu, nhếch miệng cười:

“Ta vừa nói những uất ức cô nương phải chịu, tướng quân nghe xong thật sự không nể mặt chút nào, trực tiếp cầm kiếm hất tung quan bào của Phùng Chiêu, dọa nàng ta mềm nhũn chân ngay tại chỗ. Ngoài xin lỗi nhận phạt, tướng quân còn lệnh cho nàng ta tự tay xách nước đổ đầy toàn bộ năm chum nước lớn dùng cho nhà bếp. Phía sau còn có náo nhiệt để xem rồi.”

“À… tướng quân còn lột y phục nàng ta sao?”

Thi Nghê nhíu mày suy nghĩ một lúc lâu, lại bắt lấy trọng điểm này.

Nghe vậy, Kinh Thiện suýt nữa bị nước bọt làm sặc, vừa ho vừa vội xua tay phủ nhận:

“Chỉ là áo… áo ngoài thôi!”', '2026-06-01 15:49:41.446587+00'), (21, 4, 3, 'Chương 2: Ở lại biệt viện làm ngoại thất', 'Đông cung mà thế nhân kính ngưỡng, là nơi khoác trên mình áo gấm hoa lệ, quyền thế ngập trời.
Nhưng đối với Khương Dung Âm mà nói, Đông cung lại là cơn ác mộng của nàng, càng là chiếc lồng giam cầm nàng.
Bởi vì nơi ấy có Khương Quân.
Một kẻ hận nàng, giày vò nàng.
Trước cửa thiên điện Đông cung, Bảo Ngân bị ngăn lại.
Khương Dung Âm gượng nở một nụ cười, lắc đầu với nàng ấy.
Vừa bước vào trong điện, hơi nước mờ mịt đã suýt làm hoa mắt.
Trong bể tắm, Khương Quân quay lưng về phía cửa điện, nửa thân mình chìm trong nước.
“Điện hạ.”
Khương Dung Âm rụt rè gọi một tiếng, tựa vào cửa, không bước thêm về phía trước.
“Cô có thể ăn thịt nàng sao?”
“Lại đây.”
Tiếng nước ào lên. Khương Quân vươn tay đặt lên mép bể tắm.
Trên làn da màu lúa mạch là những vết sẹo chằng chịt ngang dọc.
Cữu cữu nhà họ Ngụy từng nói, sở dĩ Khương Quân khiến người ta khiếp sợ trên chiến trường, dựa vào chính là lối đánh không màng sống chết ấy.
Dù là một mình xông vào doanh trại địch, hay lấy một địch trăm vẫn trầm ổn vững vàng, đều không phải điều người bên cạnh có thể học được.
Đối với Khương Quân, những vết sẹo ấy càng giống như huân chương.
Trên bắp thịt rắn chắc còn có thể nhìn thấy gân xanh nổi lên, là sức mạnh bộc phát, cũng là sự khống chế tuyệt đối.
Sự áp bức chỉ riêng kẻ ở trên cao mới có khiến Khương Dung Âm càng không muốn bước tới.
“Cô không có nhiều kiên nhẫn đâu, Tiểu Cửu.”
Không nghe thấy tiếng bước chân của Khương Dung Âm, Khương Quân lại lên tiếng.
Lúc này Khương Dung Âm mới chậm rãi dịch từng bước về phía trước. Nàng vừa đi đến bên mép bể, tay Khương Quân đã nắm lấy cổ chân nàng.
Dù cách một lớp y phục, Khương Dung Âm vẫn cảm thấy bàn tay đang nắm cổ chân mình nóng rực đến mức khiến nàng khó chịu.
“Ta… ta giúp điện hạ kỳ lưng.”
Khương Dung Âm nhấc chân muốn lùi lại, nhưng Khương Quân không buông tay.
“Cần đến nàng sao?”
Dứt lời, Khương Dung Âm đã bị Khương Quân kéo xuống nước, làm bọt nước văng lên một mảng lớn, từng vòng gợn sóng lan ra.
“Khụ khụ.”
Bị sặc nước, Khương Dung Âm vội trồi đầu lên ho khan. Nàng mở mắt ra, một đôi mắt đen thẫm liền hiện ngay trước mặt.
Rõ ràng là nước ấm, nhưng chẳng hiểu vì sao, những ngón tay rơi trên người Khương Dung Âm lại mang theo hơi lạnh.
“Cô mới một tháng chưa về, tính tình Tiểu Cửu lại càng lúc càng to gan rồi.”
Đầu ngón tay hắn luồn vào trong áo nàng. Y phục thấm nước nổi lềnh bềnh trên mặt nước, ngược lại càng thuận tiện cho hắn.
Ánh mắt Khương Quân dời xuống, rơi trên mặt dây chuyền treo trước ngực nàng.
Là Tần Thời Ngôn tặng.
Khương Dung Âm yêu thích không rời tay, chưa từng tháo khỏi người.
Cũng phải, tiểu công tử nhà họ Tần và đích công chúa là thanh mai trúc mã cùng nhau lớn lên. Tất cả mọi người đều cho rằng, chuyện hai người thành thân sẽ không bao giờ thay đổi.
Thế nhưng lại cố tình xuất hiện một Khương Quân.
“Năm đó cô từng hỏi Tiểu Cửu, hòa thân với Đại Nguyệt, nếu nàng bằng lòng, cô sẽ không ngăn cản.”
“Chẳng phải chính nàng đã nói, nàng nguyện hầu hạ cô, bù đắp món nợ hơn mười năm qua sao?”
Đầu ngón tay hơi lạnh dời lên, tháo dây áo trong của nàng. Khương Dung Âm nghe những lời hắn nói, cả người đều run lên.
Mái tóc ướt sũng dính sát vào gò má nàng. Tiếng nước tí tách rơi xuống, nhất thời lại không phân rõ đó là nước hay là nước mắt.
Nàng hé môi, gượng nở một nụ cười.
“Dung Âm là người của điện hạ, không dám mơ tưởng điều gì khác. Là điện hạ khoan dung rộng lượng, không so đo chuyện Dung Âm chiếm lấy thân phận suốt mười sáu năm. Có thể ở lại trong cung hầu hạ điện hạ, Dung Âm đã cảm kích vô cùng.”
Những lời trái lòng ấy được nói ra có vài phần vấp váp.
Khương Quân nghe Khương Dung Âm nói, bàn tay dưới nước bóp lấy eo nàng, kéo người va vào trước ngực mình.
“Run cái gì? Sợ nói lời giả dối, ông trời sẽ không tha cho nàng sao?”
“Là lời thật lòng.”
Khương Dung Âm cúi đầu.
Nàng có thể nói gì đây?
Nói rằng năm đó, khi sứ thần Đại Nguyệt đến kinh thành cầu cưới công chúa, thật ra nàng đã bằng lòng sao?
Hay nói rằng nếu biết ở lại hoàng cung sẽ trở thành chim trong lồng của Khương Quân, nàng thà chết quách đi cho xong?
Thậm chí trong tình cảnh khi ấy, có thể được hòa thân rời đi, đối với Khương Dung Âm mà nói đã là một loại may mắn.
Người không cho nàng rời khỏi hoàng cung, là Khương Quân.
Đêm ấy, ánh trăng sáng soi lên nền điện Quang Hoa. Y phục bị Khương Quân xé nát rơi đầy đất, hắn nói, cho dù nàng có chết, cũng phải chết bên cạnh hắn.
Dựa vào đâu mà mười sáu năm khổ nạn lại do hắn gánh chịu, còn vinh hoa phú quý lại thuộc về Khương Dung Âm?
Đó là thứ Khương Dung Âm nợ hắn.
Khi ấy, Khương Dung Âm bị hắn giày vò đến mức nằm rạp trên giường. Màn lụa bị xé xuống trói chặt hai tay nàng lại với nhau, cổ tay non mềm bị mài đến bật máu.
Đôi mắt khóc đến đỏ hoe, giọng nói khàn đặc chỉ có thể lặp đi lặp lại một câu xin lỗi.
Dù rõ ràng đó không phải lỗi của nàng.
Nàng nói, điện hạ, xin lỗi.
Nàng nói, nàng bằng lòng rời khỏi hoàng cung, dù có đến am ni cô làm ni cô cả đời cũng được.
Người luôn không chịu buông tha cho nàng, vẫn luôn là Khương Quân.
“Chuyện của Tần Thời Ngôn, cô có thể xem như chưa từng xảy ra.”
“Tiểu Cửu, đây là cơ hội cuối cùng cô cho nàng, hiểu chưa?”
Khương Quân nâng cằm nàng lên, ép nàng đối diện với ánh mắt hắn.
Một ánh mắt tràn đầy tính xâm chiếm, không thể tránh né.
“Ta có thể… về Quang Hoa điện không?”
Bị hắn hôn đến đầu óc quay cuồng, Khương Dung Âm chỉ có thể bám vào cánh tay Khương Quân, cất lời cầu xin duy nhất ấy.
Ngày mai Học Tri quán còn có tiết học. Khương Dung Âm không muốn để người khác nhìn thấy nàng bước ra từ Đông cung.
Khương Quân là bảo bối trong lòng Ngụy hoàng hậu, là thiên chi kiêu tử của Đại Ung.
Còn nàng chẳng qua chỉ là một kẻ giả mạo không có chút quan hệ huyết thống nào, được giữ lại trong cung vì lòng tốt của Khương Quân.
Nếu để người khác cho rằng nàng quyến rũ Khương Quân, hại hắn làm ra chuyện trái luân thường, Ngụy hoàng hậu sẽ không bỏ qua cho nàng.
Một khi bị phát hiện, vì bảo toàn danh tiếng hoàng gia, Khương Dung Âm chỉ còn một con đường chết.
“Xem tâm trạng của cô.”
Khương Quân chỉ đáp lại nàng một câu như vậy. Sau đó hắn đổi hướng, Khương Dung Âm bị ép lên mép bể tắm. Mặt đá cuội bên dưới cấn vào người, vừa khó chịu vừa đau.
Nàng cắn môi không nói, nhìn bốn phía cửa sổ cửa điện đóng chặt, tựa như những bức tường cung cao ngất không thấy hy vọng. Dù nàng có biến thành chim, mọc ra đôi cánh, cũng chẳng thể bay ra ngoài.
Khương Dung Âm bỗng muốn khóc. Giọt lệ vừa rơi xuống đã bị đầu ngón tay Khương Quân lau đi.
Hắn cúi người, những ngón tay chen vào lòng bàn tay nàng, mạnh mẽ đan mười ngón tay với nàng.
“Cô thật sự đã muốn giết Tần Thời Ngôn.”
“Chỉ là giữ hắn lại, mới có thể nhắc nhở Tiểu Cửu của cô rằng, chuyện gì nên làm, chuyện gì không nên làm.”
Giữa từng đợt chìm nổi, lời Khương Quân từng chữ từng câu rơi bên tai Khương Dung Âm.
Hai bàn tay siết chặt đến mức khớp xương cũng kêu lên khe khẽ. Khương Dung Âm cong ngón tay, nhắm mắt nói:
“Ta biết sai rồi.”
Khương Quân không nói gì, chỉ dùng tay đỡ lấy thân thể nàng. Nước trong bể tắm dập dềnh lan ra hết vòng này đến vòng khác, nàng chỉ có thể dựa vào người hắn.
Không biết đã qua bao lâu, khi Khương Dung Âm mở mắt ra, bên ngoài đã lên đèn.
Đèn cung lay động trong gió. Nàng ôm một tấm chăn, co ro trong góc.
Khương Quân ngồi trước án thư cách đó không xa, trên người chỉ mặc một chiếc áo bào tơ tằm gấm Thục. Đai lưng buộc lỏng lẻo, để lộ vết cào trước ngực.
“Tỉnh rồi?”
Nghe thấy động tĩnh, Khương Quân nhìn về phía Khương Dung Âm. Sau đó, Khương Dung Âm nhìn thấy hắn đứng dậy.
Tấm chăn bị Khương Quân kéo đi. Hắn cởi giày bước lên giường, ôm nàng vào lòng.
“Điện hạ, ta nên về Quang Hoa điện rồi.”
Lòng bàn tay Khương Quân mang theo hơi ấm. Nghe Khương Dung Âm nói vậy, hắn vòng tay ôm lấy eo nàng, ánh mắt rũ xuống, tối tăm khó lường.
“Đi nổi sao?”
Chỉ một câu đã khiến Khương Dung Âm đỏ bừng mặt vì thẹn.
“Ngày mai Học Tri quán còn có tiết. Là tiết của Tang phu tử, nếu đến muộn sẽ bị mắng.”
Giọng Khương Dung Âm mềm nhũn bổ sung thêm một câu, sau đó quay mắt đi, không nhìn hắn nữa.
Con người Khương Quân này, khi hắn nhìn chằm chằm vào ngươi, dù ngươi có mặc y phục, cũng giống như chẳng mặc gì cả.
Ánh mắt hắn đầy tính xâm chiếm, tình dục ngập tràn tựa như sắp nhấn chìm Khương Dung Âm.
“Cô thật không biết, Tiểu Cửu lại yêu thích việc học đến vậy.”
“Mặc y phục đi, Hướng Minh sẽ đưa nàng về.”
Khương Quân nhìn chằm chằm Khương Dung Âm một lúc lâu, gần như muốn nhìn xuyên một lỗ trên đỉnh đầu nàng, rồi mới chịu nhả lời.
“Sau Yến Xạ yến, một khi định xong người được chọn làm Thái tử phi, cô sẽ đưa nàng ra khỏi cung.”
Khương Dung Âm đang ngồi đó mặc y phục, vừa nghe thấy lời này, hàng mày lập tức giãn ra.
Hắn chán rồi sao?
Chỉ là câu tiếp theo của Khương Quân lại khiến Khương Dung Âm như rơi xuống địa ngục.
“Mẫu hậu không thích nàng, vậy nàng cứ ở lại biệt viện làm ngoại thất đi.”', '2026-06-01 15:59:03.76115+00'), (22, 4, 4, 'Chương 3: Không làm chim hoàng yến của hắn', 'Khương Dung Âm không biết mình đã rời khỏi Đông cung bằng cách nào.

Vừa bước ra khỏi cửa điện, chân nàng đã trẹo một cái, suýt nữa ngã xuống. May mà Bảo Ngân kịp thời đỡ lấy nàng.

“Công chúa, người không sao chứ?”

Bảo Ngân nhìn những vết đỏ trên cần cổ trắng nõn của Khương Dung Âm, suýt nữa thì bật khóc.

Điện hạ lần nào cũng như vậy, chưa từng nghĩ cho công chúa. Những dấu vết này cũng không biết phải mấy ngày mới có thể tan hết.

Hướng Minh nhìn Khương Dung Âm thất thần lạc phách, không nói một lời đi theo sau hai người.

“Đừng đi theo ta!”

Dứt lời, Khương Dung Âm dừng bước, sau đó cúi đầu, buồn bực nói một câu:

“Ta có thể tự về.”

Hướng Minh nghe nàng nói vậy, không tiếp tục đi theo nữa.

Khương Dung Âm bước rất nhanh. Mãi đến khi ra khỏi Đông cung, nàng mới như mất hết sức lực, tựa người vào tảng giả sơn.

Ánh trăng dịu dàng soi sáng gương mặt đầy hoảng loạn của nàng. Nàng thở hổn hển từng hơi, rồi cúi đầu xuống.

Trong lòng bàn tay nàng xòe ra là mười vết máu hình bán nguyệt rõ ràng.

Khi nghe Khương Quân nói muốn đưa nàng ra khỏi cung làm ngoại thất, Khương Dung Âm thật sự rất muốn bất chấp tất cả, giết Khương Quân, hoặc giết chính mình.

Nhưng sau khi bình tĩnh lại, Khương Dung Âm cảm thấy người đáng chết không phải là nàng.

Nàng dùng đau đớn ép bản thân trấn định, để lại một câu “đều nghe theo điện hạ”, rồi mới có thể bước ra ngoài.

Ngoại thất.

Quả nhiên Khương Quân chưa từng định buông tha cho nàng.

Dù hắn sắp thành hôn, hắn cũng chưa từng nghĩ sẽ buông tha nàng.

“Công chúa, người còn ổn không? Có phải rất đau không?”

Bảo Ngân đỡ Khương Dung Âm, nhìn lòng bàn tay nàng đầy vết máu, ngay cả phần da thịt lộ ra ngoài cũng loang lổ vết đỏ.

“Nếu thật sự không chịu nổi, người cứ mềm giọng nhận thua với điện hạ, cầu điện hạ nhẹ tay một chút.”

Giọng Bảo Ngân nghẹn ngào. Nàng ấy chỉ hận bản thân chẳng giúp được gì.

Thái tử điện hạ là người chém giết bước ra từ núi thây biển máu, còn công chúa nhà nàng được nuôi trong thâm cung suốt mười sáu năm, đã từng chịu loại khổ sở này bao giờ?

Bảo Ngân chỉ sợ thân thể Khương Dung Âm bị Khương Quân giày vò đến sinh bệnh.

Khương Dung Âm nghe Bảo Ngân nói, nở một nụ cười thê lương.

“Nếu hắn thật sự quan tâm ta sẽ ra sao, hắn đã không làm những chuyện như vậy với ta.”

Hắn giữ nàng lại trên giường Đông cung, hôn lên đôi mắt khóc đỏ của nàng, hết lần này đến lần khác giày vò nàng.

Hắn nhất định phải ép nàng nói ra từng câu từng chữ khó mở miệng, cũng không chịu buông tha nàng.

Khương Quân xem nàng như món đồ chơi để trút giận. Trong tay hắn, nàng cũng chẳng qua chỉ là một món đồ chơi dùng khá thuận tay mà thôi.

Vậy nên hắn chưa từng để ý Khương Dung Âm sẽ ra sao.

Cho dù bị phát hiện, người phải chết cũng chỉ có Khương Dung Âm.

Chỉ là những lời hôm nay của Khương Quân khiến Khương Dung Âm không thể không tính toán lại.

Nàng tuyệt đối không thể làm ngoại thất của Khương Quân, càng không thể làm chim hoàng yến của hắn, cả đời bị nhốt ở nơi này.

Nàng nhất định phải chạy.

Hơn nữa còn phải khiến Khương Quân không bao giờ tìm thấy nàng nữa, khiến hắn hoàn toàn dập tắt ý định ấy mới được.

Chỉ là chuyện của Tần Thời Ngôn đã khiến Khương Quân càng thêm đề phòng. Khoảng thời gian này, nàng phải an phận thủ thường, khiến hắn yên tâm. Cũng vừa hay nhân cơ hội đó nghĩ xem mình còn đường lui nào khác.

“Về Quang Hoa điện thôi.”

Khương Dung Âm hít sâu một hơi, đứng thẳng người, dẫn Bảo Ngân trở về.

Sáng hôm sau, trời vừa tờ mờ sáng, Khương Dung Âm đã tỉnh lại.

Những vết đỏ trên người nàng đã bắt đầu chuyển thành màu xanh tím. Cố tình lúc này lại đang là mùa hạ, y phục mỏng nhẹ, cổ áo không thể che kín.

Nhất là dấu răng trên xương quai xanh kia, che thế nào cũng không giấu được.

Khương Dung Âm rũ mắt, cầm lấy cây trâm trên bàn trang điểm. Trong tiếng kinh hô của Bảo Ngân, nàng dùng trâm rạch nát dấu vết ấy.

Thứ Khương Quân để lại trên người nàng, nàng không muốn giữ lại bất cứ thứ gì.

Dấu răng này là thứ có thể lấy mạng nàng, nhưng Khương Quân lại chưa bao giờ quan tâm những dấu vết lưu lại trên người nàng có bị người khác phát hiện hay không.

“Công chúa, nô tỳ đi lấy thuốc trị thương.”

Bảo Ngân lau nước mắt, đứng dậy đi lấy thuốc.

Trong gương đồng phản chiếu gương mặt tái nhợt của Khương Dung Âm. Nàng cong môi cười, trông hệt như nữ quỷ chết thảm.

“Còn sống, thì vẫn còn hy vọng.”

Vậy nên nàng nhất định có thể trốn thoát, rời khỏi hoàng cung, rời khỏi Khương Quân.

Sau khi xử lý xong vết thương, trên cổ Khương Dung Âm quấn một lớp vải mỏng. Lúc này nàng mới dẫn Bảo Ngân đến Học Tri quán.

Học Tri quán là thư viện hoàng gia, chuyên dành cho các hoàng tử công chúa học tập.

Bên trong còn có con cái của đại thần trong triều vào làm bạn học.

Nếu là một năm trước, Khương Dung Âm đứng ở đó cũng là tồn tại được người người vây quanh như sao nâng trăng. Nhưng hiện giờ, nàng đứng nơi ấy, lại là người ai ai cũng tránh không kịp.

Khương Quân giữ nàng lại trong cung, nhưng chưa từng mở miệng che chở cho nàng.

Người bên ngoài vì muốn lấy lòng Thái tử điện hạ, đương nhiên sẽ chẳng có sắc mặt tốt đẹp gì với Khương Dung Âm.

Khương Dung Âm làm như không thấy những ánh mắt khác thường ấy, nhận lấy rương sách từ tay Bảo Ngân rồi bước vào.

Hai ngày trước Học Tri quán được nghỉ. Hôm nay là ngày đầu tiên mở lớp lại.

Chỉ là khi Khương Dung Âm đi đến chỗ ngồi của mình, nhìn thấy sách vở trên án thư bị xé nát, nỗi ấm ức bị đè nén mấy ngày qua cuối cùng cũng không nhịn nổi nữa.

“Ai làm?”

Nàng lạnh giọng hỏi một câu. Sau khi nhìn quanh một vòng, nàng chỉ thấy Lục công chúa Khương Tuyết Bình đang nhìn mình với vẻ đắc ý.

Mẹ ruột của Khương Tuyết Bình là Vạn chiêu nghi, thuộc phe Ngụy hoàng hậu. Vì vậy, trong Học Tri quán, Khương Tuyết Bình luôn nhắm vào Khương Dung Âm.

Nàng ta lấy việc bắt nạt Khương Dung Âm làm vui. Nhưng phần lớn thời điểm, nàng ta làm vậy là để lấy lòng Khương Quân.

Vì quan hệ giữa Vạn chiêu nghi và Ngụy hoàng hậu, Khương Quân cũng sẽ nhìn Khương Tuyết Bình nhiều hơn một cái.

Chỉ là Khương Dung Âm cảm thấy, Khương Quân nhìn Khương Tuyết Bình, là vì cảm thấy nàng ta ngu xuẩn.

“Khương Tuyết Bình, là ngươi làm?”

Ánh mắt Khương Dung Âm khóa chặt trên người Khương Tuyết Bình. Nàng đặt mạnh rương sách trong tay xuống án thư, rồi bước về phía nàng ta.

Khương Tuyết Bình nhìn gương mặt trầm xuống của Khương Dung Âm, lại thấy trong đôi mắt trong trẻo kia còn mang theo tức giận, liền đứng dậy.

“Khương Dung Âm, ngươi đừng có vu oan cho ta.”

“Đồ của mình tự giữ không cẩn thận, còn có thể trách lên đầu ta sao?”

Khương Dung Âm nghe Khương Tuyết Bình nói vậy, không phản bác nàng ta, chỉ từng bước đi về phía nàng ta, cho đến khi ép Khương Tuyết Bình lùi vào góc.

“Xin lỗi ta.”

“Dựa vào cái gì?! A! Khương Dung Âm, con chó điên này, buông ta ra!”

Ngay khi Khương Tuyết Bình định vươn tay đẩy Khương Dung Âm, Khương Dung Âm trực tiếp giơ tay túm lấy tóc nàng ta.

Một lần rồi lại một lần, dù là tượng đất cũng còn có ba phần nóng nảy.

Lần trước Khương Tuyết Bình đập vỡ nghiên mực của nàng. Lần này lại xé sách của nàng, muốn nhìn nàng mất mặt, để giẫm lên thể diện của nàng mà đi tranh công với Khương Quân sao?

Chẳng bao lâu sau, hai người đã giằng co đánh nhau thành một đoàn. Nếu không phải những người khác chạy tới ngăn lại, e rằng Khương Tuyết Bình đã bị Khương Dung Âm cưỡi lên người mà đánh rồi.

“Khương Dung Âm, ngươi đúng là đồ điên! Ta sẽ nói với hoàng huynh, ngươi chết chắc rồi!”

Khương Tuyết Bình ôm gương mặt bị Khương Dung Âm tát đến đỏ sưng, vừa khóc vừa gào đòi đi tìm Khương Quân.

Khương Dung Âm đứng đó với mái tóc rối bù, giống như một con hổ con bướng bỉnh, nhìn chằm chằm vào Khương Tuyết Bình.

“Có chuyện gì mà ồn ào vậy?”

Khi hai bên còn đang tranh chấp không ngừng, một giọng nói ôn hòa đúng mực nhưng lại mang theo vài phần uy nghiêm truyền đến.

Mọi người quay đầu nhìn ra cửa, sau đó đồng loạt chắp tay hành lễ.

“Thịnh tiên sinh.”

Khương Dung Âm ngẩng đầu, đối diện với đôi mắt ôn hòa của Thịnh Hoài An.

“Tiên sinh! Khương Dung Âm ra tay đánh ta ở Học Tri quán.”

Khương Tuyết Bình vừa nhìn thấy Thịnh Hoài An, trong lúc hoảng loạn còn không quên chỉnh lại dung mạo, vừa khóc sướt mướt vừa đi về phía Thịnh Hoài An.

“Cửu công chúa, có đúng như vậy không?”

Trong tay Thịnh Hoài An cầm một quyển sách. Nghe vậy, hắn nhìn về phía Khương Dung Âm, hỏi một câu.

Khương Dung Âm hơi sững lại. Nàng vốn tưởng Thịnh Hoài An sẽ trực tiếp trách phạt mình, không ngờ hắn lại mở miệng hỏi.

Nàng cúi đầu đáp:

“Nàng ta xé sách của ta, nhất thời ta tức không nhịn được.”

Quyển sách bị xé nát ấy chẳng khác nào thể diện của nàng, bị Khương Tuyết Bình giẫm nát dưới chân.', '2026-06-01 16:00:05.681113+00'), (23, 4, 5, 'Chương 4: Tiểu Cửu của cô, chỉ vậy mà thôi', 'Ánh mắt Thịnh Hoài An dừng trên gương mặt bướng bỉnh của cô nương.

Vệt mực đen loang lổ dính trên gương mặt trắng nõn của Khương Dung Âm. Nàng cúi đầu nói xong câu ấy rồi không nói gì thêm.

“Lục công chúa làm hỏng sách vở của đồng môn, Cửu công chúa ra tay với đồng môn ở Học Tri quán. Vậy phạt mỗi người chép Luận Ngữ mười lần, xem như răn dạy nhẹ.”

Nghe Thịnh Hoài An nói vậy, Khương Tuyết Bình lập tức trợn to mắt.

“Tiên sinh! Người phạm lỗi rõ ràng là Khương Dung Âm…”

“Nhạn bay qua còn để lại vết, gió thổi qua còn lưu lại tiếng. Chỉ cần là chuyện con người từng làm, đều sẽ để lại dấu tích.”

“Nếu Lục công chúa muốn ta điều tra kỹ chuyện này, cũng không phải là không được.”

Khóe môi Thịnh Hoài An hơi cong lên, nhưng ánh mắt nhìn Khương Tuyết Bình lại mang theo vài phần áp bức.

Ánh mắt Khương Tuyết Bình thoáng né tránh trong chớp mắt, cuối cùng không nói thêm gì nữa.

Trận náo loạn ở Học Tri quán cứ thế kết thúc.

Thịnh Hoài An giao bài học xong, liền cho bọn họ rời đi.

Khi Khương Dung Âm bước ra khỏi Học Tri quán, nàng nhìn thấy Khương Tuyết Bình hung hăng trừng mình một cái.

“Công chúa, người… người bị sao thế này?”

Bảo Ngân nhìn mái tóc rối bù của Khương Dung Âm, ngay cả chiếc váy màu xanh non cũng dính đầy vết mực.

Rốt cuộc là đi học hay là đi đánh nhau vậy?

“Không sao, chúng ta về Quang Hoa điện thôi.”

Khương Dung Âm giơ tay lau mặt, mực đen dính đầy tay.

Nhưng tâm trạng nàng lại nhẹ nhõm hơn rất nhiều.

Khương Tuyết Bình bắt nạt nàng ở Học Tri quán không phải chỉ mới ngày một ngày hai. Trước kia, Khương Dung Âm không muốn làm lớn chuyện nên đều nhịn xuống.

“Ta còn thấy khá vui.”

Khương Dung Âm cong mắt, mỉm cười với Bảo Ngân.

Xuân hòa cảnh sáng, hàng mày giãn ra của cô nương như chứa đựng những tia sáng vụn vỡ.

Bảo Ngân đã rất lâu không nhìn thấy Khương Dung Âm cười.

Dường như kể từ khi Thái tử điện hạ trở về, công chúa chưa từng có lúc nào nhẹ nhõm thoải mái như vậy nữa.

Hai người trở về Quang Hoa điện. Bảo Ngân hầu hạ Khương Dung Âm tắm rửa, sau đó ra ngoài lấy y phục thay cho nàng.

Khương Dung Âm tựa đầu lên thành thùng tắm, thoải mái nhắm mắt gọi một tiếng:

“Bảo Ngân.”

Tiếng bước chân chậm rãi truyền đến, không nhẹ nhàng như Bảo Ngân, chỉ là Khương Dung Âm không nghĩ nhiều.

Có người nắm lấy cánh tay nàng đang đặt sang một bên.

“Ngươi dùng sức mạnh quá, đau.”

Khương Dung Âm nhíu mày, lập tức mở mắt ra. Đôi mắt đen thẫm của Khương Quân đã ở ngay trước mặt.

Hắn ngồi trên giá hoa cạnh thùng tắm.

Thân hình nam nhân cao lớn, chiếc giá hoa cao nửa người, Khương Quân vừa ngồi lên đã che khuất hoàn toàn Khương Dung Âm.

Thấy Khương Dung Âm mở mắt, nàng co người lại, muốn rút tay về.

Khương Quân cong môi cười nhạt, năm ngón tay buông lỏng rồi lại siết chặt, lập tức kéo người đến trước mặt mình.

Hắn khom lưng, tầm mắt lướt qua thân thể nàng dưới làn nước.

“Đánh nhau với Khương Tuyết Bình ở Học Tri quán?”

Ánh mắt Khương Quân quay lại, rơi trên vết cào nơi gương mặt trắng sạch của nàng.

Tuy nói sức chiến đấu của Khương Dung Âm hơn hẳn, đè Khương Tuyết Bình ra mà đánh, nhưng cũng không phải hoàn toàn không bị thương chút nào.

Mái tóc ướt sũng dính sát vào mặt Khương Dung Âm. Hơi nước mịt mờ bốc lên, một tiếng tí tách vang lên khi giọt nước rơi xuống mặt nước.

“Điện hạ muốn trừng phạt ta thay Lục công chúa sao?”

Cổ họng Khương Dung Âm hơi nghẹn lại.

Rốt cuộc Khương Quân đã cài bao nhiêu người? Chuyện ở Học Tri quán đến giờ còn chưa được một canh giờ, vậy mà hắn đã biết rồi.

“Đúng là nên phạt.”

“Để tránh cho Tiểu Cửu không biết trời cao đất dày, lúc nào cũng gây chuyện sinh sự.”

Khương Quân buông nàng ra, đáy mắt nhiễm vài phần lạnh lẽo.

Ánh xuân rơi vào trong phòng dường như trong khoảnh khắc này cũng hóa thành màu xám trắng. Nàng trước nay chưa bao giờ là người gây chuyện sinh sự.

Khương Dung Âm rũ mắt.

“Là nàng ta động vào đồ của ta trước.”

Một quyển sách, một nghiên mực, Khương Dung Âm đều có thể không so đo.

Nhưng thứ Khương Tuyết Bình muốn nhìn thấy là dáng vẻ nàng khó xử, là cảnh nàng bị người ta chê cười, là cảnh tôn nghiêm của nàng bị giẫm nát dưới chân.

Đây mới là điều Khương Dung Âm không thể nhẫn nhịn.

“Cô đã nói rồi, tính tình nàng càng lúc càng lớn.”

“Nàng ta là công chúa, còn nàng là gì?”

Tay Khương Quân đặt lên đỉnh đầu Khương Dung Âm, những ngón tay xuyên vào mái tóc đen nhánh của nàng.

Nghe thấy câu này, Khương Dung Âm ngẩng đầu đối diện ánh mắt Khương Quân. Nàng không đáp lời.

Một đôi mắt ướt sũng, bướng bỉnh, không cam lòng, nhưng lại không thể phản kháng.

“Ta là vì điện hạ lương thiện nên mới được giữ lại…”

“Nàng là Tiểu Cửu của cô, chỉ vậy mà thôi.”

Khương Quân cắt ngang lời Khương Dung Âm. Hai chữ “hàng giả” cứ thế bị chặn cứng trong cổ họng nàng.

Khương Dung Âm quay mặt đi.

Nàng chẳng là gì cả.

Không phải Tiểu Cửu của Khương Quân, cũng không phải Cửu công chúa của Đại Ung.

Nàng là chính nàng.

Nàng là Khương Dung Âm.

“Ngày mai không cần đến Học Tri quán nữa.”

Khương Quân nhàn nhạt buông xuống câu này. Hắn đi Giang Nam một chuyến, trở về rồi, nàng ngược lại đã sinh ra không ít tâm tư khác thường.

“Vì sao? Ta… ý ta là, việc học vẫn chưa kết…”

Khương Dung Âm quay đầu lại, không biết câu nào vừa rồi của mình lại chọc giận hắn, khiến hắn tước đoạt cả quyền được đến Học Tri quán học của nàng.

“Không chỉ ngày mai không cần đi, trước Yến Xạ yến nàng đều không cần đi nữa.”

Khương Quân đứng dậy. Khương Dung Âm nhìn hắn tháo đai lưng, ngọc thạch va vào nhau phát ra tiếng leng keng.

Sau đó là áo khoác ngoài, áo ngoài, rồi lớp áo bên trong…

“Nhưng ta muốn đến Học Tri quán. Nếu không biết chữ, ta cũng không thể hầu hạ điện hạ cho tốt.”

Khương Dung Âm nghe giọng điệu không cho phép phản bác của hắn, trong lòng càng thêm căng thẳng.

Đến Học Tri quán là cơ hội duy nhất để nàng tiếp xúc với bên ngoài.

Muốn trốn khỏi hoàng cung, muốn sống trong thế giới bên ngoài, Khương Dung Âm không thể cái gì cũng không biết.

Khương Quân tháo hộ giáp trên cổ tay, xoay người đi về phía nàng.

“Nàng dùng tay để hầu hạ sao?”

Ý ngoài lời chính là, biết chữ hay không cũng chẳng quan trọng.

“Một năm nay, thuật cưỡi ngựa bắn cung của nàng chẳng tiến bộ chút nào, những chỗ khác ngược lại tiến bộ không ít. Muốn ở Yến Xạ yến bị người ta xem như bia sống sao?”

Vừa nói, Khương Quân đã bước vào thùng tắm. Nước đầy tràn đổ ra khắp sàn, ánh mắt hắn vẫn như trước, ngập đầy dục vọng.

Thùng tắm chỉ lớn chừng ấy, Khương Dung Âm ngay cả chỗ để lùi cũng không có, trực tiếp bị Khương Quân ôm gọn vào lòng.

“Điện hạ muốn dạy ta cưỡi ngựa bắn cung sao?”

Đôi mắt Khương Dung Âm hơi mở lớn. Khương Quân cúi đầu, nụ hôn rơi xuống bên tai nàng.

“Tần Thời Ngôn cũng ở đó. Chẳng phải Tiểu Cửu có lời muốn nói với hắn sao?”

Không đợi Khương Dung Âm nói thêm, Khương Quân đã khiến nàng im bặt.

Không sao.

Bất kể Khương Dung Âm có tâm tư gì, hắn cũng sẽ từng chút một bóp chết tất cả.

Đêm xuống, khi Khương Dung Âm mở mắt ra, ánh nến lúc tỏ lúc mờ lay động qua lại. Nàng kéo chăn một chút. Bảo Ngân đang canh bên ngoài lập tức mở mắt đứng dậy đi vào.

“Công chúa khát nước sao?”

Trên giường, sau lưng Khương Dung Âm lại thêm một mảng xanh tím. Quả thật là vết thương cũ chưa lành đã chồng thêm vết thương mới.

Nghe Bảo Ngân hỏi, Khương Dung Âm gật đầu.

Đợi Bảo Ngân bưng nước tới, Khương Dung Âm uống cạn chén nước từ tay nàng ấy.

“Mấy giờ rồi?”

“Đã giờ Dần rồi. Khi điện hạ rời đi có dặn hôm nay công chúa không cần đến Học Tri quán, bảo người ở Quang Hoa điện nghỉ ngơi cho tốt.”

Bảo Ngân giúp nàng kéo lại góc chăn. Nghĩ đến lúc mình đứng ngoài điện nghe thấy tiếng khóc của Khương Dung Âm, trong lòng nàng ấy phức tạp khó tả.

Nay điện hạ càng lúc càng không kiêng dè, đã đuổi tới tận Quang Hoa điện rồi.

“Bảo Ngân, ngươi giúp ta đến Học Tri quán lấy một quyển sách về.”

“Chính là quyển trước đó Lâm tiểu thư cho ta mượn, ta đặt dưới án thư.”

Đó là huyện chí Bồng Khê, Đinh Châu.

Là thứ Lâm tiểu thư mang đến từ Đinh Châu.

Khương Dung Âm từng nghĩ, nếu đã chạy thì phải chạy thật xa.

Mà Đinh Châu cách kinh thành ngàn dặm.

Lâm tiểu thư từng nói, nơi đó dân trí chưa khai hóa, thôn dân chất phác, rất dễ chung sống. Vậy nên cho dù nàng không có sổ hộ tịch và lộ dẫn, nàng cũng có thể sống sót ở Đinh Châu.

Chỉ cần không dùng đến sổ hộ tịch, cả đời này Khương Quân cũng sẽ không tra ra được nơi nàng đi.', '2026-06-01 16:06:28.123929+00'), (24, 4, 6, 'Chương 5: Đừng vọng tưởng thứ không thuộc về mình', 'Bảo Ngân gật đầu, lại đút cho Khương Dung Âm uống thêm một chén nước, lúc này mới đi ra ngoài.

Khương Dung Âm xoay người, nhắm mắt ngủ thêm một canh giờ. Đợi nàng mở mắt lần nữa, Bảo Ngân đã lấy quyển huyện chí Bồng Khê về.

Nàng nằm trên giường, nhìn những chỗ trước đây mình từng đánh dấu.

Trong cung mỗi năm đều tổ chức Yến Xạ yến, địa điểm nằm ở khu săn bắn hoàng gia trên núi Tây Giao.

Trước đây Khương Dung Âm từng đến đó, biết bên ngoài hàng rào chính là cả một vùng núi Tây Giao hoàn chỉnh.

Phía đông và phía tây nối liền với dãy Ngọc Hành, núi non kéo dài không dứt. Trong mắt người ngoài, đó là nơi mênh mông không thấy điểm cuối, nhưng đối với Khương Dung Âm mà nói, đó là hy vọng sống.

Yến Xạ yến chính là cơ hội để nàng trốn thoát.

Trước đây nàng từng nghĩ, nếu có thể được ban hôn ra ngoài, có thánh chỉ của Hoàng đế che chở, cũng có thể kiềm chế được Khương Quân.

Trước mắt kế hoạch đã thất bại, nàng chỉ có thể dùng cách này.

Ngoài việc quyết định sẽ đến Đinh Châu, Khương Dung Âm còn phải chuẩn bị một ít bạc vụn, hoạch định xong lộ trình, cũng như sắp xếp ổn thỏa tất cả mọi chuyện sau đó.

Nàng cất sách đi, lại nhắm mắt lại.

Tuy chuyện phải làm còn rất nhiều, nhưng chỉ cần nghĩ đến việc có thể thoát khỏi Khương Quân, tâm trạng Khương Dung Âm không khỏi có chút vui vẻ.

Sau giờ Ngọ, Khương Dung Âm vừa dùng xong bữa trưa thì nghe Bảo Ngân nói Hướng Minh tới.

“Điện hạ đang ở đình bắn cung, mời công chúa qua đó.”

Truyền lời xong, trong tay Bảo Ngân còn ôm bộ y phục cưỡi ngựa bắn cung mà Khương Quân sai Hướng Minh mang tới.

Hắn ngược lại hiểu rất rõ vóc dáng Khương Dung Âm, một bộ y phục may vô cùng vừa vặn.

Tuy Khương Dung Âm không muốn để ý đến Khương Quân, nhưng sau chuyện trước đó, hắn đã sinh lòng cảnh giác.

Nếu chống đối, trái lệnh hắn, Khương Dung Âm sợ Khương Quân lại làm ra chuyện khác, trực tiếp cắt đứt cơ hội ra ngoài của nàng.

Đợi khi Khương Dung Âm không tình nguyện đi đến đình bắn cung, từ xa đã nhìn thấy mấy bóng người.

Thiếu niên phong thái hăng hái đặt tay lên trường cung, sau đó một mũi tên bắn ra, trúng ngay hồng tâm.

“Kỹ thuật cưỡi ngựa bắn cung của Tần công tử lại tiến bộ rồi.”

“Có muốn cùng chơi mã cầu không?”

Vài tiếng khen ngợi vang lên. Khương Dung Âm siết chặt cung tên trong tay mình.

Chỉ là vừa xoay người, nàng đã đâm thẳng vào lồng ngực một người.

“Đi đâu?”

Hộ giáp trên người Khương Quân va vào trán Khương Dung Âm, khiến nơi đó ửng đỏ một mảng, còn hơi đau.

“Đi tìm điện hạ.”

Nghe thấy giọng hắn, Khương Dung Âm lùi về sau một bước, kéo giãn khoảng cách rồi đáp lời.

Thì ra đây chính là câu hôm qua hắn nói, Tần Thời Ngôn cũng ở đây.

Khương Dung Âm không hiểu vì sao Khương Quân nhất định phải kéo nàng đến nơi này. Chỉ để xem nàng còn có gan nói chuyện với Tần Thời Ngôn hay không sao?

“Lại đây, cô dạy nàng cưỡi ngựa bắn cung.”

Khương Quân không nói nhiều, chỉnh lại hộ giáp trên cổ tay đang ánh lên sắc lạnh rồi chỉ để lại cho Khương Dung Âm một câu ấy.

Khương Dung Âm nhìn thấy mấy vị công tử ca vừa rồi còn nhàn tản, sau khi nhìn thấy Khương Quân thì thái độ lập tức trở nên cung kính vô cùng.

Nàng thầm thở dài trong lòng, bước lên phía trước.

Ánh mắt thiếu niên lập tức rơi trên người Khương Dung Âm, nhưng rất nhanh lại dời đi.

Trong lòng Khương Dung Âm chua xót, trên mặt lại lộ ra một nụ cười.

Không thể để Khương Quân nhìn ra manh mối.

Tuyệt đối không thể.

Sau đó, một bàn tay vươn tới nắm lấy tay cầm cung của nàng. Khương Quân nhìn về phía nhóm Tần Thời Ngôn, nói:

“Các ngươi cứ tự nhiên. Cô còn phải dạy Tiểu Cửu.”

Lời này vừa rơi xuống, ánh mắt Khương Quân nhìn về phía Khương Dung Âm. Nàng ngược lại nhìn thẳng phía trước, từ đầu đến cuối không liếc về phía Tần Thời Ngôn lấy một cái.

“Thời Ngôn, mấy ngày nữa có phải huynh phải đến nhà họ Sở cầu thân không?”

Phía xa có người hỏi một câu, lời nói theo gió bay vào tai Khương Dung Âm.

“Lúc cô từ Giang Nam trở về, nghe người nhà họ Sở nói, Tần Thời Ngôn đã hủy hoại trong sạch của tiểu thư nhà họ Sở, muốn cô đứng ra làm chủ.”

Giọng Khương Quân cũng đồng thời vang lên, mang theo tay Khương Dung Âm cùng nâng lên.

Mũi tên sắc bén hướng thẳng về phía người rơm cách đó không xa.

“Tiểu Cửu cảm thấy, cô là phá hoại nhân duyên của người khác, hay là tác thành chuyện tốt cho người ta đây?”

Bên tai Khương Dung Âm là từng câu từng chữ Khương Quân rơi xuống.

Hắn đang thử xem trong lòng nàng còn có Tần Thời Ngôn hay không.

Hoặc là, cho dù có, cũng đừng vọng tưởng thứ không thuộc về nàng.

Muốn thoát khỏi hắn cũng được, trong lòng có người khác cũng chẳng sao.

Chỉ cần Khương Quân không buông tay, nàng nơi nào cũng không đi được.

Khương Dung Âm giống như con diều bị Khương Quân nắm chặt dây. Thi thoảng dây thả lỏng một chút, nàng liền muốn bay thật xa. Nhưng người giữ dây chỉ cần kéo nhẹ một cái, đã có thể kéo nàng trở về lần nữa.

“Điện hạ làm đúng. Trong sạch của nữ tử lớn hơn trời.”

Khương Dung Âm trầm giọng nói một câu, giọng nói không nghe ra điều gì khác thường.

Khương Quân khẽ cười, nhìn Khương Dung Âm buông tay đang giữ mũi tên, hỏi nàng:

“Đành lòng buông tay rồi?”

“Cung đã kéo căng rồi, điện hạ.”

Cung đã căng mà không buông, người bị thương chỉ có thể là chính nàng.

Tần Thời Ngôn có thể giữ được một mạng trong tay Khương Quân đã là chuyện không dễ dàng.

Khương Dung Âm không thể gây thêm phiền phức cho hắn nữa. Sau này cứ xem như không quen biết, để hắn sống cho tốt.

Mũi tên vút một tiếng bay ra, xuyên thủng cả đầu người rơm. Lực bắn mạnh đến mức thân thể Khương Dung Âm cũng không khỏi nghiêng về sau.

“Hạ bàn không vững, chẳng trách chẳng bao lâu đã kêu mệt.”

Khương Quân đứng đó, giống như một ngọn núi, sừng sững bất động.

Chỉ là những lời hắn nói ra khiến Khương Dung Âm thật muốn trở tay ném thẳng cây cung này vào mặt hắn.

“Tự luyện thêm nửa canh giờ.”

Khương Quân nhìn vẻ mặt muốn nói lại thôi của Khương Dung Âm, ý cười trên mặt càng sâu hơn.

Vừa hay lúc này Hướng Minh đi tới nói có chuyện quan trọng, hắn liền rời đi.

Khương Dung Âm cầm trường cung kia, lại lắp thêm một mũi tên.

Chỉ là còn chưa đợi nàng bắn ra, một tiểu thái giám cầm ống tên trong tay bỗng làm rơi xuống đất.

Mấy mũi tên lông dài lăn đến bên chân Khương Dung Âm.

Nàng cúi người nhặt lên, chỉ nghe thấy một câu:

“Tần công tử đang ở chỗ giả sơn.”

Không đợi Khương Dung Âm kịp phản ứng, tiểu thái giám đã nhặt hết tên rồi rời đi.

Khương Dung Âm ngước mắt. Sau tảng giả sơn cách đó không xa lộ ra một góc áo bào màu xanh.

Nàng thu hồi tầm mắt, không nhìn sang đó nữa.

Mãi đến khi Khương Quân quay lại, Khương Dung Âm vẫn luôn luyện bắn tên.

Nam nhân bất động thanh sắc liếc mắt nhìn tảng giả sơn một cái, rồi vươn tay đặt lên đầu Khương Dung Âm.

“Đi thôi.”

“Không luyện nữa sao?”

“Không muốn giữ cánh tay nữa à?”

Nghe Khương Quân nói vậy, Khương Dung Âm mím môi một cái, đặt trường cung xuống.

Nàng lờ mờ biết Tần Thời Ngôn muốn nói gì với nàng.

Nhưng đây là hoàng cung. Một người kín kẽ như Khương Quân, dục vọng khống chế lại cực mạnh, nhìn như đã rời đi, nhưng bên cạnh Khương Dung Âm chắc chắn có tai mắt của hắn.

Nàng dám đi gặp Tần Thời Ngôn, Khương Quân liền có thể khiến nàng ba ngày không ra khỏi cửa Quang Hoa điện được, cũng không rời khỏi chiếc giường kia được.

Đợi Khương Quân và Khương Dung Âm rời đi, Tần Thời Ngôn đứng sau tảng giả sơn mới bước ra.

Thiếu niên rũ mắt, trên mặt lộ ra vài phần chua xót.

Hắn muốn giải thích với Khương Dung Âm rằng hắn không hề chạm vào Sở Thanh Âm, càng không muốn cưới nàng ta.

Nhưng Sở Thanh Âm là người Khương Quân muốn hắn cưới. Mục đích chính là khiến hắn và Khương Dung Âm không còn khả năng nào nữa.

“Công tử, đại nhân bảo người về. Nói là… người nhà họ Sở tới rồi.”

Lời của gã sai vặt khiến Tần Thời Ngôn đấm một quyền lên tảng giả sơn, khớp xương ngón tay cũng bật máu.

Nhà họ Sở phái người tới còn có thể là vì chuyện gì nữa?

Hắn không muốn cưới Sở Thanh Âm, thà rằng tòng quân, hoặc đến chùa làm hòa thượng.

Nhà họ Sở đến là để gây áp lực cho Tần Thời Ngôn.

“Công tử, người!”

Gã sai vặt Tùy Phong nhìn vết thương của Tần Thời Ngôn, kinh hô một tiếng. Sau đó liền thấy Tần Thời Ngôn nhấc chân rời đi.

Lúc này trong Quang Hoa điện, Khương Quân đang ấn Khương Dung Âm lại để nàng bôi thuốc cho hắn.

Mấy ngày trước ngược lại không phát hiện vết thương trên người hắn. Vậy mà hắn vẫn còn dư sức giày vò Khương Dung Âm sống dở chết dở.

“Tiểu Cửu, nàng đây là mượn việc công báo thù riêng sao?”

Khương Dung Âm trực tiếp đổ cả lọ thuốc bột xuống, cũng chẳng thèm quan tâm Khương Quân có đau hay không, cầm lấy băng gạc định băng bó cho hắn.

Đau sao?

Đau là đúng rồi.

Tốt nhất là đau đến mức hắn cũng sống dở chết dở, dập tắt cái tâm tư giày vò nàng đi.', '2026-06-01 16:13:03.462654+00');